// HaTi — extracted module (E0). Globals are window-attached on
// purpose: the app is written against a single global scope (inline
// onclick handlers, cross-module calls); modules give file isolation
// for editing, not scope isolation.
/* ============================================================ STATE */
window.FIRST_PARTY = 'Highland Corporate Ltd'; // replaced by the workspace org name at login
window.PORTAL_MODE = false;                     // true when rendering the counterparty share portal

/* ---- WHO WE ARE ON THIS AGREEMENT, WHICH IS NOT THE SAME AS WHO WE ARE ----
   Reported by the owner (11 Aug 2026): "when drafting a contract, you should
   have the option to state who the owner / party to the contract is along with
   the counterparty. Currently, the owner ends up being the person signed into
   the account, which is incorrect." And the reason, which is the part that
   settles the design: "even though I may work for West Electronics, within
   West Electronics there might be subdivisions of the business or different
   legal entities. Therefore the assumption should not be that the company is
   automatically the party to the contract."

   TWO FACTS THAT LOOKED LIKE ONE. FIRST_PARTY is the WORKSPACE — the
   organisation whose seat you are sitting in. It is right for everything the
   platform says about itself: who sent a link, whose colleagues a note stays
   inside, which company the Copilot is acting for, what the evidence pack was
   generated by. c.party is the LEGAL ENTITY named on THIS agreement, and it is
   right for everything the DOCUMENT says: the recital, "Between A and B", the
   signature block, the executed copy.

   Until now there was only the first, so every contract a group drafted named
   the holding company on its paper whatever entity was actually contracting.

   THE LINE IS: does the DOCUMENT name us, or does the PLATFORM? Document reads
   contractParty(c); platform stays FIRST_PARTY. Nothing here changes for a
   business with one entity — an unanswered party falls back to the workspace,
   which is exactly what every existing contract already says. */
const contractParty = c => {
  const p = String((c && c.party) || '').trim();
  return p || window.FIRST_PARTY || '';
};

Object.assign(window,{FIRST_PARTY,PORTAL_MODE,contractParty});

window.uid = 100;
const nextId = () => 'MK-' + (++uid);
const seedComments = () => ([
  { author:(typeof jxEg==='function'&&jxEg('reviewer'))||'Wanjiku Kamau', role:'Editor (Internal)', side:'internal',
    text:`Flagged clause 4 — please confirm the governing-law reference stays ${(typeof jxAdjective==='function'?jxAdjective():'Kenyan')}.`, ts:'2d ago' },
  { author:'Counterparty', role:'Reviewer', side:'external', text:'Agreed on scope. We will need the value confirmed before counsel signs off.', ts:'1d ago' },
]);

