function approveContract(c){
  if(!approvalState(c).canApprove){ toast(i18t('co_no_approver_rights'),'err'); return; }
  const u=currentUser();
  c.approval={ by:u.name, byId:u.id, role:ROLE_LABEL[u.role], at:nowISO() };
  logAudit(c,'Approved',`Approved for signing by ${u.name} (${ROLE_LABEL[u.role]})`);
  persist(c); renderSignButton(c); renderAuditSection(c);
  toast(i18t('co_contract_approved'));
}

/* ---------- workspace / auth ---------- */
const getOrg = () => REMOTE ? REMOTE.org : lsGet(LS.org);
const getUsers = () => REMOTE ? REMOTE.users : (lsGet(LS.users) || []);
const saveUsers = u => lsSet(LS.users, u);
const getSession = () => REMOTE ? (REMOTE.me?{userId:REMOTE.me.id}:null) : lsGet(LS.session);
const userById = id => getUsers().find(u=>u.id===id);
const currentUser = () => REMOTE ? REMOTE.me : (getSession() ? userById(getSession().userId) : null);
const canEdit = () => { const u=currentUser(); return !!u && u.role!=='viewer'; };
const isAdmin = () => currentUser()?.role==='admin';
/* ---- TWO NAMES FOR A ROLE, AND THEY ARE NOT INTERCHANGEABLE ----
   ROLE_LABEL is the RECORD's word. It is stamped into approval records, audit
   lines and comment attributions, all of which are history: what somebody's
   role was called on the day they approved something. It stays English on
   purpose — a Swedish approver and an English one must not leave two different
   words behind for the same act, and an audit line is not re-read through a
   translator when the reader changes. It is also what ROLE_LABEL_SET compares
   against when it decides whether an old signature has a permission level
   sitting in its capacity field.

   THE MIDDLE ROLE USED TO BE CALLED "Legal" AND IS NOW "Editor". The stored
   role id is still `legal` — it is a database CHECK constraint and a
   permission key, and renaming it would be a migration for no gain. Only the
   words changed, here and in the dictionary. Records already written keep the
   word they were written with, which is the whole point of this table being
   separate from roleName(); ROLE_LABEL_SET therefore still recognises "Legal"
   as well as "Editor".

   roleName() is the SCREEN's word — what the reader is shown right now, in
   their own language. Anything a person reads off a table, a menu or a badge
   goes through this; anything written into a record does not. */
const ROLE_LABEL = { admin:'Admin', legal:'Editor', viewer:'Viewer' };
const roleName = r => ({ admin:i18t('role_admin'), legal:i18t('role_legal'), viewer:i18t('role_viewer') })[r]
  || ROLE_LABEL[r] || '';

/* ---------- directory & per-member folder access ----------
   Both live in the org-wide appSettings blob, so they persist through
   saveSettings() in server mode (PUT /api/settings) AND local mode (localStorage)
   with no schema change:
     state.settings.directory    = [{ name, email, title }]   (contacts for auto-fill)
     state.settings.folderAccess = { [userId]: '*' | [folderId,…] }  (stream access) */
// A merged people directory: imported contacts PLUS team members (so signer
// fields can auto-fill a name → title + email). Title comes from the contact
// record when an email matches.
function orgDirectory(){
  const dir=(((state.settings||{}).directory)||[]).map(p=>({ name:p.name||'', email:p.email||'', title:p.title||'' }));
  const byEmail={}; dir.forEach(p=>{ const k=(p.email||'').toLowerCase(); if(k) byEmail[k]=p; });
  (getUsers()||[]).forEach(u=>{ const k=(u.email||'').toLowerCase(); if(!k) return;
    if(byEmail[k]){ if(!byEmail[k].title && u.title) byEmail[k].title=u.title; if(!byEmail[k].name) byEmail[k].name=u.name||''; }
    else { const p={ name:u.name||'', email:u.email, title:u.title||'' }; byEmail[k]=p; dir.push(p); } });
  return dir.filter(p=>p.name||p.email);
}
// Look a person up by exact name OR email (case-insensitive) — used to auto-fill.
function directoryLookup(nameOrEmail){
  const q=String(nameOrEmail||'').trim().toLowerCase(); if(!q) return null;
  return orgDirectory().find(p=>(p.name||'').toLowerCase()===q || (p.email||'').toLowerCase()===q)||null;
}
// A user's folder access: '*' = every stream (the default, and always for admins),
// otherwise an array of folder ids they are restricted to.
/* TWO PLACES CARRY THIS ANSWER, AND ONLY ONE OF THEM REACHES A RESTRICTED
   MEMBER'S OWN BROWSER.

   state.settings.folderAccess is the whole workspace's map. It is the admin's
   editing surface — and the server DELIBERATELY strips it from the bootstrap of
   anyone who is not an admin, because it discloses who is fenced off from what.
   So on a restricted member's own screen that map is simply absent, every read
   of it came back undefined, and this function answered "every stream". The
   server went on filtering their data correctly, so nothing leaked; but the
   screen drew the whole workspace's stream switcher and the member was told
   they had access they did not have. Reported from the field (Young, 09 Aug
   2026): "I assign one stream, I log in, I still see all of them."

   The server already sends each person their OWN scope on the user record
   (publicUser → folderScopeFor). That is the authority when the map is silent.

   ORDER MATTERS. The map wins WHEN IT HAS AN ENTRY, because an admin editing
   access sees the change take effect on their own screen before the save
   round-trips. Absence falls through to the record. And a workspace with no
   server at all has neither an entry nor a record, so it answers '*' exactly as
   it always did. */
function userFolderAccess(u){
  u=u||currentUser(); if(!u) return '*'; if(u.role==='admin') return '*';
  const map=((state.settings||{}).folderAccess)||{};
  if(u.id in map){
    /* The map's own quirk, kept: an admin who ticks nothing has not locked
       somebody out of the whole workspace, they have said nothing. */
    const v=map[u.id];
    return (v==null||v==='*'||(Array.isArray(v)&&v.length===0))?'*':v;
  }
  /* The server's answer for this person, taken literally — an empty list there
     is a deliberate deny-all (see folderScopeFor), and the server is already
     filtering on exactly that. A screen that disagreed would offer streams the
     data never arrives for. */
  const own=u.folderAccess;
  return (own==null||own==='*'||!Array.isArray(own))?'*':own;
}
function canAccessFolder(fid,u){ const a=userFolderAccess(u); return a==='*'||(Array.isArray(a)&&a.includes(fid)); }
/* ---- HOW MANY PEOPLE CAN SEE WHAT IS IN THIS DRAWER ----
   The settings panel has printed "N of M people can see it" beside every folder
   since the August 2026 rebuild, and re-filing a contract is the act that
   CHANGES that number — so the confirm has to be able to say it too. One
   reading, two readers: it is built on canAccessFolder, which is the map's own
   named predicate, so the sentence on the confirm and the line on the settings
   panel can never disagree about who is in a folder. */
function folderSeerCount(fid){
  const users=((typeof getUsers==='function'?getUsers():[])||[]);
  return { n:users.filter(u=>canAccessFolder(fid,u)).length, total:users.length };
}

/* ---------- signing capacity ----------
   A signature block states the capacity in which someone bound the company —
   "Amina Otieno, Chief Operating Officer". That is their JOB TITLE, and it is
   a different thing from their `role`, which is an Admin/Legal/Viewer
   PERMISSION LEVEL inside the software.

   The two were being confused: the sign path never recorded a title, and the
   signature block filled the gap with the permission level, so a COO who
   happened to be a workspace admin signed as "Admin". A permission level says
   nothing about authority to sign, so a missing title must render as nothing
   at all rather than as the wrong claim.

   Order of preference: the title on the member's own account, then the people
   directory (which may know them from an imported contact list), then empty. */
function signerTitle(u){
  u=u||currentUser(); if(!u) return '';
  if(u.title && String(u.title).trim()) return String(u.title).trim();
  if(typeof directoryLookup==='function'){
    const p=directoryLookup(u.email)||directoryLookup(u.name);
    if(p && p.title && String(p.title).trim()) return String(p.title).trim();
  }
  return '';
}
/* What to print under a signer's name. `title` is the capacity as recorded.
   `role` is the free-text "Title (e.g. CFO)" field on a signing route — but
   signatures taken before this was fixed had the PERMISSION LEVEL written into
   it, so a value that is exactly one of those labels is suppressed rather than
   displayed as a capacity. Display-only: it reads existing records more
   honestly without altering one, which matters because a signature on an
   executed contract is immutable by design. */
// "Legal" is the name the middle role carried before it was renamed Editor;
// signatures taken then still hold that word, so both are recognised.
const ROLE_LABEL_SET = new Set(['Admin','Legal','Editor','Viewer']);
function signatureCapacity(s){
  if(!s) return '';
  const t=String(s.title||'').trim();
  if(t) return t;
  const r=String(s.role||'').trim();
  return (!r || ROLE_LABEL_SET.has(r)) ? '' : r;
}
/* Whether this member may see monetary amounts. The SERVER decides — it strips
   value fields, monetary aggregates and CSV value cells before responding, and
   never puts a figure in an Copilot prompt for someone without the right. This
   function exists so the interface can stop OFFERING what it will not receive
   (a "sort by value" option that cannot sort, a KPI card that would read KES 0),
   not to do the hiding. In static mode there is no server and no such
   permission, so it answers true and behaviour is unchanged. */
function canViewValues(u){
  u=u||currentUser();
  if(!u) return false;
  if(u.role==='admin') return true;
  return u.canViewValues!==false;
}
/* The Value cell for a browser-built CSV (a selection of register rows). A
   masked record has no `value` at all, and `c.value||0` would write a
   confident "0" into the sheet — a wrong number, not a hidden one. The
   authoritative, whole-register export is GET /api/export/contracts.csv, which
   the server masks the same way. */
const csvValueCell = c => (!isMonetary(c) || !canViewValues()) ? '' : (c.value||0);
Object.assign(window,{orgDirectory,directoryLookup,userFolderAccess,canAccessFolder,folderSeerCount,canViewValues,csvValueCell,signerTitle,signatureCapacity});

const newSalt = () => Math.random().toString(36).slice(2) + Date.now().toString(36);
const hashPassword = (pw,salt) => sha256(`${salt}::${pw}`);

function renderAuth(mode){
  document.getElementById('app-shell').classList.add('hidden');
  const root=document.getElementById('auth-root');
  const shell = inner => `
  <div style="min-height:100vh;display:grid;place-items:center;background:var(--color-bg);padding:40px 16px;">
    <div style="width:100%;max-width:420px;">
      <div style="display:flex;align-items:center;gap:10px;justify-content:center;margin-bottom:20px;">
        <div style="width:36px;height:36px;background:var(--color-accent-800);color:#fff;display:grid;place-items:center;font-family:var(--font-mono);font-weight:600;font-size:17px;letter-spacing:.02em;border-radius:0;">HT</div>
        <div style="line-height:1.15;">
          <div style="font-family:var(--font-mono);font-weight:600;font-size:20px;letter-spacing:.01em;color:var(--color-text);">HaTi</div>
          <div style="font-size:11px;letter-spacing:.09em;text-transform:uppercase;color:var(--color-neutral-600);">${i18t('co_clm')}</div>
        </div>
      </div>
      <div style="background:var(--color-surface);border:1px solid var(--color-divider);box-shadow:var(--shadow-lg);border-radius:0;padding:26px;">${inner}</div>
      <p style="text-align:center;font-size:12px;color:var(--color-neutral-600);margin-top:14px;line-height:1.6;">${REMOTE?'Connected to your HaTi server — accounts and contracts are stored centrally.':'MVP demo — no data leaves this browser.'}</p>
    </div>
  </div>`;
  const input=(id,label,type='text',ph='')=>`
    <label style="display:block;margin-bottom:14px;">
      <span style="display:block;font-size:13px;font-weight:600;color:var(--color-neutral-700);margin-bottom:5px;font-family:var(--font-mono);letter-spacing:.02em;">${label}</span>
      <input id="${id}" type="${type}" placeholder="${ph}" style="width:100%;min-height:36px;border:1px solid var(--color-divider);background:var(--color-surface);border-radius:0;padding:7px 11px;font-size:14px;font-family:var(--font-body);color:var(--color-text);outline:none;"/></label>`;
  const H1='font-family:var(--font-mono);font-weight:600;font-size:22px;letter-spacing:-0.01em;color:var(--color-text);margin:0;';
  const SUB='font-size:13px;color:var(--color-neutral-700);margin:4px 0 18px;line-height:1.5;';
  const PBTN='width:100%;padding:9px;font-size:14px;margin-top:2px;';
  const LINKBTN='margin-top:14px;width:100%;background:none;border:0;font-size:12px;color:var(--color-neutral-600);cursor:pointer;font-family:var(--font-body);';
  if(mode==='setup'){
    root.innerHTML = shell(`
      <h1 style="${H1}">${i18t('co_create_workspace_h')}</h1>
      <p style="${SUB}">${i18t('co_setup_sub')}</p>
      ${input('su-org',i18t('co_org_name'),'text',i18t('co_ph_org'))}
      ${input('su-name',i18t('co_your_full_name'),'text',i18t('co_ph_person'))}
      ${input('su-title',i18t('co_your_job_title'),'text',i18t('co_ph_job_title'))}
      ${input('su-email',i18t('co_work_email'),'email',i18t('co_ph_work_email'))}
      ${input('su-pass',i18t('co_password'),'password',i18t('co_ph_min8'))}
      ${/* WHERE THE WORKSPACE OPERATES, ASKED BEFORE ANYTHING IS BUILT. The
           market switch lived only in the shell, which is after this screen —
           so the sample portfolio, the money on it and the law in its wording
           were always the default market's, and a Swedish pilot had to switch
           afterwards and re-read everything it had just been shown. */''}
      <label style="display:block;margin-bottom:14px;">
        <span style="display:block;font-size:13px;font-weight:600;color:var(--color-neutral-700);margin-bottom:5px;font-family:var(--font-mono);letter-spacing:.02em;">${i18t('co_where_you_operate')}</span>
        <select id="su-market" style="width:100%;min-height:36px;border:1px solid var(--color-divider);background:var(--color-surface);border-radius:0;padding:7px 11px;font-size:14px;font-family:var(--font-body);color:var(--color-text);outline:none;">
          ${jxList().map(p=>`<option value="${p.id}"${p.id===jxId()?' selected':''}>${p.name}</option>`).join('')}
        </select>
        <span style="display:block;font-size:12px;color:var(--color-neutral-600);margin-top:4px;line-height:1.45">${i18t('co_market_sets')}</span></label>
      <label style="display:flex;align-items:center;gap:10px;font-size:13px;color:var(--color-neutral-700);margin:2px 0 18px;"><input id="su-sample" type="checkbox" checked style="width:16px;height:16px;accent-color:var(--color-accent);"/> ${i18t('co_load_sample')} <span id="su-sample-label">${jx().sampleLabel}</span> ${i18t('co_portfolio_30')}</label>
      <button id="su-go" class="ui-btn ui-btn-primary" style="${PBTN}">${i18t('co_create_and_signin')}</button>`);
    /* Applied on CHANGE, not at submit, so the sample label under it tells the
       truth about what is on the other side of the button. */
    document.getElementById('su-market')?.addEventListener('change',e=>{
      jxSet(e.target.value);
      const lbl=document.getElementById('su-sample-label');
      if(lbl) lbl.textContent=jx().sampleLabel;
    });
    document.getElementById('su-go').addEventListener('click',doSetup);
    root.querySelectorAll('input').forEach(i=>i.addEventListener('keydown',e=>{if(e.key==='Enter')doSetup();}));
  } else if(mode==='login'){
    root.innerHTML = shell(`
      <h1 style="${H1}">${i18t('co_sign_in_to',{org:getOrg()?.name||i18t('co_your_workspace')})}</h1>
      <p style="${SUB}">${i18t('co_use_credentials')}</p>
      ${input('li-email',i18t('co_email'),'email')}
      ${input('li-pass',i18t('co_password'),'password')}
      <button id="li-go" class="ui-btn ui-btn-primary" style="${PBTN}">${i18t('co_sign_in')}</button>
      <p id="li-err" class="hidden" style="text-align:center;font-size:13px;color:var(--st-ruby-dot);margin-top:12px;"></p>
      ${REMOTE?`<button id="li-forgot" style="${LINKBTN}">${i18t('co_forgot_password')}</button>`:''}
      ${REMOTE?'':`<button id="li-reset" style="${LINKBTN}">${i18t('co_reset_workspace')}</button>`}`);
    document.getElementById('li-go').addEventListener('click',doLogin);
    root.querySelectorAll('input').forEach(i=>i.addEventListener('keydown',e=>{if(e.key==='Enter')doLogin();}));
    document.getElementById('li-forgot')?.addEventListener('click',()=>renderAuth('forgot'));
    document.getElementById('li-reset')?.addEventListener('click',async()=>{
      if(await confirmDialog({get title(){ return i18t('co_reset_workspace_q'); }, get message(){ return i18t('co_erase_msg'); }, get confirmLabel(){ return i18t('co_erase_everything'); }, danger:true})){
        Object.values(LS).forEach(k=>localStorage.removeItem(k)); location.reload();
      }
    });
  } else if(mode==='forgot'){
    root.innerHTML = shell(`
      <h1 style="${H1}">${i18t('co_reset_your_password')}</h1>
      <p style="${SUB}">${i18t('co_enter_email_reset')}</p>
      ${input('fp-email',i18t('co_email'),'email')}
      <button id="fp-go" class="ui-btn ui-btn-primary" style="${PBTN}">${i18t('co_send_reset_link')}</button>
      <div id="fp-result" style="margin-top:12px;"></div>
      <button id="fp-back" style="${LINKBTN}">${i18t('co_back_to_signin')}</button>`);
    document.getElementById('fp-back').addEventListener('click',()=>renderAuth('login'));
    document.getElementById('fp-go').addEventListener('click',async()=>{
      const email=fval('fp-email'); if(!email){ toast(i18t('co_enter_your_email'),'err'); return; }
      try{
        const r=await api('password/reset-request','POST',{ email });
        /* C-2: the server never returns the reset token any more. When email is
           not configured the reset link is in the ADMIN-ONLY outbox (Team &
           Settings), the same place signing codes queue — so the shortcut that
           used to open the reset form for anyone is gone. */
        const outboxHint = r.emailSent ? '' : ` <br/>${i18t('co_outbox_hint')}`;
        document.getElementById('fp-result').innerHTML=`<div style="border-radius:0;background:var(--color-accent-100);border:1px solid var(--color-divider);padding:11px;font-size:12px;color:var(--color-accent-800);line-height:1.5;">${i18t('co_reset_sent')}${outboxHint}</div>`;
      }catch(e){ toast(e.message,'err'); }
    });
  } else if(mode && mode.startsWith('reset:')){
    const token=mode.slice(6);
    root.innerHTML = shell(`
      <h1 style="${H1}">${i18t('co_set_new_password')}</h1>
      <p style="${SUB}">${i18t('co_choose_new_password')}</p>
      ${input('rs-pass','New password','password','Min 8 characters')}
      <button id="rs-go" class="ui-btn ui-btn-primary" style="${PBTN}">${i18t('co_save_new_password')}</button>
      <p id="rs-err" class="hidden" style="text-align:center;font-size:13px;color:var(--st-ruby-dot);margin-top:12px;"></p>`);
    document.getElementById('rs-go').addEventListener('click',async()=>{
      const pass=document.getElementById('rs-pass').value;
      if(pass.length<8){ toast(i18t('co_password_min8'),'err'); return; }
      try{
        await api('password/reset','POST',{ token, password:pass });
        toast(i18t('co_password_updated'));
        location.hash=''; renderAuth('login');
      }catch(e){ const el=document.getElementById('rs-err'); el.textContent=e.message; el.classList.remove('hidden'); }
    });
  }
}
/* The email is the sign-in name AND the password-reset route, so a typo here
   is not a cosmetic problem — there is no second admin yet to fix it with. */
const validEmail = e => /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/.test(String(e||'').trim());
async function doSetup(){
  const name=fval('su-org').trim(), uname=fval('su-name').trim(), email=fval('su-email').trim().toLowerCase();
  const utitle=fval('su-title').trim();
  const pass=document.getElementById('su-pass').value;
  if(!name){ toast(i18t('co_enter_org_name'),'err'); return; }
  if(!uname){ toast(i18t('co_enter_full_name'),'err'); return; }
  if(!validEmail(email)){ toast(i18t('co_enter_work_email'),'err'); return; }
  if(pass.length<8){ toast(i18t('co_password_min8'),'err'); return; }
  if(REMOTE){
    try{
      const sample=document.getElementById('su-sample').checked;
      /* Re-seeded HERE rather than reusing the set built at module load: the
         market is picked on this screen, and the portfolio built before that
         choice is always the default one. */
      if(sample) state.contracts=sampleContracts();
      await api('setup','POST',{ org:name, name:uname, title:utitle, email, password:pass,
        data:{ uid, contracts:sample?state.contracts.map(migrateContract):[], view:'dashboard', activeId:null, folderId:null } });
      await loadBootstrap();
      startApp();
      toast(`Workspace "${name}" created — karibu!`);
    }catch(e){ toast(e.message,'err'); }
    return;
  }
  const salt=newSalt();
  const admin={ id:'u1', name:uname, email, role:'admin', title:utitle, salt, hash:await hashPassword(pass,salt), createdAt:nowISO() };
  lsSet(LS.org,{ name, createdAt:nowISO() });
  saveUsers([admin]);
  lsSet(LS.session,{ userId:admin.id, at:nowISO() });
  if(!document.getElementById('su-sample').checked) state.contracts=[];
  else state.contracts=sampleContracts();   // same reason as the server branch above
  persist();
  startApp();
  toast(`Workspace "${name}" created — karibu!`);
}
async function doLogin(){
  const email=fval('li-email').toLowerCase(), pass=document.getElementById('li-pass').value;
  const err=document.getElementById('li-err');
  if(REMOTE){
    try{
      const r=await api('login','POST',{ email, password:pass });
      // two-step sign-in (WO-6): a correct password earned a ticket, not a
      // session — the code turns it into one
      if(r&&r.twoStep) return doLoginTotp(r.ticket, err);
      await loadBootstrap();
      startApp();
      toast(`Karibu tena, ${REMOTE.me.name.split(' ')[0]}`);
    }catch(e){ err.textContent=e.message; err.classList.remove('hidden'); }
    return;
  }
  const u=getUsers().find(x=>x.email===email);
  if(!u || (await hashPassword(pass,u.salt))!==u.hash){ err.textContent='Email or password is incorrect.'; err.classList.remove('hidden'); return; }
  lsSet(LS.session,{ userId:u.id, at:nowISO() });
  startApp();
  toast(`Karibu tena, ${u.name.split(' ')[0]}`);
}
/* The second step (WO-6). Cancel falls back to the sign-in form; a wrong code
   re-asks while the ticket is live (the server's failures-only limiter is the
   wall against grinding); "sign in again" from the server means the five-
   minute window closed, so the password comes first once more. */
async function doLoginTotp(ticket, err){
  const code=await promptDialog({ title:i18t('ts_code_title'), message:i18t('ts_code_msg'),
    placeholder:'123456', confirmLabel:i18t('ts_confirm'), cancelLabel:i18t('act_cancel') });
  if(code==null) return;
  try{
    await api('login/totp','POST',{ ticket, code:String(code).trim() });
    await loadBootstrap();
    startApp();
    toast(`Karibu tena, ${REMOTE.me.name.split(' ')[0]}`);
  }catch(e){
    if(err){ err.textContent=e.message; err.classList.remove('hidden'); }
    if(!/sign in again/i.test(e&&e.message||'')) return doLoginTotp(ticket, err);
  }
}
function logout(){
  if(REMOTE){ api('logout','POST').catch(()=>{}).finally(()=>location.reload()); return; }
  localStorage.removeItem(LS.session); location.reload();
}

/* An account created by an admin starts on a password the admin chose. Until
   the member replaces it, everything they do is attributable to two people —
   which for a signing product means attributable to neither. The server refuses
   their mutating requests; this is the screen that lets them fix it. */
function renderMustChangePassword(){
  const authRoot=document.getElementById('auth-root');
  const shell=document.getElementById('app-shell');
  shell.classList.add('hidden'); shell.style.display='none';
  const F='width:100%;min-height:38px;border:1px solid var(--color-divider);background:var(--color-surface);border-radius:0;padding:8px 11px;font-size:14px;font-family:var(--font-body);color:var(--color-text);outline:none;margin-bottom:10px;';
  authRoot.innerHTML=`
    <div style="min-height:100vh;display:grid;place-items:center;background:var(--color-bg);padding:0 16px;">
      <div style="background:var(--color-surface);border:1px solid var(--color-divider);box-shadow:var(--shadow-lg);border-radius:0;padding:30px;max-width:25rem;width:100%;">
        <h1 style="font-family:var(--font-heading);font-weight:600;font-size:20px;color:var(--color-text);margin:0 0 6px;">${i18t('co_choose_own_password')}</h1>
        <p style="font-size:14px;color:var(--color-neutral-700);margin:0 0 16px;line-height:1.55;">Your account was created with a temporary password someone else chose. Set your own before you continue — anything you sign has to be attributable to you alone.</p>
        <input id="cp-current" type="password" placeholder="${i18t('co_temporary_password')}" style="${F}"/>
        <input id="cp-new" type="password" placeholder="${i18t('co_new_password_min')}" style="${F}"/>
        <input id="cp-again" type="password" placeholder="${i18t('co_repeat_password')}" style="${F}"/>
        <button id="cp-go" class="ui-btn ui-btn-primary" style="width:100%;padding:10px;font-size:15px;">${i18t('co_set_my_password')}</button>
        <p id="cp-err" class="hidden" style="text-align:center;font-size:13px;color:var(--st-ruby-dot);margin-top:12px;"></p>
      </div></div>`;
  document.getElementById('cp-go').addEventListener('click',async()=>{
    const cur=document.getElementById('cp-current').value;
    const nw=document.getElementById('cp-new').value;
    const again=document.getElementById('cp-again').value;
    const err=document.getElementById('cp-err');
    const fail=m=>{ err.textContent=m; err.classList.remove('hidden'); };
    if(nw.length<8) return fail('The new password must be at least 8 characters.');
    if(nw!==again) return fail('The two new passwords do not match.');
    try{
      await api('password/change','POST',{ current:cur, password:nw });
      if(REMOTE&&REMOTE.me&&REMOTE.me.prefs) delete REMOTE.me.prefs.mustChangePassword;
      toast('Password updated — karibu');
      startApp();
    }catch(e){ fail(e.message); }
  });
}
function startApp(){
  if(REMOTE && REMOTE.me && REMOTE.me.prefs && REMOTE.me.prefs.mustChangePassword){
    renderMustChangePassword(); return;
  }
  FIRST_PARTY = getOrg().name;
  /* BEFORE THE FIRST RENDER, not after: this is the moment the signed-in user
     is known, and langId() reads through them. Painting the shell first and
     translating afterwards would show every returning Swedish user a flash of
     English. repaint:false because nothing has been drawn yet — there is no
     screen to redraw and setView is about to run anyway. */
  window.applyLanguage && applyLanguage({repaint:false});
  document.getElementById('auth-root').innerHTML='';
  const shell=document.getElementById('app-shell');
  shell.classList.remove('hidden');   // renderAuth hides the shell; .hidden is !important so the class must go
  shell.style.display='grid';
  renderSideUser(); renderSideFolders();
  window.renderNewMenu&&renderNewMenu();
  window.applyPanelLayout&&applyPanelLayout();
  // the company design loads async; if the first paint was a contract, repaint it dressed
  refreshOrgBranding().then(()=>{ if(window.ORG_BRANDING&&state.view==='workspace'&&window.renderWorkspace) renderWorkspace(); });
  // resume where the user left off
  window.hydrateAdvice&&hydrateAdvice();   // Advice Desk queue (static mode; server mode loads async below)
  /* 'redline' and the template surfaces belong on this list: both render an
     honest empty state when their contract or template is not loaded yet, so
     resuming there is safe — and losing a refresh mid-negotiation to the
     dashboard was the exact complaint this list caused. */
  setView(['dashboard','register','pipeline','advice','intake','folder','intel','calendar','reports','templates','templatelib','playbook','workspace','team','directory','migration','redline'].includes(state.view)?state.view:'dashboard');
  if(API_MODE()){ refreshStats(); refreshShareOverview(); refreshWaitingQuestions(); pollPendingResponses(); refreshAiUsage();
    schedulePolling();
    /* Coming back to the tab is when a person expects to be up to date. */
    if(!window._pollFocusBound){
      window._pollFocusBound=true;
      window.addEventListener('focus',()=>pollNow('focus'));
      document.addEventListener('visibilitychange',()=>{ if(!document.hidden) pollNow('visible'); });
    }
    setInterval(refreshShareOverview,60000); setInterval(refreshWaitingQuestions,60000); setInterval(refreshAiUsage,30000);
    window.loadAdviceRequests&&loadAdviceRequests().then(()=>{ updateSidebarCounts(); if(state.view==='advice') renderAdviceDesk(); }).catch(()=>{});
    window.loadIntake&&loadIntake().then(()=>{ updateSidebarCounts(); if(state.view==='intake') renderIntake(); }).catch(()=>{});
    /* One-time heal: workspaces whose market was chosen before the choice was
       persisted server-side (see jxSet) have it only in this browser's local
       store, and every server-built artefact fell back to the default market.
       An admin whose browser knows better teaches the server once; from then
       on bootstrap carries it to everyone. */
    try{
      const org=getOrg(), local=(typeof lsGet==='function'&&lsGet(JX_LS))||null;
      if(isAdmin()&&org&&!org.jurisdiction&&local&&window.JURISDICTIONS&&JURISDICTIONS[local]&&local!==JX_DEFAULT)
        api('org/jurisdiction','PUT',{ jurisdiction:local }).then(()=>{ org.jurisdiction=local; }).catch(()=>{});
    }catch(_){}
  }
  repairMigratedSignatories();
  openFromHash();
}

/* ---- A LINK IN AN EMAIL LANDS ON THE CONTRACT, NOT ON THE FRONT DOOR ----
   #contract=<id>[&tab=sign]. Written by the server's internal turn email (see
   contractSignUrl in server/server.js), which used to point at the site root —
   telling somebody a specific agreement is waiting on them and then asking them
   to go and find it.

   CONSUMED HERE RATHER THAN IN boot(), and that is the whole reason it works:
   boot runs before anybody is signed in, and an internal signer following their
   turn email arrives at the sign-in wall. renderAuth does not touch the hash, so
   it survives the wall — and startApp is what runs on the far side of a
   successful sign-in AND on a resumed session, which makes it one place for both
   journeys rather than two that can drift.

   The hash is cleared once honoured: a refresh an hour later should reopen the
   contract wherever the reader left it, not jump them back to the signing step. */
function openFromHash(){
  const m=String(location.hash||'').match(/^#contract=([^&]+)(?:&tab=([a-z]+))?$/i);
  if(!m) return false;
  const id=decodeURIComponent(m[1]), tab=String(m[2]||'').toLowerCase();
  try{ history.replaceState(null,'',location.pathname+location.search); }catch(_){ location.hash=''; }
  const c=(state.contracts||[]).find(x=>x&&x.id===id);
  /* A contract this person cannot see is not an error to explain away: the
     server filters their bootstrap (folderScopeFor), so "not here" and "not
     yours" look the same from the browser and must read the same. */
  if(!c){ if(window.toast) toast(i18t('co_open_link_gone',{id}),'err'); return false; }
  state.activeId=id; state.selId=id;
  setView('workspace');
  /* The tab is asked for AFTER the room exists, through the room's own router —
     never by writing its private state from out here. An unknown tab name is
     simply not asked for, and the room opens where it always would.

     'redline' IS ON THE LIST AND IS NOT A TAB. Negotiate left the room's tab row
     on 12 Aug 2026 and became a place; the KEY still routes through roomGoTab,
     which opens the negotiation workbench for that agreement. It is here because
     the internal review's email asks a colleague to rule on named changes, and
     the one place they can do that is the negotiation — the same reason the
     signer's mail asks for 'sign'. Both links are built by one function on the
     server (contractUrl), and this is the one place either is honoured. */
  if(tab && window.roomGoTab && ['terms','docs','sign','history','redline'].includes(tab)){
    try{ roomGoTab(c, tab); }catch(_){}
  }
  return true;
}

/* One-time repair. Migration used to stamp the name of whoever ran the import
   into `signatory`, and the signature panel then read that as "Signed by …" —
   putting a person who never signed onto an executed contract. Nothing was
   forged (no signature record was ever created, and the evidence pack lists
   none), but the claim has to come off the record, not just off the screen.
   The condition is self-clearing, so this runs once per affected contract. */
async function repairMigratedSignatories(){
  if(!canEdit()) return;                                  // viewers cannot write
  const todo=state.contracts.filter(c=>isExternallyExecuted(c) && c.signatory);
  if(!todo.length) return;
  for(const c of todo){
    try{
      await ensureFull(c);                                // never save from a light record
      if(!c.signatory) continue;
      const was=c.signatory;
      c.signatory=null;
      logAudit(c,'Corrected',`Removed "${was}" as recorded signatory — this contract was executed outside HaTi and no signature was taken here`);
      persist(c);
    }catch(e){ /* leave it for the next load; the panel already reads honestly */ }
  }
  try{ await flushSaves(); }catch(e){}
  if(state.view==='workspace' && window.renderWorkspace) renderWorkspace();
}
function renderSideUser(){
  const u=currentUser(); if(!u) return;
  const org=getOrg().name||'HaTi';
  const initials=(u.name||org).split(' ').filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase();
  const av=document.getElementById('rail-avatar');
  /* ---- THE AVATAR IS THE ACCOUNT MENU NOW, FOR EVERYBODY ----
     It used to be a one-click door straight into Team & Settings, which is
     admin-only from the Aug 2026 redesign — so for two of the three roles it
     was a door onto a refusal. It opens "Your account" instead: their own job
     title, their sidebar, their sessions, their backup and the honest statement
     of what HaTi emails them. An admin finds Settings & Rules on that surface
     and in the sidebar, so no door was lost; one was gained for everybody else. */
  if(av){ av.title=`${u.name} · ${org} · ${roleName(u.role)}`;
    av.onclick=()=>{ if(window.openMyAccount) openMyAccount(); else setView('team'); }; }
  const lo=document.getElementById('side-logout');
  if(lo) lo.onclick=async()=>{
    const ok=(typeof confirmDialog==='function')
      ? await confirmDialog({ get title(){ return i18t('co_log_out_q'); }, message:`End your session${org?` on ${org}`:''} and return to the sign-in screen?`, confirmLabel:'Log out' })
      : true;
    if(ok) logout();
  };
  const setTxt=(id,t)=>{ const el=document.getElementById(id); if(el) el.textContent=t; };
  setTxt('side-avatar', initials);
  setTxt('side-name', u.name||org);
  setTxt('side-role', `${roleName(u.role)||i18t('role_member')} · ${org}`);
  const online=(getUsers()||[]).length||1;
  // Show the storage backend AND whether the Copilot brain is live, so an entered key
  // is visibly reflected (green ✦ = Claude answering; grey = keyword fallback).
  // THREE NAMED READINGS, not one run-on sentence. The card in the sidebar foot
  // states what each figure is before it states the figure, so a reader who has
  // never seen the app can tell what it is reporting.
  const aiOn=(typeof copilotAvailable==='function') && copilotAvailable();
  const put=(id,txt,tone)=>{ const el=document.getElementById(id); if(!el) return;
    el.textContent=txt; if(tone) el.setAttribute('data-tone',tone); else el.removeAttribute('data-tone'); };
  put('side-status-mode', API_MODE()?'Server · SQLite':'Local · browser');
  put('side-status-ai',   aiOn?'✦ Claude · live':'Keywords only', aiOn?'on':'off');
  put('side-status-online', online===1?'1 person':`${online} people`);
}
// Bottom-left Copilot meter: today's real Anthropic API calls across the workspace,
// so the owner can watch actual usage and size a per-customer daily limit.
// Server mode only (in Local mode the browser calls Anthropic directly with no
// server tally); the count resets at local midnight (server AI_DAY_TZ).
async function refreshAiUsage(){
  const box=document.getElementById('side-ai-usage'), txt=document.getElementById('side-ai-usage-txt');
  const lab=document.getElementById('side-ai-usage-label'), sub=document.getElementById('side-ai-usage-sub');
  if(!box||!txt) return;
  if(!API_MODE()){ box.style.display='none'; return; }
  /* A DOOR ONLY WHERE PRESSING IT DOES SOMETHING. This box took everybody to
     Team & Settings, and that page is admin-only now — so for a colleague it
     was a control that looked live and led to their own account instead. It
     still SHOWS the workspace's Copilot spend to everyone (that is worth
     knowing), it simply stops promising a press. */
  const mayTune=(typeof isAdmin==='function') && isAdmin();
  box.onclick = mayTune ? (()=>{ if(window.openSettingsAt) openSettingsAt('build','engine'); else setView('team'); }) : null;
  box.style.cursor = mayTune ? '' : 'default';
  try{
    const u=await api('ai/usage');
    state.aiUsage=u;
    const budget=Number(u.dailySpendLimit||0);
    const spent=Number(u.spend||0);
    const a=u.allowance;
    // The request count moves off the money line and becomes the line that
    // SAYS WHAT THE MONEY IS. "$1.02 / $10.00" on its own is a figure without
    // a subject; under a "Copilot spend today" label with "15 Copilot requests
    // today" beneath it, it is a reading.
    const reqs=Number(u.count||0);
    const reqLine=`${reqs.toLocaleString(jxLocale())} Copilot request${reqs===1?'':'s'} today`;
    if(a&&a.open){
      if(lab) lab.textContent='Free allowance';
      txt.textContent=`$${Number(a.spent||0).toFixed(2)}${a.budget>0?' / $'+Number(a.budget).toFixed(2):''}`;
      if(sub) sub.textContent=reqLine;
    }else{
      if(lab) lab.textContent='Copilot spend';
      txt.textContent=`$${spent.toFixed(2)}${budget>0?' / $'+budget.toFixed(2):''}`;
      if(sub) sub.textContent=reqLine;   // the cap is already the figure's denominator
    }
    box.style.display='flex';
  }catch(e){ box.style.display='none'; }
}
// folders/quick-create moved into the Register + New-contract menu; no rail list.
function renderSideFolders(){ /* rail has no folder list in the light-theme redesign */ }

/* ---------- audit trail ---------- */
/* Where a signer's IP and device go now that they are off the document face:
   into the audit entry for the signature. Returns a suffix like
   " · IP 41.90.x.x · Chrome", or '' when neither was captured. The full
   user-agent string is kept on the signature record and travels in the
   evidence pack; the audit line names the device family, which is what a
   reader of the trail can actually use. */
function deviceFromUa(ua){
  const s=String(ua||'');
  if(!s) return '';
  if(/mobile|android|iphone|ipad/i.test(s)) return 'Mobile';
  if(/edg\//i.test(s)) return 'Edge';
  if(/chrome|crios/i.test(s)) return 'Chrome';
  if(/firefox/i.test(s)) return 'Firefox';
  if(/safari/i.test(s)) return 'Safari';
  return 'Browser';
}
function signerProvenance(ip, ua){
  const parts=[];
  if(ip) parts.push('IP '+ip);
  const dev=deviceFromUa(ua);
  if(dev) parts.push(dev);
  return parts.length?' · '+parts.join(' · '):'';
}
/* `data` is an optional STRUCTURED half of an entry (X3): the prose `detail`
   is the record a human reads, and `data` is the same fact in a shape the
   history timeline can render without parsing prose — first used by the
   renumbering act ({ kind:'renumber', headings:[{clauseId,from,to}], … }).
   Additive: entries without it are unchanged, and nothing reads it back as
   required. */
function logAudit(c, action, detail, actor, data){
  c.audit = c.audit || [];
  const user = actor || currentUser()?.name || 'System';
  const last = c.audit[c.audit.length-1];
  // coalesce rapid repeats (e.g. keystrokes on the same field) into one entry
  if(last && last.action===action && last.detail===detail && last.user===user
     && (Date.now()-new Date(last.at).getTime())<60000){ last.at=nowISO(); return; }
  c.audit.push({ at:nowISO(), user, action, detail, ...(data ? { data } : {}) });
}
function renderAuditSection(c){
  const host=document.getElementById('audit-section'); if(!host) return;
  const items=(c.audit||[]).slice().reverse();
  /* H-1: escape audit fields before they reach innerHTML. Audit `detail` strings
     embed counterparty-influenced text — a proposed change's summary and the
     proposer's name (see negoResolve in negotiation.js) and comment text applied
     from a share response — so the audit trail is an untrusted-text sink too,
     for the same reason the comments feed was. */
  const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  host.innerHTML=`
    <div class="px-5 py-4">
      <div class="flex items-center gap-2 mb-3">
        <span class="text-brand-500">${icon('history')}</span>
        <h3 class="text-sm font-display font-600 text-brand-900">${i18t('co_audit_trail')}</h3>
        <span class="ml-auto text-[10px] font-mono text-brand-800/60">${items.length} events</span>
      </div>
      <div class="space-y-2 max-h-44 overflow-y-auto scroll-thin pr-1">
        ${items.length?items.map(e=>`
          <div class="flex gap-2 text-[11px] leading-relaxed">
            <span class="mt-1.5 h-1.5 w-1.5 rounded-full bg-brand-300 shrink-0"></span>
            <span class="min-w-0"><span class="font-medium text-brand-900">${esc(e.action)}</span>
              <span class="text-brand-800/70"> — ${esc(e.detail)}</span>
              <span class="block text-[10px] text-brand-800/60 font-mono">${esc(e.user)} · ${esc(fmtDT(e.at))}</span></span>
          </div>`).join(''):`<div class="text-[11px] text-brand-800/65">${i18t('co_no_events')}</div>`}
      </div>
    </div>`;
}

/* ---------- negotiation rounds ---------- */
/* Rounds that have been ruled on. The presence of one is what makes "send the
   updated version" meaningful: something was decided, so the wording has moved
   and the other side is owed the new copy. */
const resolvedRounds = c => (c.rounds||[]).filter(r=>r.status!=='open' && r.resolution);

function renderNegotiationSection(c){
  const host=document.getElementById('nego-section'); if(!host) return;
  const rounds=c.rounds||[];
  if(!rounds.length){ host.innerHTML=''; return; }
  const open=rounds.filter(r=>r.status==='open').length;
  host.innerHTML=`
    <div class="px-5 py-4">
      <div class="flex items-center gap-2 mb-3">
        <span class="text-gold-500">${icon('history')}</span>
        <h3 class="text-sm font-display font-600 text-brand-900">${i18t('co_negotiation')}</h3>
        ${open?`<span class="ml-auto inline-flex items-center gap-1 rounded-full border border-gold-500/25 bg-gold-500/10 text-gold-600 px-2 py-0.5 text-[10px] font-medium">${open} open</span>`:`<span class="ml-auto text-[10px] font-mono text-brand-800/60">${rounds.length} round${rounds.length===1?'':'s'}</span>`}
      </div>
      <div class="space-y-2">
        ${rounds.slice().reverse().map(r=>`
          <div class="rounded-lg border ${r.status==='open'?'border-gold-500/30 bg-gold-500/5':'border-brand-100 bg-white'} p-3">
            <div class="flex items-center gap-2 text-[11px] mb-1">
              <span class="font-semibold text-brand-900">${r.via==='word'?i18t('co_round_via_word',{n:r.n}):i18t('co_round_via_changes',{n:r.n})}</span>
              <span class="ml-auto text-brand-800/60 font-mono">${fmtDT(r.at)}</span>
            </div>
            <div class="text-[11px] text-brand-800/65 mb-1">by ${r.by}</div>
            <p class="text-xs text-brand-800/80 leading-relaxed">${(r.comment||'').replace(/</g,'&lt;')}</p>
            ${r.proposedText?`<div class="mt-1.5 text-[11px] inline-flex items-center gap-1 rounded-full bg-gold-500/12 text-gold-600 px-2 py-0.5 font-600">${icon('history','w-3 h-3')} proposed edits (redline)</div>`:''}
            ${r.proposedValue!=null?`<div class="mt-1.5 text-[11px]"><span class="text-brand-800/70">${i18t('co_proposed_value')}</span> <span class="font-mono font-semibold text-brand-900">${fmtMoney(r.proposedValue)}</span></div>`:''}
            ${r.status==='open'?(canEdit()?`
              <div class="mt-2 flex items-center gap-2">
                ${r.proposedText?`<button data-nego-redline="${r.n}" class="flex items-center gap-1 rounded-lg bg-brand-900 text-white px-3 py-1.5 text-[11px] font-medium hover:bg-brand-800 transition">${icon('history','w-3 h-3')} Review redline</button>
                <button data-nego-reject="${r.n}" class="rounded-lg border border-brand-200 text-brand-700 px-3 py-1.5 text-[11px] font-medium hover:bg-brand-50 transition">${i18t('co_reject')}</button>`
                :`<button data-nego-accept="${r.n}" class="flex items-center gap-1 rounded-lg bg-brand-900 text-white px-3 py-1.5 text-[11px] font-medium hover:bg-brand-800 transition">${icon('check2','w-3 h-3')} ${r.proposedValue!=null?i18t('co_accept_apply_value'):i18t('co_accept')}</button>
                <button data-nego-reject="${r.n}" class="rounded-lg border border-brand-200 text-brand-700 px-3 py-1.5 text-[11px] font-medium hover:bg-brand-50 transition">${i18t('co_reject')}</button>`}
              </div>`:`<div class="mt-2 text-[11px] text-brand-800/65">${i18t('co_awaiting_approver')}</div>`)
            :`<div class="mt-1.5 text-[11px] font-medium ${r.resolution?.decision==='accepted'?'text-brand-600':'text-rose-600'}">${r.resolution?.decision==='accepted'?'Accepted':'Rejected'} by ${r.resolution?.by||'—'} · ${r.resolution?fmtDT(r.resolution.at):''}</div>
              ${r.resolution&&r.resolution.comment?`<div class="mt-1 text-[11px] text-brand-800/80 leading-relaxed border-l-2 border-brand-200 pl-2">Your reply: ${String(r.resolution.comment).replace(/</g,'&lt;')}</div>`:''}`}
          </div>`).join('')}
      </div>
      ${resolvedRounds(c).length&&canEdit()&&c.status!=='Signed'?`
        <div style="display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-top:10px;border-top:1px solid var(--color-divider);padding-top:10px">
          <span style="flex:1;min-width:140px;font-size:12px;color:var(--color-neutral-700)">${i18t('co_ready_next_round')}</span>
          <button id="nego-reshare" class="ui-btn ui-btn-primary" style="flex:none;font-size:13px;padding:6px 12px">${icon('send','w-3.5 h-3.5')} ${i18t('co_send_updated')}</button>
        </div>`
      :`<p class="mt-2 text-[10px] text-brand-800/60">${i18t('co_after_resolving')}</p>`}
    </div>`;
  document.getElementById('nego-reshare')?.addEventListener('click',async e=>{
    const btn=e.currentTarget, restore=btn.innerHTML;
    btn.disabled=true; btn.innerHTML=`<span class="animate-pulse">${i18t('co_sending')}</span>`;
    try{
      const out=await reshareToLastRecipient(c);
      const who=out.recipient.name||out.recipient.email||out.recipient.phone||'the counterparty';
      /* FIRST, because it outranks every other outcome: if their copy could not
         be reused, the news is not whether an email went — it is that the URL
         they hold has stopped being the contract. */
      if(out.stranded){
        toast(reshareStrandedLine(who),'err');
      } else if(out.delivered){
        toast(`Updated version emailed to ${who}`);
      } else if(out.quiet){
        /* THE SAME LIE, SECOND PLACE. A round published onto a standing link
           sends nothing ON PURPOSE — the link was emailed once, when the
           negotiation began, and every round after travels through the
           platform. Falling through to reshareNotSentModal told the sender
           "the mail provider refused it" about a send nobody attempted.
           The contract page's own toast has said this correctly all along
           (see the quiet branch in js/views/contract.js); this is the two
           surfaces agreeing rather than a new sentence. */
        toast(i18t('co_round_on_standing_link',{who:esc(who)}));
      } else if(out.channel==='whatsapp' && out.recipient.phone){
        // the same route the first share uses — nothing sends WhatsApp for us
        try{ window.open(waShareLink(out.recipient.phone, shareMessageText(c, out.link, '', null)),'_blank'); }catch(_){}
        toast(`Link updated — WhatsApp opened so you can send it to ${who}`);
      } else {
        reshareNotSentModal(c, out, who);
      }
      renderAuditSection(c); renderSharesSection(c); refreshShareOverview();
    }catch(err){
      // nobody on record to send to — fall back to the full dialog rather than
      // leaving a pressed button that did nothing
      toast(err.message,'err');
      try{ openShareModal(c); }catch(_){}
    }
    btn.disabled=false; btn.innerHTML=restore;
  });
  host.querySelectorAll('[data-nego-accept]').forEach(b=>b.addEventListener('click',()=>resolveRound(c,Number(b.getAttribute('data-nego-accept')),true)));
  host.querySelectorAll('[data-nego-redline]').forEach(b=>b.addEventListener('click',()=>reviewProposedRound(c,Number(b.getAttribute('data-nego-redline')))));
  host.querySelectorAll('[data-nego-reject]').forEach(b=>b.addEventListener('click',async()=>{
    // A rejection the other side cannot understand is a rejection they will
    // re-send. Ask for the reason here, where it is still fresh.
    const why=await promptDialog({ get title(){ return i18t('co_why_turning_down'); },
      message:'This is sent to the counterparty with your decision, so they know what to do next. Leave it blank to reject without a reason.',
      label:'Reply to '+(c.counterparty||'the counterparty'),
      placeholder:'e.g. Net-30 stands, or we can look at a 2% price increase.',
      confirmLabel:'Reject round' });
    if(why==null) return;                       // cancelled — the round stays open
    resolveRound(c,Number(b.getAttribute('data-nego-reject')),false,{ comment:why });
  }));
}
/* resolveRound lives in js/versioning.js, beside acceptProposedRound:
   resolving a round and adopting one are the same decision seen from two
   sides, and the all-rejected branch of adoption has to be able to call it. */

/* ---------- modal helper ---------- */
function openModal(html, opts={}){
  const root=document.getElementById('modal-root');
  const maxw=opts.maxWidth||'32rem';
  // Given an explicit height the panel becomes a fill-the-window shell: it stops
  // scrolling itself and whatever is inside takes charge of its own overflow.
  const sized=opts.height
    ? `height:${opts.height};overflow:hidden;`
    : `max-height:88vh;overflow-y:auto;`;
  root.innerHTML=`
  <div style="position:fixed;inset:0;z-index:70;display:grid;place-items:center;padding:16px">
    <div id="modal-scrim" style="position:absolute;inset:0;background:color-mix(in srgb,#2b2b2d 50%,transparent);"></div>
    <div class="modal-in scroll-thin" style="position:relative;width:100%;max-width:${maxw};${sized}background:var(--color-surface);border:1px solid var(--color-divider);box-shadow:var(--shadow-lg);border-radius:0;">${html}</div>
  </div>`;
  document.getElementById('modal-scrim').addEventListener('click',closeModal);
  // Esc closes, exactly like the scrim click — some modals (Compare, share)
  // otherwise strand keyboard users with no visible way out
  document.addEventListener('keydown',function esc(e){
    if(e.key!=='Escape'){ if(!document.getElementById('modal-scrim')) document.removeEventListener('keydown',esc); return; }
    document.removeEventListener('keydown',esc); closeModal();
  });
  return root;
}
function closeModal(){ document.getElementById('modal-root').innerHTML=''; }

/* ---- A PANEL THAT DOES NOT STAND IN FRONT OF WHAT IT IS TALKING ABOUT ----

   openModal centres its panel and lays a 50% scrim over the page. That is
   right for a dialog you answer and dismiss. It is wrong for FINDINGS: every
   one of them offers "Go to the wording", which scrolls the document behind
   and flashes the clause it means. Centred, the panel sat on top of that
   clause; scrimmed, the whole document was dimmed to half. You pressed the
   button, the page did exactly what it promised, and you could see none of it.

   So this one docks to the right edge, takes the full height, and lays NO
   scrim: the page behind stays bright, scrollable and clickable while it is
   open, which is the entire point. It closes on its own × or on Escape —
   there is no scrim left to click, so it must offer both. Shares #modal-root
   with openModal, so the two can never be open at once. */
function openSidePanel(html, opts={}){
  const root=document.getElementById('modal-root');
  const w=opts.width||'400px';
  root.innerHTML=`
  <aside id="side-panel" class="side-panel-in scroll-thin" role="dialog" aria-label="${String(opts.label||opts.title||'Panel').replace(/"/g,'')}"
    style="position:fixed;top:0;right:0;bottom:0;width:100%;max-width:${w};z-index:70;display:flex;flex-direction:column;background:var(--color-surface);border-left:1px solid var(--color-divider);box-shadow:var(--shadow-lg);">
    <div style="flex:none;display:flex;align-items:center;gap:8px;padding:12px 14px;border-bottom:1px solid var(--color-divider);">
      <span style="font-family:var(--font-heading);font-weight:700;font-size:14px;color:var(--color-text);min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${String(opts.title||'')}</span>
      <button id="side-panel-x" title="${i18t('co_close_esc')}" aria-label="${i18t('act_close')}"
        style="margin-left:auto;flex:none;width:26px;height:26px;border-radius:0;border:1px solid var(--color-divider);background:var(--color-bg);color:var(--color-neutral-600);cursor:pointer;display:grid;place-items:center;padding:0;font:inherit;">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M6 6l12 12M18 6 6 18"/></svg>
      </button>
    </div>
    <div class="scroll-thin" style="flex:1;min-height:0;overflow-y:auto;padding:10px 12px 18px;">${html}</div>
  </aside>`;
  document.getElementById('side-panel-x').addEventListener('click',closeModal);
  document.addEventListener('keydown',function esc(e){
    if(e.key!=='Escape'){ if(!document.getElementById('side-panel')) document.removeEventListener('keydown',esc); return; }
    document.removeEventListener('keydown',esc); closeModal();
  });
  return root;
}

/* Styled confirm — a branded replacement for the native window.confirm().
   Returns a Promise<boolean>. Self-contained overlay (appended to <body>) so it
   never clobbers an open modal in #modal-root. Usage:
     if(!await confirmDialog({title, message})) return; */
function confirmDialog(opts={}){
  const title=opts.title||'Are you sure?';
  const message=opts.message||'';
  const confirmLabel=opts.confirmLabel||'Confirm';
  const cancelLabel=opts.cancelLabel||'Cancel';
  const danger=!!opts.danger;
  const esc=s=>String(s==null?'':s).replace(/[&<>]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[ch]));
  return new Promise(resolve=>{
    const prev=document.getElementById('confirm-overlay'); if(prev) prev.remove();
    const ov=document.createElement('div');
    ov.id='confirm-overlay';
    ov.style.cssText='position:fixed;inset:0;z-index:90;display:grid;place-items:center;padding:16px';
    const btnFg=danger?'#fff':'#fff';
    const btnBg=danger?'var(--danger)':'var(--color-accent)';
    ov.innerHTML=`
      <div style="position:absolute;inset:0;background:color-mix(in srgb,#2b2b2d 50%,transparent)"></div>
      <div class="modal-in" role="alertdialog" aria-modal="true" style="position:relative;width:100%;max-width:30rem;background:var(--color-surface);border:1px solid var(--color-divider);box-shadow:var(--shadow-lg);border-radius:0;padding:22px 24px">
        <div style="display:flex;align-items:flex-start;gap:12px;margin-bottom:${message?'6px':'14px'}">
          <span style="width:34px;height:34px;flex:none;display:grid;place-items:center;border-radius:0;background:${danger?'var(--red-tint,rgba(176,69,60,.1))':'var(--color-accent-100)'};color:${danger?'var(--danger)':'var(--color-accent-700)'}">${icon(danger?'alert':'shield','w-4 h-4')}</span>
          <h3 style="font-family:var(--font-heading);font-weight:600;font-size:17px;margin:0;line-height:1.3;padding-top:5px">${esc(title)}</h3>
        </div>
        ${message?`<p style="font-size:14px;color:var(--color-neutral-700);line-height:1.55;margin:0 0 16px;padding-left:46px">${esc(message)}</p>`:''}
        <div style="display:flex;justify-content:flex-end;gap:8px">
          <button id="cf-cancel" class="ui-btn">${esc(cancelLabel)}</button>
          <button id="cf-ok" class="ui-btn" style="background:${btnBg};border-color:${btnBg};color:${btnFg}">${esc(confirmLabel)}</button>
        </div>
      </div>`;
    document.body.appendChild(ov);
    const done=val=>{ ov.remove(); document.removeEventListener('keydown',onKey); resolve(val); };
    function onKey(e){ if(e.key==='Escape') done(false); else if(e.key==='Enter') done(true); }
    document.addEventListener('keydown',onKey);
    ov.querySelector('#cf-cancel').addEventListener('click',()=>done(false));
    ov.querySelector('#cf-ok').addEventListener('click',()=>done(true));
    ov.addEventListener('click',e=>{ if(e.target===ov||e.target===ov.firstElementChild) done(false); });
    ov.querySelector('#cf-ok').focus();
  });
}

/* Styled prompt — a branded replacement for the native window.prompt().
   Returns a Promise<string|null>; null means cancelled, so an empty string is
   still distinguishable from "no answer". Same overlay contract as
   confirmDialog: appended to <body> at a higher z-index than #modal-root, so it
   stacks over an open modal instead of clobbering it. Usage:
     const name = await promptDialog({title, label, value});
     if(name==null) return; */
function promptDialog(opts={}){
  const title=opts.title||'';
  const message=opts.message||'';
  const label=opts.label||'';
  const placeholder=opts.placeholder||'';
  const confirmLabel=opts.confirmLabel||'OK';
  const cancelLabel=opts.cancelLabel||'Cancel';
  const esc=s=>String(s==null?'':s).replace(/[&<>]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[ch]));
  return new Promise(resolve=>{
    const prev=document.getElementById('prompt-overlay'); if(prev) prev.remove();
    const ov=document.createElement('div');
    ov.id='prompt-overlay';
    ov.style.cssText='position:fixed;inset:0;z-index:92;display:grid;place-items:center;padding:16px';
    ov.innerHTML=`
      <div style="position:absolute;inset:0;background:color-mix(in srgb,#2b2b2d 50%,transparent)"></div>
      <div class="modal-in" role="dialog" aria-modal="true" style="position:relative;width:100%;max-width:30rem;background:var(--color-surface);border:1px solid var(--color-divider);box-shadow:var(--shadow-lg);border-radius:0;padding:22px 24px">
        <div style="display:flex;align-items:flex-start;gap:12px;margin-bottom:${message?'6px':'12px'}">
          <span style="width:34px;height:34px;flex:none;display:grid;place-items:center;border-radius:0;background:var(--color-accent-100);color:var(--color-accent-700)">${icon('pencil','w-4 h-4')}</span>
          <h3 style="font-family:var(--font-heading);font-weight:600;font-size:17px;margin:0;line-height:1.3;padding-top:5px">${esc(title)}</h3>
        </div>
        ${message?`<p style="font-size:14px;color:var(--color-neutral-700);line-height:1.55;margin:0 0 12px;padding-left:46px">${esc(message)}</p>`:''}
        <div style="padding-left:46px">
          ${label?`<label for="pd-input" style="display:block;font-size:12px;font-weight:600;color:var(--color-neutral-700);margin-bottom:4px">${esc(label)}</label>`:''}
          ${opts.multiline
            ? /* A REASON IS NOT A ONE-LINE ANSWER. box-sizing so the padding
                 counts inside, width:100% so it tracks the dialog rather than
                 its own cols attribute, and overflow-wrap so a pasted
                 reference with no spaces in it wraps instead of scrolling the
                 field sideways. Same three declarations as the clause
                 editor's reason box, and for the same reason. */
              `<textarea id="pd-input" rows="3" wrap="soft" placeholder="${esc(placeholder).replace(/"/g,'&quot;')}"
                 style="box-sizing:border-box;width:100%;max-width:100%;min-height:70px;resize:vertical;border:1px solid var(--color-divider);background:var(--color-bg);border-radius:0;padding:8px 11px;font:inherit;font-size:14px;line-height:1.6;outline:none;white-space:pre-wrap;overflow-wrap:anywhere">${esc(opts.value)}</textarea>`
            : `<input id="pd-input" type="text" value="${esc(opts.value).replace(/"/g,'&quot;')}" placeholder="${esc(placeholder).replace(/"/g,'&quot;')}"
                 style="width:100%;border:1px solid var(--color-divider);background:var(--color-bg);border-radius:0;padding:8px 11px;font:inherit;font-size:14px;outline:none"/>`}
          <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px">
            <button id="pd-cancel" class="ui-btn">${esc(cancelLabel)}</button>
            <button id="pd-ok" class="ui-btn ui-btn-primary">${esc(confirmLabel)}</button>
          </div>
        </div>
      </div>`;
    document.body.appendChild(ov);
    const input=ov.querySelector('#pd-input');
    const done=val=>{ ov.remove(); document.removeEventListener('keydown',onKey,true); resolve(val); };
    function onKey(e){
      if(e.key==='Escape'){ e.preventDefault(); e.stopPropagation(); done(null); }
      /* Enter submits a one-line field and types a newline in a multiline one,
         which is what every text box on every platform already does. */
      else if(e.key==='Enter' && !opts.multiline){ e.preventDefault(); e.stopPropagation(); done(input.value); }
    }
    // capture phase: an open modal behind this one may also listen for Escape
    document.addEventListener('keydown',onKey,true);
    ov.querySelector('#pd-cancel').addEventListener('click',()=>done(null));
    ov.querySelector('#pd-ok').addEventListener('click',()=>done(input.value));
    ov.addEventListener('click',e=>{ if(e.target===ov||e.target===ov.firstElementChild) done(null); });
    input.focus(); if (input.select && !opts.multiline) input.select();
  });
}

/* ---------- document sealing ----------
   For a generated contract the seal covers the field values; for an uploaded
   ("inbound") document it covers the file's own hash, so the seal proves
   exactly which file you signed. */
// Used only for the share-link doc fingerprint (change detection).
/* C-3: the share-link change-detection fingerprint MUST cover the negotiated
   body. It used to hash only the field values, so an edit to a clause's wording
   (c.redlineText) left the fingerprint unchanged — the owner could revise the
   text after the counterparty approved, and the "did this change?" check saw
   nothing. The body is canonicalised the same way the seal and the version
   fingerprint are (canonicalDocString normalises formatting-only churn), so a
   real wording change trips the check while a cosmetic reformat does not. */
const canonicalDoc = c => isUpload(c)
  ? JSON.stringify({ id:c.id, source:'upload', fileName:c.upload?.fileName, fileHash:c.upload?.fileHash,
      firstParty:contractParty(c), counterparty:c.counterparty, value:c.value })
  : JSON.stringify({ id:c.id, template:c.template, name:c.name,
      firstParty:contractParty(c), counterparty:c.counterparty, value:c.value, valueType:c.valueType, fields:c.fields,
      body: c.redlineText ? ((window.canonicalDocString) ? canonicalDocString(c.redlineText, c.format) : String(c.redlineText)) : '' });

/* Evidence-grade sealing:
   at signature we FREEZE the fully-rendered contract text (values baked in),
   hash that exact text, and from then on the workspace renders the frozen
   copy — so what was sealed is always what is shown. The seal binds the
   frozen text (or, for uploads, the file bytes) to the parties and value. */
/* A READ-ONLY projection of a contract's document.
   `docBody()` renders a template's terms as <input> elements so the owner can
   complete them in place. Disabling them (PORTAL_MODE) stops the counterparty
   typing, but an <input> still holds its text in a `value` attribute rather
   than in the document — so the moment the document leaves the live browser
   view (copy/paste, print, PDF, any text projection) every commercial term
   silently disappears and the contract reads "made on ___ between X and ___".
   This substitutes each field for the text it holds, exactly as
   freezeContractHtml() does at signing, so what the counterparty reads, copies
   and prints is the same text that will be sealed. An empty field becomes an
   em-dash rather than nothing, so an unfilled term is visible as a gap the
   reader can point at. */
function readOnlyDocHtml(html){
  const tmp=document.createElement('div');
  tmp.innerHTML=String(html||'');
  tmp.querySelectorAll('input,textarea').forEach(inp=>{
    const s=document.createElement('span');
    /* The monospace has gone — see .field-frozen in index.html. A commercial
       term reads as part of the sentence it sits in, not as a code sample. */
    s.className='field-frozen';
    const v=fieldDisplayValue(inp);
    s.textContent=v||'—';
    if(!v) s.setAttribute('title',i18t('ct_term_not_filled'));
    inp.replaceWith(s);
  });
  return tmp.innerHTML;
}
function freezeContractHtml(c){
  // E2: if an accepted redline replaced the drafted text, seal that exact text.
  if(c.redlineText){
    // Rich working text freezes as the SANITISED fragment — never the raw
    // stored string. What gets sealed is exactly what the renderer will show.
    if(window.isRich && isRich(c.format)){
      return `<div class="hati-doc" data-anchor="redline">${sanitizeRich(c.redlineText)}</div>`;
    }
    const d=document.createElement('div');
    d.innerHTML=`<div class="text-[13.5px] leading-[1.9] text-brand-800/85 whitespace-pre-wrap" data-anchor="redline">${String(c.redlineText).replace(/[&<>]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[ch]))}</div>`;
    return d.innerHTML;
  }
  const tmp=document.createElement('div');
  tmp.innerHTML=docBody(c);
  tmp.querySelectorAll('.seal-in,[data-anchor="sig"]').forEach(el=>el.remove());
  tmp.querySelectorAll('input,textarea').forEach(inp=>{
    const s=document.createElement('span');
    s.className='font-mono font-semibold text-brand-900';
    s.textContent=fieldDisplayValue(inp)||'—';
    inp.replaceWith(s);
  });
  return tmp.innerHTML;
}
const normText = html => { const d=document.createElement('div'); d.innerHTML=html||''; return (d.textContent||'').replace(/\s+/g,' ').trim(); };

/* The exact string a frozen document is hashed over. VERSION-GATED, because
   every contract sealed before rich content existed was hashed with normText()
   and must keep verifying against the hash it was given:

     hashMode absent / 'text' → normText(html)      — unchanged, forever
     hashMode 'rich'          → canonicalRich(html) — formatting is part of the
                                                      document, so the seal binds it

   An old record has no hashMode, takes the first branch, and produces a
   byte-identical input to what it produced before this run. Nothing about a
   pre-existing seal moves. (See DESIGN-rich-documents.md.) */
function execHashInput(exec){
  const html=(exec&&exec.html)||'';
  if(exec && exec.hashMode==='rich' && window.canonicalRich) return canonicalRich(html);
  return normText(html);
}
function sealString(c){
  const content = isUpload(c) ? 'file:'+(c.upload?.fileHash||'') : 'text:'+(c.execution?.textHash||'');
  /* H-6: the seal must bind the first-party name AS IT WAS AT SIGNING, not the
     live workspace name. It used to read the FIRST_PARTY global, which is set
     from the org name at each login — so renaming the workspace (a corrected
     legal name, a re-setup) made every previously-sealed contract recompute to
     a different string and verifySeal cried "MISMATCH" on untouched records.
     The name is now frozen onto c.execution at signing and read from there;
     records sealed before this change have no frozen name and fall back to the
     live global exactly as before, so their verification is unchanged. */
  const firstParty=(c.execution&&c.execution.firstParty)||FIRST_PARTY;
  const base={ id:c.id, firstParty, counterparty:c.counterparty,
    value:c.value, valueType:c.valueType, content, signedAt:c.execution?.at||'' };
  // Seal v2 folds every signature MARK (its hash) into the seal, so the visible
  // signatures are as tamper-evident as the text. v1 (sealVersion unset) keeps
  // the exact original string — so every previously-sealed contract still verifies.
  if(Number(c.sealVersion||0)>=2){
    base.sigs=(c.signatures||[]).map(s=>({ name:s.name||'', at:s.at||'', form:s.form||s.method||'', imageHash:s.imageHash||'' }));
  }
  return JSON.stringify(base);
}

async function verifySeal(c){
  if(!c.hash){ toast(i18t('co_not_sealed'),'err'); return; }
  if(c.hash==='PRE-SEEDED'){ toast(i18t('co_sample_presealed'),'err'); return; }
  if(c.hash==='MIGRATED'){ toast(`Migrated contract — executed outside HaTi. The uploaded file's own SHA-256 (${(c.upload?.fileHash||'').slice(0,16)}…) is the evidence of record`); return; }
  if(!isUpload(c)){
    if(!c.execution?.html){ toast(i18t('co_no_snapshot'),'err'); return; }
    const th=await sha256(execHashInput(c.execution));
    if(th!==c.execution.textHash){ toast(i18t('co_seal_mismatch_text'),'err'); return; }
  }
  // v2: each stored signature mark must still hash to the value bound at signing.
  if(Number(c.sealVersion||0)>=2){
    for(const s of (c.signatures||[])){
      if(s.image && s.imageHash){ const ih=await sha256(s.image);
        if(ih!==s.imageHash){ toast(i18t('co_seal_mismatch_mark'),'err'); return; } }
    }
  }
  const h=await sha256(sealString(c));
  if(h!==c.hash){ toast(i18t('co_seal_mismatch_record'),'err'); return; }
  /* The seal can be perfectly valid and the workspace still be showing
     different wording, because the seal is computed over the frozen copy and
     this asks about the live one. Reported here rather than left to be noticed,
     since "Seal valid" on a screen whose text nobody signed is the most
     misleading thing this button could say. */
  const div=(typeof executedDivergence==='function')?executedDivergence(c):null;
  if(div){ toast(i18t('co_seal_valid_but')
    +'the sealed copy is the evidence of record','err'); return; }
  /* ---- AND A WEAK SEAL IS NAMED (owner-ruled 14 Aug 2026) ----
     sha256 falls back to a 32-bit rolling hash when crypto.subtle is missing —
     which browsers withhold outside a secure context — and that fallback is
     correct: refusing to let anybody sign because the connection is not https
     would be worse. What was wrong is what this button said afterwards. It
     reported "Seal valid" with exactly the same confidence over a fingerprint
     with eight characters of real information in it, repeated to fill the shape
     of a real one, so the two are indistinguishable on screen.

     Two other surfaces in the product already say this — the settings
     integrity check and negoIntegrityReport's 'weak-digest' — and this one
     simply never asked. Asked BEFORE the comparison as well as reported after,
     because sha256IsReal() answers for the fallback having been used at all,
     not only for this call. */
  const weak=(typeof sha256IsReal==='function')&&!sha256IsReal();
  const ok=isUpload(c)?'Seal valid — file and parties are intact':'Seal valid — sealed text, parties and value are intact';
  if(weak){ toast(`${ok}. ${i18t('co_seal_weak')}`,'err'); return; }
  toast(ok);
}
function downloadFile(name, content, type='application/json'){
  const a=document.createElement('a');
  a.href=URL.createObjectURL(new Blob([content],{type}));
  a.download=name; a.click(); URL.revokeObjectURL(a.href);
}
function downloadEvidence(c){
  downloadFile(`${c.id}-evidence-pack.json`, JSON.stringify({
    generatedAt:nowISO(), platform:'HaTi CLM', org:FIRST_PARTY,
    // a migrated contract was signed elsewhere — citing the e-signature Act
    // here would claim HaTi took a signature it never took
    legalBasis: isExternallyExecuted(c)
      ? 'Executed outside HaTi and migrated in as a record. No electronic signature was taken in HaTi; the signatures are on the original document.'
      : jxEsignature(),
    disclosure:'Government IPRS identity verification and CAK-accredited PKI signatures are not yet integrated.',
    /* THE AGREEMENT IS ONLY AS WELL PROVED AS ITS LEAST-PROVED SIGNATURE, so
       this is the WEAKEST rung and not the best one — the flattering reading
       is the one a dispute destroys. */
    assurance:(()=>{ const a=(typeof contractAssurance==='function')?contractAssurance(c):null;
      return a?{ key:a.key, label:String(a.rung.label), basis:String(a.rung.basis),
        derived:!!a.derived, note:'The lowest assurance among the signatures below.' }:null; })(),
    migration: isExternallyExecuted(c)
      ? { filedBy:(c.migration&&c.migration.importedBy)||null, filedAt:(c.migration&&c.migration.importedAt)||null,
          batch:(c.migration&&c.migration.batch)||null,
          get note(){ return i18t('co_executed_on_note'); } }
      : null,
    contract:{ id:c.id, name:c.name, type:cKind(c), counterparty:c.counterparty,
      value:c.value, valueType:c.valueType, status:c.status },
    seal:{ sha256:c.hash, signedAt:c.signedAt,
      sealedTextSha256:c.execution?.textHash||null,
      sealedFileSha256:isUpload(c)?(c.upload?.fileHash||null):null,
      sealedText:isUpload(c)?null:normText(c.execution?.html||''),
      uploadedFile:isUpload(c)?{ name:c.upload?.fileName, size:c.upload?.size }:null },
    // `capacity` is the whole point of a signature block and was missing from
    // the pack entirely: the document that exists to prove a signature did not
    // say in what capacity anyone signed. Empty means none was recorded — it is
    // never back-filled from a permission level.
    signatures:(c.signatures||[]).map(s=>({ party:s.party, name:s.name, email:s.email||null,
      capacity:signatureCapacity(s)||null,
      method:s.method||null, form:s.form||null, signatureImageSha256:s.imageHash||null, signatureImage:s.image||null,
      /* W3-3: WHAT WAS PROVED, in the pack that exists to answer exactly
         that. `assuranceDerived` is not a footnote — a reader must be able
         to tell a recorded fact from an inference drawn years later. */
      assurance:(()=>{ const a=(typeof signatureAssurance==='function')?signatureAssurance(s,c):null;
        return a?a.key:null; })(),
      assuranceLabel:(()=>{ const a=(typeof signatureAssurance==='function')?signatureAssurance(s,c):null;
        return a&&a.rung?String(a.rung.label):null; })(),
      assuranceBasis:(()=>{ const a=(typeof signatureAssurance==='function')?signatureAssurance(s,c):null;
        return a&&a.rung?String(a.rung.basis):null; })(),
      assuranceDerived:(()=>{ const a=(typeof signatureAssurance==='function')?signatureAssurance(s,c):null;
        return a?!!a.derived:null; })(),
      ip:s.ip||null, userAgent:s.ua||null, at:s.at })),
    distribution:c.distribution||null,
    auditTrail:c.audit||[],
  },null,2));
  logAudit(c,'Exported','Evidence pack downloaded'); persist(c); renderAuditSection(c);
  toast(i18t('co_evidence_downloaded'));
}

/* ---------- readiness: is this contract fit to leave the building? ----------
   The workspace already knows when a contract is incomplete — the action bar
   says "Complete key terms" and the Signing panel refuses to enable the button.
   Sharing consulted none of it, so a draft with no price, no dates and unfilled
   placeholders went to the counterparty in silence. This is that same knowledge
   in one place, so the share modal and the sign gate ask the same question.

   Returns [] when the contract is ready. Each problem has a `severity`:
   'block' — must be acknowledged before sending; 'warn' — worth saying. */
const PLACEHOLDER_RE = /\[[A-Z][A-Z0-9 ,.'&\/-]{2,60}\]|\{\{\s*[\w.-]+\s*\}\}|_{4,}/g;
function contractPlaceholders(c){
  if(isUpload(c)) return [];                 // their paper — brackets are theirs
  let text='';
  try{
    // The rendered text projection, so a value typed into a template field
    // counts as filled and only genuinely empty ones are reported.
    const html=(c.status==='Signed'&&c.execution&&c.execution.html)||docBody(c);
    const d=document.createElement('div');
    d.innerHTML=readOnlyDocHtml(html);
    text=d.innerText||'';
  }catch(e){
    text=(typeof c.redlineText==='string'?c.redlineText:'')||'';
  }
  const hits=String(text).match(PLACEHOLDER_RE)||[];
  // an em-dash from readOnlyDocHtml is an unfilled template field, not a
  // placeholder string — counted separately by the key-terms checks below
  return [...new Set(hits.map(h=>h.trim()))].slice(0,12);
}
function contractReadiness(c){
  const p=[];
  if(!c) return p;
  const add=(severity,key,label)=>p.push({ severity, key, label });
  if(!String(c.counterparty||'').trim()) add('block','counterparty','No counterparty is set.');
  if(isMonetary(c) && !(Number(c.value)>0))
    add('block','value','No contract value is set, and this contract type carries one.');
  if(!c.expiry && !(c.fields&&c.fields.expiry) && (c.metadata||{}).renewalType!=='evergreen')
    add('warn','term','No expiry or term end is recorded, so no renewal reminder can be scheduled.');
  if(!c.effectiveDate && !(c.fields&&c.fields.effDate))
    add('warn','effective','No effective date is recorded.');
  const ph=contractPlaceholders(c);
  if(ph.length) add('block','placeholders',
    `The document still contains ${ph.length} unfilled placeholder${ph.length===1?'':'s'}: ${ph.slice(0,5).join(', ')}${ph.length>5?', …':''}`);
  /* INTERNAL APPROVAL IS PART OF BEING READY TO SEND, and it was not on this
     list. Signing checks it — signDocument refuses outright — but sharing
     never did, and sharing is how a contract actually reaches the other side:
     a link sent with purpose 'sign' puts the counterparty in front of a
     signature panel, and their signature executes the contract through
     applyResponse without the owner touching the Sign button at all. So the
     one gate that existed could be walked straight past by pressing Share.

     Read through `window` so the rule-chain version in js/approvals.js is the
     one that answers — js/core.js declares its own legacy approvalState below,
     and a bare call would resolve to that lexical binding for ever. */
  /* AND THE SEVERITY IS NOT THE SAME IN ALL THREE CASES. Sending a draft out
     for comment while approval is still working its way through is not a
     mistake — it is the ordinary order of events, and making the sender tick an
     acknowledgement for it would teach them to tick acknowledgements. A
     REFUSAL is different: somebody said no, and putting that wording in front
     of the counterparty anyway is a decision the sender should have to own. So
     is a sign-off the contract has since moved out from under. */
  try{
    const ap=(window.approvalState)?window.approvalState(c):null;
    if(ap && ap.required && !ap.ok){
      const refused=(ap.rejected||[])[0], stale=(ap.stale||[])[0];
      if(refused) add('block','approval',
        `Internal approval was refused${refused.by?` by ${refused.by}`:''} — “${refused.name}” is unresolved.`);
      else if(stale) add('block','approval',
        `“${stale.name}” was approved and the contract has changed since — it needs approving again.`);
      else add('warn','approval',
        `Internal approval is outstanding: “${ap.next?ap.next.name:'approval'}” is waiting on ${ap.approverLabel||'an approver'}. This contract cannot go out for signature until it clears.`);
    }
  }catch(_){ /* a readiness list that cannot be built is not a reason to block */ }
  /* AND THE OTHER GATE, THE EARLIER ONE. Approval above governs SIGNING; this
     governs the redlines going out at all. It is a block rather than a warning
     for the reason the refusal case above is: the workspace has said in its own
     settings that wording of this kind does not leave without being looked at,
     and a warning is something a sender ticks past. */
  try{
    /* The reader's own posture blocks first: it is about THEM rather than about
       the contract, so it is true even where the gate is off, and it is the
       more useful sentence when both apply. */
    /* Not being the lead of this negotiation belongs on the readiness list for
       the same reason the reviewer's posture does: the panel exists to say why
       the send will refuse before somebody fills in a form that was never going
       to go anywhere. */
    if(window.deskSendBlock){
      const dm=deskSendBlock(c);
      if(dm) add('block','desk',dm);
    }
    if(window.reviewActorBlockMessage){
      const am=reviewActorBlockMessage(c);
      if(am) add('block','review',am);
    }
    if(window.reviewGateMessage){
      const rm=reviewGateMessage(c);
      if(rm) add('block','review',rm);
    }
  }catch(_){ /* same: an unreadable gate must not take the panel down with it */ }
  if(c.status==='Draft') add('warn','status','This contract is still a Draft.');
  const sig=(c.signatories||c.signers||[]).filter(s=>s&&(s.name||s.email));
  if(window.SIGN_ROUTE_ON && !sig.length) add('warn','signatory','No named signatory is set on the signature block.');
  return p;
}
const readinessBlocks = c => contractReadiness(c).filter(x=>x.severity==='block');
/* ---------- counterparty share links ---------- */
const b64e = obj => btoa(unescape(encodeURIComponent(JSON.stringify(obj)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const b64d = str => { try{ return JSON.parse(decodeURIComponent(escape(atob(String(str).trim().replace(/-/g,'+').replace(/_/g,'/'))))); }catch(e){ return null; } };

// Prefilled WhatsApp deep link: opens the sender's own WhatsApp with the
// message ready to send — no Business API needed, and the recipient sees a
// number they recognise. The portal link itself carries the tracking.
const waShareLink=(phone,text)=>'https://wa.me/'+String(phone||'').replace(/[^\d]/g,'')+'?text='+encodeURIComponent(text);
const shareMessageText=(c,link,msg,expiresAt)=>
  `${currentUser().name} at ${FIRST_PARTY} shared "${c.name}" for your review.`
  +(msg?`\n\n${msg}`:'')
  +`\n\nOpen it here — review, sign, request changes or decline, no account needed:\n${link}`
  +(expiresAt?`\n\nThis link expires on ${String(expiresAt).slice(0,10)}.`:'');

/* ---------- what is this link FOR? ----------
   A share carries a purpose, and the purpose decides which screen the other
   side lands on: the negotiation room, or a signing panel. Every caller that
   had an opinion stated one — the room says 'negotiate', the signing route says
   'sign' — and the ONE caller nobody thought about is the Share button in the
   contract toolbar, which is the button a first-time user actually presses.

   It stated nothing, so buildSharePayload fell back to reading the change set:
   no changes yet means nobody has negotiated, which it took to mean "this is a
   signature request". On a first draft that reading is exactly backwards. The
   first send of a negotiation went out labelled `sign`, and the counterparty's
   first sight of a contract nobody had discussed was a green tick and the words
   "Ready to sign".

   So the default is now a read of whether the deal is FINISHED, not of whether
   it has started, and the dialog states the answer out loud where the sender
   can change it. */
function defaultSharePurpose(c){
  if(!c) return 'sign';
  if(c.status==='Signed') return 'sign';
  /* Read c.changes directly rather than through negoChanges: this is asked of
     contracts loaded as summaries, and a read must not stamp clause ids into a
     document (see negoAlignment for the same care). */
  const live=(Array.isArray(c.changes)?c.changes:[]).filter(x=>x&&x.status!=='superseded');
  /* Sign is the default when nothing is on the table (Young, 02 Aug 2026):
     most contracts go out to be signed, not argued over, and the sender who
     wants a review round picks Negotiate consciously. The one state that
     still preselects Negotiate is an OPEN negotiation — a signing link over
     unresolved changes is the mistake the room exists to prevent. */
  /* ---- AND SIGN IS NOT PRESELECTED WHERE IT CANNOT BE SENT ----
     Naming the signers is what opens signing (11 Aug 2026), so a Sign link on
     a contract with no route is refused — by this dialog, and by the server
     behind it. Preselecting it there made the QUIET PATH THROUGH THE FORM A
     BLOCKED ONE: open Share on a clean contract, take the default, fill in the
     recipient, press Send, and only then be told no. Reported the day the rule
     shipped, with the reasonable question "how am I supposed to send a
     contract that is just for the counterparty to read?"

     So the default follows what the contract can actually do. Sign stays FIRST
     in the picker and stays one press away — it is still the commonest intent
     — but choosing it is now the deliberate act the rule was asked for, and
     the amber block beside it says what naming the signers is for. */
  /* signingRouteOpen (js/approvals.js) is the authority and is asked first.
     The fallback is its one line rather than an optimistic `true`, because a
     default that quietly reverts to the refused answer wherever that module
     has not loaded is a rule that works everywhere except where it is tested. */
  const routed=(typeof window!=='undefined' && window.signingRouteOpen)
    ? signingRouteOpen(c)
    : (Array.isArray(c.signerPlan)?c.signerPlan:[]).some(s=>s && s.party==='counterparty');
  if(!routed) return 'negotiate';
  if(!live.length) return 'sign';
  const settled=live.every(x=>x.status==='accepted'||(x.status==='rejected'&&x.withdrawn));
  return settled?'sign':'negotiate';
}
const SHARE_PURPOSE_COPY={
  negotiate:{ label:'Negotiate', get title(){ return i18t('co_purpose_negotiate'); },
    get blurb(){ return i18t('co_purpose_negotiate_sub'); } },
  sign:{ get label(){ return i18t('act_sign'); }, get title(){ return i18t('co_purpose_sign'); },
    get blurb(){ return i18t('co_purpose_sign_sub'); } },
  view:{ get label(){ return i18t('co_purpose_view'); }, get title(){ return i18t('co_purpose_view_sub'); },
    blurb:'For an advisor, an insurer, a lawyer being asked whether this is normal. They see the wording and the redlines as they stand today, and cannot respond, edit or sign. Your comments and internal notes never leave this workspace.' },
};
/* ---------- THE FIRST QUESTION, WHICH USED NOT TO BE ASKED ----------
   Share opened straight into "what is this link for?" and offered Sign and
   Negotiate. It never asked the question above that one: is the CONTRACT
   travelling, or the record of the argument about it? Those are different
   objects with different readers — the counterparty signs a contract; an
   advisor, an auditor or a colleague is handed a history — and with no place
   to ask it, there was nowhere to put "just the history".

   It is a step of its own rather than a fourth card beside Sign and Negotiate,
   because a fourth card there would be answering a different question from the
   three next to it. Sign, Negotiate and View only are things somebody does TO A
   CONTRACT; none of them means anything about a record. Two questions, each
   with one kind of answer — and the dense second screen loses a section.

   The history option is offered only where there is a history: a contract
   nobody has proposed anything on has no record to send. */
function shareKindOptionsHtml(c, sel){
  const hasHistory = !!(window.negoAllChanges && negoAllChanges(c).some(x => x && x.status !== 'superseded'));
  const card = (k, title, blurb, on, disabled) => `
    <button type="button" data-share-kind="${k}" aria-pressed="${on?'true':'false'}"${disabled?' disabled':''}
      style="display:flex;gap:11px;align-items:flex-start;text-align:left;width:100%;font:inherit;
      cursor:${disabled?'not-allowed':'pointer'};opacity:${disabled?'.5':'1'};border-radius:0;padding:13px 14px;
      border:1.5px solid ${on?'var(--color-accent)':'var(--color-divider)'};
      background:${on?'var(--color-accent-100)':'var(--color-surface)'}">
      <span style="flex:none;margin-top:2px;width:13px;height:13px;border-radius:50%;
        border:1.5px solid ${on?'var(--color-accent)':'var(--color-neutral-500)'};
        background:${on?'var(--color-accent)':'transparent'};
        box-shadow:${on?'inset 0 0 0 2.5px var(--color-surface)':'none'}"></span>
      <span style="min-width:0">
        <span style="display:block;font-size:14px;font-weight:700;color:${on?'var(--color-accent-800)':'var(--color-text)'}">${title}</span>
        <span style="display:block;font-size:12px;line-height:1.5;color:var(--color-neutral-600);margin-top:3px">${blurb}</span>
      </span>
    </button>`;
  return `
    <div id="share-kind" style="display:flex;flex-direction:column;gap:9px">
      ${card('contract','The contract',
        'The wording, with whatever they are allowed to do to it — sign it, propose changes to it, or read it and nothing more.',
        sel!=='history', false)}
      ${card('history','The negotiation history',
        hasHistory
          ? 'The Negotiation history screen, opened by somebody with no account — every change, who asked, and what was decided. Read-only: the agreement itself does not travel and there is nothing on it to sign.'
          : 'Nothing has been proposed on this contract yet, so there is no record to send.',
        sel==='history', !hasHistory)}
    </div>`;
}
function shareKindStepHtml(c, sel){
  return `
    <div id="share-step-kind">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;"><span style="display:inline-flex;color:var(--color-accent);">${icon('share')}</span>
        <h2 style="font-family:var(--font-heading);font-weight:600;font-size:18px;color:var(--color-text);margin:0;">${i18t('co_what_sharing')}</h2></div>
      <p style="font-size:13px;color:var(--color-neutral-700);margin:0 0 12px;line-height:1.55;">${i18t('co_one_question')}</p>
      ${shareKindOptionsHtml(c, sel)}
      <div style="margin-top:14px;display:flex;align-items:center;gap:8px;justify-content:flex-end;">
        <button id="share-close-kind" class="ui-btn">${i18t('act_close')}</button>
        <button id="share-kind-next" class="ui-btn ui-btn-primary">Next ${icon('arrow-right','w-3.5 h-3.5')}</button>
      </div>
    </div>`;
}
function sharePurposePickerHtml(c, sel){
  const btn=(k)=>{ const on=sel===k, m=SHARE_PURPOSE_COPY[k];
    return `<button type="button" data-share-purpose="${k}" aria-pressed="${on?'true':'false'}"
      style="flex:1;min-width:190px;text-align:left;cursor:pointer;font:inherit;border-radius:0;padding:10px 12px;
      border:1.5px solid ${on?'var(--color-accent)':'var(--color-divider)'};
      background:${on?'var(--color-accent-100)':'var(--color-surface)'}">
      <span style="display:flex;align-items:center;gap:7px">
        <span style="flex:none;width:13px;height:13px;border-radius:50%;border:1.5px solid ${on?'var(--color-accent)':'var(--color-neutral-500)'};
          background:${on?'var(--color-accent)':'transparent'};box-shadow:${on?'inset 0 0 0 2.5px var(--color-surface)':'none'}"></span>
        <span style="font-size:14px;font-weight:700;color:${on?'var(--color-accent-800)':'var(--color-text)'}">${m.label}</span>
      </span>
      <span style="display:block;font-size:13px;font-weight:600;color:var(--color-text);margin:5px 0 2px">${m.title}</span>
      <span style="display:block;font-size:12px;line-height:1.5;color:var(--color-neutral-600)">${m.blurb}</span>
    </button>`; };
  return `<div id="share-purpose" style="margin:0 0 14px">
    <span style="display:block;font-size:12px;font-weight:600;color:var(--color-neutral-700);margin-bottom:6px;font-family:var(--font-mono);letter-spacing:.02em">${i18t('co_what_link_for')}</span>
    ${''/* Sign leads: most sends are "here it is, sign it" (Young, 02 Aug
         2026). The default SELECTION still follows the contract's reality —
         defaultSharePurpose keeps Negotiate preselected while changes are
         open, because a signing link over an unresolved argument is the
         mistake the rest of the product exists to prevent.

         VIEW ONLY IS THE THIRD, AND IT WAS BUILT AND NOT OFFERED. The purpose
         existed, the server enforced it, the counterparty's page honoured it
         and the PHONE offered all three — this dialog offered two. Reported by
         the owner (11 Aug 2026): "I am trying to send the contract without
         signers just for viewing", pressed Send on a Sign link and was refused
         with no third door on the screen to take instead. That is the
         duplication rule walked again: a control that exists on one shell and
         not the other. It is last because it is the rarest of the three. */}
    <div style="display:flex;gap:8px;flex-wrap:wrap">${btn('sign')}${btn('negotiate')}${btn('view')}</div>
  </div>`;
}

/* ---------- step 1 of Share: what am I actually sending? ----------
   Share used to open straight onto the send form, which asked someone to
   dispatch a contract to another company without once showing them what had
   changed since it last went out. Six rounds in, nobody can hold that in their
   head.

   So the dialog now opens on the answer, and Next goes to the form. The list is
   quoted from the change records (negoChangeSummary) and never composed — the
   sender can edit it, because a covering note is theirs to write, but the
   fingerprints and clause names it starts from are the record's. */
function shareSummaryStepHtml(c, opts={}){
  const s = (typeof negoChangeSummary==='function') ? negoChangeSummary(c) : null;
  const rows = s && s.lines.length ? s.lines.map(x=>`
    <li style="display:flex;gap:9px;align-items:flex-start;padding:7px 0;border-bottom:1px solid var(--color-divider)">
      <span style="flex:none;font-family:var(--font-mono);font-size:12px;font-weight:700;border:1.5px solid var(--color-accent);
        color:var(--color-accent);border-radius:0;padding:1px 7px;margin-top:1px">#${esc(x.id)}</span>
      <span style="flex:1;min-width:0">
        <span style="display:block;font-size:14px;font-weight:600;color:var(--color-text);line-height:1.45">${esc(x.summary||x.kind)}</span>
        <span style="display:block;font-size:12px;color:var(--color-neutral-600);margin-top:1px">${esc(x.clause)} · ${esc(x.kind)} · ${esc(x.mine?'yours':x.author)}</span>
      </span>
      <span style="flex:none;font-size:11px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;border-radius:0;padding:2px 6px;margin-top:1px;
        background:${x.status==='accepted'?'var(--st-green-bg)':x.status==='rejected'?'var(--st-ruby-bg)':'var(--st-amber-bg)'};
        color:${x.status==='accepted'?'var(--st-green-fg)':x.status==='rejected'?'var(--st-ruby-dot)':'var(--st-amber-fg)'}">${esc(x.status)}</span>
    </li>`).join('') : '';
  const FLD='width:100%;border:1px solid var(--color-divider);background:var(--color-surface);border-radius:0;padding:8px 10px;font-size:13px;font-family:var(--font-body);color:var(--color-text);outline:none;line-height:1.5;';
  /* Which of the two things the first step chose. Both branches render, and the
     wiring shows one — repainting in place rather than rebuilding, because the
     summary textarea below may already carry words the sender typed. */
  const hist = opts.purposeSel==='history';
  return `
    <div id="share-step-1"${opts.hiddenStart?' class="hidden"':''}>
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;"><span style="display:inline-flex;color:var(--color-accent);">${icon('share')}</span>
        <h2 style="font-family:var(--font-heading);font-weight:600;font-size:18px;color:var(--color-text);margin:0;">${i18t('co_what_you_sending')}</h2></div>
      ${''/* THE PURPOSE QUESTION DOES NOT APPLY TO A RECORD. Sign, Negotiate
             and View only are things somebody does to a contract; a history
             link opens read-only on the timeline and there is nothing on it to
             do. So the picker is not disabled here, it is absent, and the
             screen says why rather than leaving a gap where a question was. */}
      <div id="share-purpose-wrap"${hist?' class="hidden"':''}>${sharePurposePickerHtml(c, opts.purposeSel||defaultSharePurpose(c))}</div>
      ${''/* Drawn always and shown on Sign, like every other branch in this
             step: switching the purpose must not rebuild the dialog, or the
             note the sender has already typed goes with it. */}
      <div id="share-signers"${(opts.purposeSel||defaultSharePurpose(c))==='sign'?'':' class="hidden"'}>${
        shareSignerPickHtml(c, opts.signerSel||null)}</div>
      <div id="share-hist-note"${hist?'':' class="hidden"'} style="margin:0 0 14px;border:1px solid var(--color-accent-300);background:var(--color-accent-100);border-radius:0;padding:10px 12px;font-size:13px;line-height:1.55;color:var(--color-accent-800)">
        <b>${i18t('co_no_purpose')}</b> This link opens the negotiation history and nothing else — the
        same screen ${esc(c.counterparty||'the counterparty')} already sees, read-only. The agreement
        itself does not travel with it, and there is nothing on it to answer or sign.</div>
      ${''/* Both sentences render and one is shown, for the same reason the
             purpose picker is not rebuilt: switching what is being shared must
             not throw away a summary the sender has already edited. */}
      <p id="share-manifest-line"${hist?' class="hidden"':''} style="font-size:13px;color:var(--color-neutral-700);margin:0 0 12px;line-height:1.55;">
        ${s&&s.lines.length
          ? `Round ${s.total?esc(String(s.round)):''} — ${s.lines.length} change${s.lines.length===1?'':'s'} on the table${s.pending?`, ${s.pending} still awaiting a decision`:''}. ${esc(c.counterparty||'The counterparty')} sees this summary alongside the link.`
          : `No changes have been proposed on this contract yet, so ${esc(c.counterparty||'the counterparty')} will receive the document as it currently stands.`}</p>
      <p id="share-manifest-line-hist"${hist?'':' class="hidden"'} style="font-size:13px;color:var(--color-neutral-700);margin:0 0 12px;line-height:1.55;">
        ${s&&s.lines.length
          ? `${s.lines.length} change${s.lines.length===1?'':'s'} on the record — this is what the link shows, oldest first, with what was decided.`
          : `Nothing has been proposed on this contract yet, so there is no record to send.`}</p>
      ${''/* TWO PREVIEWS, BECAUSE THE TWO LINKS SHOW DIFFERENT THINGS.

             The contract branch keeps the manifest: a list of what is going out
             for decision, with each change's fingerprint and its status. That
             is the right preview for a link somebody is going to act on.

             The history branch shows the RECORD — the Negotiation history
             screen itself, the same component the recipient will open. It was
             showing the manifest, which is the wrong list: the manifest says
             what is on the table, and a history link is about what happened.
             Rendered from the product's own negoTimelineScreenHtml so the
             preview cannot drift from the page it is previewing. */}
      <div id="share-manifest"${hist?' class="hidden"':''}>
        ${s&&s.lines.length?`<ul style="list-style:none;margin:0 0 14px;padding:0;max-height:230px;overflow-y:auto;border:1px solid var(--color-divider);border-radius:0;padding:2px 11px">${rows}</ul>`
          :`<div style="margin:0 0 14px;border:1px dashed var(--color-divider);border-radius:0;padding:14px;font-size:13px;color:var(--color-neutral-600);text-align:center">${i18t('co_nothing_proposed')}</div>`}
      </div>
      ${''/* Inert on purpose: this is a picture of the recipient's screen, not
             a second copy of it. Their filters and Verify integrity work; these
             are the same controls with nothing behind them, so they are shown
             (the reader is being told what the link carries) and made
             unclickable rather than left as dead buttons that swallow a press. */}
      <div id="share-hist-preview"${hist?'':' class="hidden"'} style="margin:0 0 14px">
        <style>
          #share-hist-preview .ht{max-height:none;padding:12px 14px;max-width:none}
          #share-hist-preview .ht h3{font-size:15px}
          #share-hist-preview .ht-inert{max-height:330px;overflow-y:auto;border:1px solid var(--color-divider);border-radius:0}
          #share-hist-preview .ht-filters{margin-bottom:10px;padding-bottom:8px}
          #share-hist-preview .ht-inert *{pointer-events:none}
        </style>
        <div class="ht-inert" aria-hidden="true">${window.negoTimelineScreenHtml
          ? negoTimelineScreenHtml(c, {})
          : `<div style="padding:14px;font-size:13px;color:var(--color-neutral-600)">${i18t('co_history_not_here')}</div>`}</div>
      </div>
      ${''/* THE BOX IS NO LONGER PRE-WRITTEN FOR THE SENDER.

             It used to open holding the generated change list, and whatever it
             held travelled: into the email body and onto the counterparty's
             landing page as "What changed". So every link arrived with a
             machine-written paragraph stapled to it, listing changes that are
             already on the same screen a few inches below — in the Tracked
             Changes panel, per clause, with the redline attached. A covering
             note that repeats the page it covers is noise wearing the shape of
             a message, and nobody reads the second copy.

             Empty, with the question in the placeholder. Say something and it
             travels; say nothing and the recipient gets the contract without a
             paragraph pretending a person wrote it. The manifest above is
             unchanged — the SENDER still sees exactly what is going out. */}
      <label style="display:block"><span id="sh-summary-label" style="display:block;font-size:12px;font-weight:600;color:var(--color-neutral-700);margin-bottom:4px;font-family:var(--font-mono);letter-spacing:.02em;">${
        hist?'A note to send with the record — optional'
           :`A note to ${esc(c.counterparty||'them')} — optional`}</span>
        <textarea id="sh-summary" rows="4" style="${FLD}" placeholder="${
          hist?'e.g. The full record of our negotiation, for your file.'
             :'e.g. We have moved on payment terms but not on the liability cap.'}"></textarea></label>
      ${opts.handOver?`<div id="share-handover" style="margin-top:12px;border:1px solid var(--st-green-line);background:var(--st-green-bg);border-left:3px solid var(--st-green-fg);border-radius:0;padding:9px 12px;font-size:13px;line-height:1.5;color:var(--st-green-fg)">
        <b>${i18t('co_closes_your_turn')}</b> Once it goes out, this contract shows as waiting on ${esc(c.counterparty||'them')} until they reply. Nothing moves if you close this without sending.</div>`:''}
      <div style="margin-top:14px;display:flex;align-items:center;gap:8px;justify-content:flex-end;">
        <button id="share-back-kind" class="ui-btn">${icon('arrow-right','w-3.5 h-3.5')} Back</button>
        <button id="share-close-1" class="ui-btn">${i18t('act_close')}</button>
        <button id="share-next" class="ui-btn ui-btn-primary">Next ${icon('arrow-right','w-3.5 h-3.5')}</button>
      </div>
    </div>`;
}

/* ============================================================
   WHO SIGNS, ASKED WHERE THE SIGNING LINK IS MADE (added 2026-08-11)
   ============================================================
   Asked for directly: "whenever you click share and you are in this step where
   you are sharing a contract for people to sign, there should be a trigger to
   assign who will be signing the contract" — pointing at the Signing order
   card on the Signing tab.

   Everything needed already existed and was in the wrong place. The Signing
   tab has the route; issueSigningRouteLinks mints one bound link per
   counterparty signer, held until their turn; the server binds a share to a
   row of the stored plan (shares.signer_id) and refuses a signature out of
   order. The SHARE DIALOG knew none of it — it took one hand-typed address and
   minted a link bound to nobody, so a signing link could be forwarded and used
   to sign any open counterparty step.

   So the dialog shows the route on a Sign link and the sender picks the person
   this link is for. Picking fills the recipient from that row AND sends the
   signerId, so the link is bound at the source rather than guessed at by the
   server's address match.

   THE INTERNAL ROWS ARE SHOWN AND ARE NOT PICKABLE. They sign in HaTi, not by
   link; drawing them greyed is what makes the order legible — "you are second
   of three" is the fact the sender needs, and hiding the first row would leave
   the numbering saying something false.

   NO ROUTE IS AN ERROR NOW, AND THAT REVERSES WHAT THIS COMMENT USED TO SAY.
   It read: "refusing to send until somebody fills in a route would be a new
   wall in front of the commonest send there is." The owner has weighed that
   and chosen the wall (11 Aug 2026): "I do not want a contract signed without
   the owner knowing the process of signing has started, which will start by
   assigning signers" — and, second, so that a contract handed to somebody to
   READ cannot be signed by them. See signingRouteOpen in js/approvals.js.

   The block therefore stops being a note and becomes a prompt: amber, saying
   what is missing and what it costs, with the door to fix it. It goes quiet
   again the moment a counterparty signer exists, because a warning that is
   always on is furniture. */
function shareSignerRowsHtml(c, sel){
  const plan=(typeof signerPlan==='function'?signerPlan(c):[])
    .slice().sort((a,b)=>(a.order||0)-(b.order||0));
  if(!plan.length) return { plan, html:`<p style="margin:0;font-size:13px;line-height:1.55;color:var(--color-neutral-600)">${
    i18t('co_no_route_yet',{them:esc(c.counterparty||'the counterparty')})}</p>` };
  const html=plan.map((s,i)=>{
    const cp=s.party==='counterparty';
    const pickable=cp && !s.signed;
    const on=pickable && String(sel||'')===String(s.id);
    const mail=String(s.email||'').trim();
    const note=s.signed ? i18t('co_signer_signed')
      : cp ? (mail ? esc(mail) : `<span style="color:var(--st-amber-fg)">${i18t('co_signer_no_email')}</span>`)
      : i18t('co_signer_internal');
    return `<${pickable?'button type="button"':'div'} ${pickable?`data-share-signer="${esc(s.id)}"`:''}
      style="display:flex;align-items:flex-start;gap:8px;width:100%;text-align:left;font:inherit;border:1px solid ${on?'var(--color-accent)':'var(--color-divider)'};
        background:${on?'var(--color-accent-100)':'var(--color-surface)'};border-radius:0;padding:7px 9px;margin-bottom:5px;
        cursor:${pickable?'pointer':'default'};opacity:${pickable||s.signed?'1':'.7'}">
      <span style="flex:none;width:17px;height:17px;border-radius:50%;display:grid;place-items:center;font-size:12px;font-weight:700;
        background:${on?'var(--color-accent)':'var(--color-neutral-100)'};color:${on?'#fff':'var(--color-neutral-700)'}">${i+1}</span>
      <span style="flex:1;min-width:0">
        <span style="display:block;font-size:13px;font-weight:600;color:var(--color-text)">${esc(s.name||'—')}${
          s.role?`<span style="font-weight:400;color:var(--color-neutral-600)"> · ${esc(s.role)}</span>`:''}</span>
        <span style="display:block;font-size:12px;color:var(--color-neutral-600);line-height:1.45">${note}</span>
      </span>
      ${on?`<span style="flex:none;font-size:11px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--color-accent-800)">${i18t('co_signer_this_link')}</span>`:''}
    </${pickable?'button':'div'}>`;
  }).join('');
  return { plan, html };
}
/* Can this contract carry a signing link at all? An executed one cannot be
   signed again by anybody, so the prompt would be about nothing — the copy of
   a signed agreement still goes out on a Sign link and must keep going out. */
const shareNeedsSigners = c => !!c && c.status!=='Signed'
  && !(window.signingRouteOpen ? signingRouteOpen(c) : true);
function shareSignerPickHtml(c, sel){
  const { plan, html }=shareSignerRowsHtml(c, sel);
  const cps=plan.filter(s=>s&&s.party==='counterparty'&&!s.signed);
  /* AMBER, BECAUSE THIS IS NOW A BLOCKER. Reported against a screenshot of the
     block ringed in red: "it should be clear that action may be needed here as
     far as adding signers, because it is currently blending in the white
     background." It was blending in because it was a note; it is a prompt now,
     and it is dressed as one only while it is true. */
  const need=shareNeedsSigners(c);
  const box=need
    ? 'border:1px solid var(--st-amber-line);background:var(--st-amber-bg)'
    : 'border:1px solid var(--color-divider);background:var(--color-bg)';
  return `<div id="share-signers-box" data-need-signers="${need?'1':'0'}" style="margin:0 0 14px;${box};border-radius:0;padding:11px 12px">
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
      ${need?`<span style="flex:none;display:inline-flex;color:var(--st-amber-fg)">${icon('alert','w-3.5 h-3.5')}</span>`:''}
      <span style="flex:1;font-size:11px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:${need?'var(--st-amber-fg)':'var(--color-neutral-600)'}">${i18t('co_who_signs')}</span>
      ${plan.length?`<span style="flex:none;font-size:12px;color:var(--color-neutral-600)">${plan.filter(s=>s.signed).length} of ${plan.length} signed</span>`:''}
    </div>
    <div id="share-signer-rows">${html}</div>
    <button type="button" id="share-signer-edit" class="${need?'ui-btn ui-btn-primary':'ui-btn'}" style="width:100%;justify-content:center;font-size:13px;padding:${need?'8px 12px':'6px 12px'};margin-top:${plan.length?'3px':'8px'}">${
      icon('users','w-3.5 h-3.5')} ${plan.length?i18t('co_add_reorder_signers'):i18t('co_add_signers')}</button>
    <p style="margin:7px 0 0;font-size:12px;line-height:1.5;color:${need?'var(--st-amber-fg)':'var(--color-neutral-500)'}">${
      need?i18t('co_signer_none_blocks')
      :cps.length?i18t('co_signer_bind_note'):i18t('co_signer_free_note')}</p>
  </div>`;
}

/* The warning block at the top of the share modal. Naming what is missing is
   the whole point — "this contract is incomplete" is not actionable, "no value
   is set and the document still says [SUPPLIER CORPORATE NAME]" is. */
/* THE COUNT HAS TO COUNT THE LIST UNDER IT. This printed "1 thing to fix" —
   the number of BLOCKS — and then listed every problem, blocks and warnings
   alike, in one undifferentiated ruby list. On the reported NDA that read as
   "1 thing to fix" above two sentences, the second of which ("This contract is
   still a Draft") is not a thing to fix at all: it is an observation, and every
   contract shared for review is a draft.

   A reader cannot tell which of the sentences is the one holding the send, so
   either the number is wrong or one of the lines is. They are separated now:
   what BLOCKS is counted and listed, what is merely worth knowing sits under
   its own quiet line. */
function readinessPanelHtml(c){
  const probs=contractReadiness(c);
  if(!probs.length) return '';
  const blocks=probs.filter(x=>x.severity==='block');
  const notes=probs.filter(x=>x.severity!=='block');
  const tone=blocks.length
    ? { bg:'var(--st-ruby-bg)', line:'var(--st-ruby-line)', fg:'var(--st-ruby-fg)',
        head:i18tn('co_not_ready',blocks.length,{n:blocks.length}) }
    : { bg:'var(--st-amber-bg)', line:'var(--st-amber-line)', fg:'var(--st-amber-fg)',
        head:i18t('co_worth_checking') };
  const list=(items,color)=>`<ul style="margin:0;padding-left:16px;font-size:13px;line-height:1.65;color:${color};">
      ${items.map(x=>`<li>${esc(x.label)}</li>`).join('')}
    </ul>`;
  return `<div id="share-readiness" style="margin:0 0 12px;border:1px solid ${tone.line};background:${tone.bg};border-radius:0;padding:10px 12px;">
    <div style="display:flex;align-items:center;gap:6px;font-size:13px;font-weight:600;color:${tone.fg};margin-bottom:6px;">${icon('alert','w-3.5 h-3.5')} ${tone.head}</div>
    ${blocks.length?list(blocks,tone.fg):''}
    ${notes.length?`<div style="${blocks.length?'margin-top:9px;padding-top:8px;border-top:1px solid '+tone.line+';':''}">
      ${blocks.length?`<div style="font-size:11px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--color-neutral-600);margin-bottom:4px">${i18t('co_also_worth_knowing')}</div>`:''}
      ${list(notes,blocks.length?'var(--color-neutral-700)':tone.fg)}
    </div>`:''}
    ${blocks.length?`<label style="display:flex;align-items:flex-start;gap:7px;margin-top:9px;font-size:13px;color:${tone.fg};cursor:pointer;">
      <input id="sh-ack" type="checkbox" style="margin-top:2px;accent-color:${tone.fg}"/>
      <span>${i18t('co_send_anyway')}</span></label>`:''}
  </div>`;
}
/* ---------- step 0 of Share: the one-question send (WO N4) ----------
   When everything the form asks for is already known — a recipient on the
   record, a purpose the contract's own state decides, no blocking readiness
   problems, a server to send through — the dialog opens as ONE SENTENCE and
   one button. The full machinery is untouched one click away behind "Change
   details": step 0 presses the SAME send handler the form's button presses,
   with the same prefilled fields, so there is exactly one send path however
   the dialog was answered. First-send is the activation moment; every visible
   decision there adds hesitation exactly where confidence matters most. */
function quickSendPhrase(p){
  return p==='sign' ? 'to sign this exact wording'
    : p==='view' ? 'to read it (view only)'
    : 'to review it and propose changes';
}
function quickSendStepHtml(c, pre, purpose, warns){
  /* Quotes escaped too, not just &<>: this is text content where a stored
     quote is harmless, but a name like `x" onfocus="…` must never appear
     verbatim anywhere in modal HTML — the escape-everything rule is cheaper
     than deciding per call site which contexts are attribute-shaped. */
  const q=s=>esc(s).replace(/"/g,'&quot;');
  const who=pre.name?`${q(pre.name)} · ${q(pre.email)}`:q(pre.email);
  const w=(warns||[]).map(x=>x.label);
  return `
  <div id="share-step-0">
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;"><span style="display:inline-flex;color:var(--color-accent);">${icon('send')}</span>
      <h2 style="font-family:var(--font-heading);font-weight:600;font-size:18px;color:var(--color-text);margin:0;">${i18t('co_send_named',{name:esc(c.name)})}</h2></div>
    <div style="border:1px solid var(--color-divider);background:var(--color-bg);border-radius:0;padding:14px 16px;margin-bottom:10px">
      <p style="margin:0;font-size:15px;line-height:1.6;color:var(--color-text)">To <b style="color:var(--color-accent-800)">${who}</b> — ${quickSendPhrase(purpose)}.</p>
      <p style="margin:6px 0 0;font-size:13px;line-height:1.5;color:var(--color-neutral-600)">${i18t('co_secure_link')}</p>
    </div>
    ${w.length?`<div style="display:flex;gap:7px;align-items:flex-start;margin:0 0 10px;font-size:12px;line-height:1.55;color:var(--st-amber-fg)"><span style="flex:none;display:inline-flex;margin-top:1px">${icon('alert','w-3.5 h-3.5')}</span><span>Worth checking: ${esc(w.slice(0,2).join(' '))}${w.length>2?' …':''}</span></div>`:''}
    <div id="qs-result" style="margin:0 0 4px"></div>
    <div style="margin-top:10px;display:flex;align-items:center;gap:8px;">
      <button id="qs-details" class="ui-btn" style="font-size:13px" title="${i18t('co_full_form')}">${i18t('co_change_details')}</button>
      <span style="flex:1"></span>
      <button id="qs-cancel" class="ui-btn">${i18t('act_cancel')}</button>
      <button id="qs-send" class="ui-btn ui-btn-primary" style="font-size:14px;padding:8px 18px">${icon('send','w-3.5 h-3.5')} ${i18t('co_send_it')}</button>
    </div>
  </div>`;
}

/* The allow-list that decides what a counterparty is shown. Everything the
   portal renders has to be in here; anything not in here does not exist as far
   as the other side is concerned. */
const shareDocText = c => { try{ return (typeof docPlainText==='function') ? docPlainText(c) : ''; }catch(_){ return ''; } };
/* The version history a counterparty is entitled to.

   Both sides now read the SAME list — same numbers, same captions, same
   authors — so "look at v3" means one thing to everyone on the deal. Matching
   captions is the point: a counterparty who sees "The paper you sent" while
   the other side sees "v2 · Edited by Young Mbagaya" cannot be talked through
   a negotiation over the phone.

   What still stays behind is drafting that was never sent to anybody. A
   contract worked on internally for a week before it went out has a history
   that is the organisation's own; the counterparty cannot refer to a version
   they never received, so publishing it would serve nothing and reveal
   working. The list therefore starts at whichever comes first: the received
   paper itself, or the first time the contract was shared. */
/* Captions travel as written, with one exception. A playbook insertion is
   labelled with the internal name of the clause and the fallback tier it came
   from — that is the organisation's negotiating position, not a description of
   the document, and naming it to the other side gives away the floor before
   the bargaining starts. */
function safeVersionLabel(label, org){
  const l=String(label||'Saved');
  return /^inserted preferred wording/i.test(l) ? ('Revised by '+(org||'the sender')) : l;
}
function shareVersions(c, org){
  const vs=(c.versions||[]);
  if(!vs.length) return undefined;
  const firstSent=vs.findIndex(v=>/^shared for review/i.test(v.label||''));
  // an inbound contract's first version IS the counterparty's own paper, so it
  // is theirs to see even though it predates any share
  const inbound=!!(c.source==='upload');
  let from = firstSent<0 ? (inbound?0:-1) : firstSent;
  if(inbound && firstSent>0) from=0;
  if(from<0) return undefined;
  const out=vs.slice(from)
    .filter(v=>v&&typeof v.text==='string'&&v.text.trim())
    .slice(-8)
    .map(v=>({ n:v.n, at:v.at, label:safeVersionLabel(v.label, org), by:v.by||null, text:v.text }));
  return out.length?out:undefined;
}
/* WHAT THE LINK IS FOR, carried by the link itself.

   'negotiate' — the room, every time it is opened, however much is outstanding
   'sign'      — the clean document and the respond panel

   It used to be inferred: count the outstanding changes, and if there were
   none, turn the negotiation link into a signature request. That arithmetic
   decided a thing only a person can decide. Resolve the last change — even by
   refusing it — and the link the counterparty had been negotiating in silently
   became somewhere to sign, with nobody having said the deal was done.

   So the sender says what the link is when they create it, the reader's page
   reads that and nothing else, and a negotiation link stays the room until a
   NEW link supersedes it. */
/* Four purposes now, and they answer two different questions. Sign, negotiate
   and view are things somebody does TO A CONTRACT — they are the second
   question the share dialog asks. 'history' is the answer to the first one:
   what is travelling at all, the contract or the record of the argument. It is
   stored in the same column because a link has one job, and collapsing the two
   questions into one value is what keeps every route that reads a purpose
   — the server's guard, the portal's router — reading a single field.

   'view' and 'history' are both read-only passes, and both are enforced by the
   server rather than by the screen (shareIsReadOnly, server/server.js). */
const SHARE_PURPOSE = p => (['sign','negotiate','view','history'].includes(p) ? p : null);
function buildSharePayload(c, docHash, who, opts){
  const org=(who&&who.org)||FIRST_PARTY;
  /* ---- ONE NAMED CONTACT, AND IT IS THE LEAD ----
     `sharedBy` is who the counterparty is told to reply to: the portal prints
     it on the header, on the response screen, on the signing screen and in the
     nudge email. So it is a CONTACT, not an audit field — and taking it from
     whoever happened to press the button meant a contributor doing something
     administrative surfaced as a change of contact on the other side.

     Where a negotiation has a desk, the contact is its lead. That is stable
     across a lead's tenure, it is the person who can actually answer, and when
     it does change the counterparty is told in a sentence rather than left to
     notice (see deskAnnouncement). Where there is no desk this is exactly what
     it always was.

     THE CONTRIBUTORS ARE STILL INTERNAL. One name travels because a deal has a
     contact; the roster does not, and neither does the fact that a desk exists. */
  const _deskLead=(window.deskIsOpen&&window.deskIsOpen(c)&&window.deskLead)?deskLead(c):null;
  const sharedBy=(who&&who.sharedBy)||(_deskLead&&_deskLead.name)||currentUser().name;
  const leadNotice=(window.deskAnnouncement)?deskAnnouncement(c):null;
  const shareUpload = u => u ? { fileName:u.fileName, size:u.size, mime:u.mime,
    fileHash:u.fileHash, dataUrl:u.dataUrl, extractedText:u.extractedText } : undefined;
  /* The negotiation history, trimmed to what the other side is entitled to
     know: which round, when they raised it, and what was decided. The proposed
     and base texts stay behind — they are bulk, and the current wording below
     already reflects any round that was accepted. The internal name of whoever
     ruled on it stays behind too; the banner speaks for the organisation. */
  /* The comment is now part of it, in BOTH directions. The counterparty's own
     ask travelling back to them is not a leak — they wrote it — and it is what
     makes the portal a conversation rather than a series of unexplained
     verdicts. The reply is the half that was missing entirely: the portal could
     say a round was "not adopted" but never why, so the reasoning lived in a
     parallel email thread, which is the fragmentation HaTi exists to end.
     The internal name of whoever ruled stays behind; the organisation speaks. */
  const shareRounds = (c.rounds||[]).map(r=>({ n:r.n, at:r.at, by:r.by, status:r.status,
    comment:r.comment||null,
    /* Per-clause exchanges: what they asked on a specific change, what was
       decided about it, and the reply given against it. Their own words coming
       back is not a leak, and the decision is theirs to know. The wording
       fragments are already visible in the document they are reading. */
    blockDecisions: Array.isArray(r.blockDecisions)&&r.blockDecisions.length
      ? r.blockDecisions.map(b=>({ id:b.id, decision:b.decision,
          before:b.before, after:b.after, note:b.note||null, reply:b.reply||null }))
      : undefined,
    resolution: r.resolution ? { decision:r.resolution.decision, at:r.resolution.at,
      comment:r.resolution.comment||null } : null }));
  /* The fingerprinted change set, whole. Nothing is trimmed out of it, and that
     is a decision rather than an oversight: the counterparty wrote half of these
     changes, and the other half are rulings ON their asks. A reader who can see
     three of four fingerprints cannot tell a change that was refused from one
     that was never looked at — which is the ambiguity this model exists to
     remove. The fingerprint travels in full so they can quote it back.

     The one thing that stays behind is the internal name of whoever ruled: the
     organisation speaks, exactly as it does for shareRounds above. */
  /* What the owner has not sent is not sendable by a side effect. See the
     holdUnsent note at the quiet-refresh call site. */
  const heldBack = (opts && opts.holdUnsent && window.negoUnsentAsks)
    ? new Set(negoUnsentAsks(c, 'owner').map(x => x.id)) : new Set();
  /* AND WHAT AN INTERNAL REVIEWER HELD BACK, on every route, unconditionally.

     Not behind an opts flag like holdUnsent above: this payload is built by
     three callers and only one of them passes options. reshareToLastRecipient —
     the round-send that every negotiation after the first travels on — passes
     none at all, so a flag-gated filter would have let a change the reviewer
     refused reach the counterparty on the ordinary path while blocking it on
     the rare one. The whole worth of a hold is that it is not conditional.

     reviewHeldIds is itself limited to UNSENT asks (see its own note): wording
     the other side already holds cannot be recalled, and a payload that quietly
     dropped it would read to them as us editing what we had already said. */
  if (window.reviewWithheldIds){
    /* HELD **AND** STILL BEING LOOKED AT. Both stay behind, for the same
       reason: wording sent while a colleague is midway through reading it makes
       their verdict worthless — it arrives about something the counterparty has
       already seen. The screens tell the two apart (ruby for a refusal, amber
       for in flight); the payload does not need to. */
    try{ for (const id of reviewWithheldIds(c)) heldBack.add(id); }catch(_){}
  }
  /* AND WHAT A SOLO SEND CHOSE TO KEEP BACK (16 Aug 2026) — unconditionally,
     for exactly the reason the review's holds are: reshareToLastRecipient,
     the round-send every negotiation after the first travels on, passes no
     options, and a flag-gated filter would push a deliberately held draft
     down the ordinary path. See negoHeldBackIds. */
  if (window.negoHeldBackIds){
    try{ for (const id of negoHeldBackIds(c)) heldBack.add(id); }catch(_){}
  }
  const shareChanges = (window.negoAllChanges ? negoAllChanges(c) : [])
    .filter(x => x.status !== 'superseded' && !heldBack.has(x.id))
    .map(x => ({ id:x.id, clauseId:x.clauseId, clauseLabel:x.clauseLabel||null, type:x.type,
      changeType:x.changeType||null, afterClauseId:x.afterClauseId||null,
      headingText:x.headingText||null, bodyHtml:x.bodyHtml||null,
      /* The STORED ops travel with the change. The counterparty must read the
         redline the owner reviewed, not one their browser re-derived — the two
         could differ the moment either side's diff changes, and then "what was
         reviewed" and "what was decided on" are two different things. */
      ops:Array.isArray(x.ops)?x.ops.map(o=>({ op:o.op, text:o.text })):undefined,
      oldText:x.oldText, newText:x.newText, hash:x.hash, hashV:x.hashV||null,
      prevChangeHash:x.prevChangeHash||null, seq:x.seq||null, status:x.status,
      needsReview:x.needsReview||false, needsReviewWhy:x.needsReviewWhy||null,
      author:x.author, authorSide:x.authorSide, createdAt:x.createdAt, roundN:x.roundN||null,
      /* Which ask this one superseded. It names a change id the other side
         already knows — their own ask, or one we sent them — so their card can
         say "counters #CHG-001" instead of showing an unexplained replacement.
         The superseded change itself never travels (filtered above). */
      counterOf:x.counterOf||null,
      /* THE NOTE IS THE AUTHOR'S ASIDE, AND IT DOES NOT CROSS THE TABLE. It
         used to travel whole, and the counterparty's page printed it under
         "why they asked" — which for a Copilot-drafted change read
         "Copilot — Explain Legal Risk": telling the other side HOW we drafted
         and WHICH clause we felt exposed on. Negotiation-sensitive twice over.
         Their own note comes back to them — they wrote it — and ours stays
         home. */
      /* TWO FIELDS, BECAUSE THEY ARE TWO DIFFERENT THINGS.
         `note` is provenance — "Copilot — Simplify", written by the
         tool that produced the wording. It is an internal aside and stays
         walled to the counterparty's own, exactly as before: telling the other
         side which of our clauses a model drafted is nobody's business but
         ours.
         `why` is the asker's own explanation, typed into the editor under a
         label that promises the other side will read it. It travels whichever
         side wrote it, because a reason the recipient cannot see is a reason
         that does nothing. What still never travels is the internal name of
         whoever RULED on a change — the organisation speaks there. */
      summary:x.summary, note:(x.authorSide==='counterparty'&&x.note)?x.note:null,
      why:x.why||null, reply:x.reply||null,
      resolvedAt:x.resolvedAt||null,
      /* Whether a refused ask has been taken off the table by the side that
         made it. It travels because "Ready to sign" is gated on it: a reader
         whose copy did not carry the withdrawal would see the button refuse
         over a point the other side had already let go, with no way to tell
         why. Who withdrew it travels too — it is their own name coming back
         when the ask was theirs, and the organisation's when it was ours. */
      withdrawn:x.withdrawn?{ by:x.withdrawn.by, side:x.withdrawn.side, at:x.withdrawn.at }:null,
      /* HOW MANY EARLIER DRAFTS THIS COPY IS NOT CARRYING, and not one word of
         them. A revision is wording we wrote and REPLACED before sending; it is
         ours, and the reader gets what was sent. But the fingerprint chain links
         a change to the wording it replaced, so a copy without the revisions
         hits a link pointing at a hash it has never been given — and reported
         the only failure it knew how to report, in red, on a legal document.
         The number is enough for the check to say "not carried here" instead of
         "altered", and it publishes nothing. See verifyChangeChain. */
      revisionsOmitted:(Array.isArray(x.revisions)?x.revisions.length:0) || undefined,
      /* ONLY THE SHARED HALF OF THE THREAD TRAVELS. negoPostComment's own
         documentation promises that an internal note "reaches nobody by simply
         not being posted — there is no filter here to get wrong". That was true
         when it was written and stopped being true when the thread was later
         added to this payload WHOLE: every internal aside a colleague filed on
         a change — the negotiation ceiling, the walk-away point — travelled to
         the counterparty's page, without even a visibility field their page
         could have filtered on. The filter now exists in the one place a
         missing filter cannot leak: what is never sent needs no hiding. The
         visibility field rides along so the reader's page can label the shared
         messages honestly. */
      thread:Array.isArray(x.thread)?x.thread.filter(m=>m&&m.visibility==='shared')
        .map(m=>({ who:m.who, side:m.side, visibility:'shared', at:m.at, text:m.text, atHash:m.atHash||null })):[] }));
  /* An explicit purpose wins. Where the sender did not state one — a link made
     before purposes existed, or by a path that has no opinion — fall back to
     the old reading of the change set, so an existing link keeps opening on
     exactly the screen it opened on yesterday. New links always state it. */
  /* THE ROUNDS THAT ARE OVER, so the other side's screen can say what ours says.
     Their page had no idea a round had ever closed: it could not offer the
     wording a past round started from, it could not show the history, and every
     change ever decided sat in one undifferentiated live list — so a change
     settled two rounds ago read to them as something still on the table.

     WHAT TRAVELS is the round's number, when it closed, the wording it was
     measured against, and WHICH CHANGES BELONGED TO IT — by id. The changes
     themselves are already in shareChanges, whole; sending them a second time
     inside the round would put two copies of one fingerprint on their page and
     invite the two to disagree. The ids are the join.

     WHAT DOES NOT TRAVEL is the internal name of whoever ruled, exactly as for
     shareRounds and shareChanges above: the organisation speaks. */
  const shareNegoRounds = ((c.negotiation&&c.negotiation.rounds)||[]).map(r=>({
    n:r.n, at:r.at||null,
    baselineBody:r.baselineBody||'',
    baselineText:r.baselineText||'',
    changeIds:(r.changes||[]).map(x=>x&&x.id).filter(Boolean) }));
  /* WHAT THE SENDER ACTUALLY CHOSE, kept apart from what this line then
     guesses. `purpose` below falls back to a reading of the change set when
     nobody stated one — which is right for deciding which SCREEN to open, and
     wrong as evidence of intent: a contract with nothing proposed on it yet
     guesses 'sign', and a link built from that guess is not a signing link.
     W6 strips the negotiating verbs from signing links, and it has to be able
     to tell the two apart or it takes Direct Edit away from links nobody ever
     issued for signature. */
  const purposeChosen = SHARE_PURPOSE(opts&&opts.purpose) || null;
  const purpose = purposeChosen || (shareChanges.length?'negotiate':'sign');
  // written out longhand, not as shorthand: this list is read as a list
  return { v:1, kind:'hati-share', org:org, sharedBy:sharedBy, at:nowISO(), docHash:docHash,
    /* One courtesy sentence, on the round after the contact changed and on that
       round only. The entire visible consequence of everything the desk does. */
    leadNotice:leadNotice||undefined,
    purpose:purpose, purposeChosen:purposeChosen,
    /* ---- WHETHER ANYTHING ON THIS LINK CAN BE SIGNED ----
       A single boolean, and deliberately only that: the signing route names
       colleagues and their addresses, and none of that is the counterparty's
       to read. What they are entitled to know is whether the Sign button in
       front of them will do anything, which is a fact about their own screen.

       The server is the wall (see the respond route); this is so their page
       can say it BEFORE they fill in their name and press it, instead of
       collecting their details and then refusing. An older payload carries no
       field at all, and their page treats absent as "do not claim" rather than
       as false — the server still refuses, in words. */
    signingOpen: window.signingRouteOpen ? !!signingRouteOpen(c) : undefined,
    contract:{ id:c.id, name:c.name, template:c.template, source:c.source||null,
      /* THE MARKS ALREADY TAKEN travel with the copy. The owner signing first
         is a fact of the document — a counterparty reading a copy with no
         record of it saw a bare "pending execution" placeholder and could not
         tell a signed-and-waiting contract from an unsigned draft (field
         report, 02 Aug 2026). Name, capacity, form, time and the adopted mark
         image: the same face the executed copy will carry. */
      /* ---- BUT THE ADDRESS AND THE MARK WAIT FOR EXECUTION (owner-ruled 14 Aug 2026) ----
         The field report above is answered by the NAME, the capacity and the
         DATE: those say "signed and waiting on you", which is the whole thing
         the counterparty could not tell before. The email address and the
         rendered signature image say nothing about that and were travelling
         from the first internal signature — on a NEGOTIATION link, to a party
         who has signed nothing. Ten lines above this, signingOpen is reduced to
         a bare boolean with the reasoning that "the signing route names
         colleagues and their addresses, and none of that is the counterparty's
         to read"; this is the same fact arriving by another door.

         AND A HELD SIGNATURE IMAGE IS THE RAW MATERIAL FOR FORGERY. Once the
         contract is executed both sides hold the same executed copy and the
         mark is on the face of it, which is what a signature is for. Before
         that it is ours. */
      signatures:(c.signatures||[]).length?c.signatures.map(s=>{
        const done=!!(c.execution&&c.execution.at)||c.status==='Signed'||!!c.hash;
        return { party:s.party, name:s.name, title:s.title||null, at:s.at||null,
          form:s.form||s.method||null,
          email:done?(s.email||null):null, image:done?(s.image||null):null };
      }):undefined,
      /* The negotiation, as the other side must see it: the same fingerprints,
         the same statuses and the same baseline the owner's tab is reading. Two
         screens built from one payload cannot disagree about what was agreed. */
      changes: shareChanges.length ? shareChanges : undefined,
      /* baselineBody, not just baselineText. The body carries the durable
         clause ids, and a change is anchored on a clause id — so a payload
         that sent only the text projection would make the other side
         re-segment the document and mint FRESH ids, and every fingerprint
         would then point at a clause that does not exist on their screen. */
      negotiation: c.negotiation ? { round:c.negotiation.round||1,
        turn:c.negotiation.turn||'owner', turnAt:c.negotiation.turnAt||null,
        chainHead:c.negotiation.chainHead||null, chainSeq:c.negotiation.chainSeq||0,
        seq:c.negotiation.seq||0, hashV:c.negotiation.hashV||null,
        /* Who has signalled they are ready to sign, and when. Both sides', not
           just theirs: a reader who cannot see that WE have signalled cannot
           tell a deal waiting on them from one waiting on us. */
        ready:c.negotiation.ready||undefined,
        rounds:shareNegoRounds.length?shareNegoRounds:undefined,
        baselineBody:c.negotiation.baselineBody||'',
        baselineText:c.negotiation.baselineText||'' } : undefined,
      upload:isUpload(c)?shareUpload(c.upload):undefined,
      /* THE ONE FACT THAT ENDS THE NEGOTIATION, and it was not on the list.
         Everything on the counterparty's page that should stop when a contract
         is executed — the redline editor, the decision verbs, the readiness
         signal — is gated on `c.status === 'Signed'`, and the payload carried
         no status at all, so renderSharePortal hard-coded 'Under Review' onto
         every copy it built. Their screen therefore showed a live negotiation
         over a contract that had been signed and sealed.

         WHEN, and nothing else. Not who signed, not their capacity, not the
         seal: those are the evidence pack, which is not a counterparty's to
         read. The date is the fact they need, and it is a fact about a deal
         they are a party to. */
      executed:(c.status==='Signed'||c.hash||(c.execution&&c.execution.at))
        ? { at:(c.execution&&c.execution.at)||c.signedAt||null } : undefined,
      /* WHICH OF OUR ENTITIES IS CONTRACTING. Their copy of the DOCUMENT has
         to name the same party ours does — a recital that reads differently on
         the two screens is the one thing a shared document cannot do. This is
         not `org` above: that is the workspace they are dealing with and the
         address they reply to. See contractParty in js/core.js. */
      party:contractParty(c)||undefined,
      counterparty:c.counterparty, value:c.value, valueType:c.valueType, fields:c.fields,
      /* A library-template contract IS its form: the blocks, field definitions
         and current values travel whole so the portal can render typed inputs
         and regenerate the same wording this side sees. The definitions are
         not sensitive — they are the blank form the counterparty is being
         asked to fill — and the branding snapshot makes their copy carry the
         same letterhead. */
      templateForm:c.templateForm?{ templateId:c.templateForm.templateId,
        templateVersionId:c.templateForm.templateVersionId,
        templateName:c.templateForm.templateName, versionNumber:c.templateForm.versionNumber,
        blocks:c.templateForm.blocks, fields:c.templateForm.fields,
        values:{...(c.templateForm.values||{})} }:undefined,
      /* The design travels with the words: a snapshot on the contract wins
         (sealed or deliberately chosen), otherwise the company default is
         stamped into THIS payload — the look the document was shared with,
         fixed on the link even if the default changes tomorrow. */
      branding:c.branding||(window.orgBrandingSnapshot?orgBrandingSnapshot():null)||undefined,
      rounds:shareRounds.length?shareRounds:undefined,
      /* The wording exactly as it left, in plain text. A template-drafted
         contract has no stored body — it is rendered from the template and its
         fields — so the server could never reconstruct what a given link said.
         Recording it here is what lets the next link tell the same reader what
         moved since the copy they last opened. */
      docText:shareDocText(c)||undefined,
      /* ---- THE FINISHED DOCUMENT, FOR A COPY THAT CANNOT BUILD ONE ----
         A read-only link is served the server's trimmed viewerPayload: the
         wording and the marks, and none of the people. That trim is right, and
         it leaves the viewer with `redlineText` as its only source of words —
         which a template-drafted contract does not have, because its wording is
         rendered on demand from the template and the record's fields. The
         reported symptom was a blank sheet on every one of the twelve
         built-ins, and on every uploaded file.

         So the body is rendered HERE, once, on the side that can: docBody
         answers for all three shapes (upload, stored wording, template). Only
         where there is no stored wording, so the common case carries nothing
         extra and the payload does not hold two copies of one document. Guarded
         because a share must not fail over a preview — a missing body is a
         sentence on their page, not a link that never went. */
      viewBody:(!c.redlineText && typeof window!=='undefined' && window.docBody)
        ? (()=>{ try{ return docBody(c)||undefined; }catch(_){ return undefined; } })()
        : undefined,
      /* Changes they asked for that were NOT adopted. A rejected change that
         simply disappears from the document reads as agreement — the reader
         has no way to tell "we said no" from "we missed it". */
      openPoints:(window.openPointsFor?openPointsFor(c):[]).length?openPointsFor(c):undefined,
      versions:shareVersions(c, org),
      redlineText:c.redlineText||undefined, format:c.redlineText?docFormat(c.format):undefined } };
}
/* ---- who we last shared this contract with ----
   Six rounds of a negotiation meant six trips through a blank share form,
   retyping the same counterparty's address each time — five or six chances to
   send a live contract to the wrong person, and enough friction to discourage
   a round that was actually needed.

   The server has always stored the recipient on every share row; nothing ever
   read it back. These two are pure functions of that list so they can be
   tested directly, and so "who is this going to?" has exactly one answer.

   Revoked and expired shares still count as evidence of WHO the counterparty
   is: the link died, the person did not. */
function lastShareRecipient(shares){
  const list=(shares||[]).filter(s=>s && (s.recipientEmail||s.recipientPhone||s.recipientName));
  if(!list.length) return null;
  // the shares endpoint returns newest first; sort defensively rather than trust it
  const sorted=list.slice().sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));
  const s=sorted[0];
  return { name:s.recipientName||'', email:s.recipientEmail||'', phone:s.recipientPhone||'',
    channel:s.channel||'email', token:s.token||null };
}
/* ---- THE SIGNING ROUTE IS THE NEWER ANSWER TO "WHO IS THIS FOR" ----
   Reported (Young, 11 Aug 2026): the counterparty signer was named on the
   signing route with one address, the route was saved, Share was opened — and
   the recipient box arrived carrying a DIFFERENT address, the one an earlier
   round had gone to, under a line reading "filled in from the last time you
   shared this contract". Two records of who the counterparty is, and the older
   one won.

   Naming a signer is the later, deliberate act: somebody sat down and said who
   executes this agreement and where the link must reach them. So it goes first,
   ahead of both the last share and the address recorded on Key terms.

   ONLY a counterparty row — internal signers sign in HaTi and never get a link
   — only one who has not signed yet, only one carrying a real address (a row
   with no email cannot fill a box, and shareSignerRowsHtml already says so in
   amber), and the FIRST such row in turn order, because on a Sign link the
   recipient should be the signer whose turn it is.

   IT ANSWERS THE PREFILL, NOT THE STANDING NEGOTIATION CHANNEL.
   reshareToLastRecipient refreshes the link the counterparty already holds, and
   re-pointing that at a signer would move a whole negotiation to somebody who
   was only ever named to sign. See counterpartyContact, where this is the LAST
   answer rather than the first. */
function shareRouteRecipient(c){
  const plan=(typeof signerPlan==='function') ? signerPlan(c) : ((c&&c.signerPlan)||[]);
  const row=(plan||[]).filter(s=>s && s.party==='counterparty' && !s.signed
      && /.+@.+\..+/.test(String(s.email||'').trim()))
    .slice().sort((a,b)=>(a.order||0)-(b.order||0))[0];
  if(!row) return null;
  return { name:String(row.name||'').trim(), email:String(row.email||'').trim(),
    phone:'', channel:'email', token:null, signerId:row.id };
}
/* A blank recipient box on a contract whose counterparty we already named is
   the third time in one sitting the same fact gets asked for. THREE records can
   answer it and they answer in this order: the signing route, then the last
   link we sent, then the address recorded on Key terms.

   `source` travels with the answer because the dialog SAYS where the box was
   filled from — and it was saying "from the last time you shared" over an
   address that had come from somewhere else entirely. A prefill nobody can
   trace is a prefill nobody checks. */
function shareModalPrefill(shares, c){
  const route=c ? shareRouteRecipient(c) : null;
  if(route) return { name:route.name, email:route.email, phone:'', channel:'email',
    source:'route', signerId:route.signerId };
  /* counterpartyContact already holds the second and third answers in the right
     order, including the case a share carries a name but no address. */
  const pick=c ? counterpartyContact(c, shares) : lastShareRecipient(shares);
  if(!pick) return { name:'', email:'', phone:'', channel:'email', source:'', signerId:null };
  return { name:pick.name||'', email:pick.email||'', phone:pick.phone||'',
    channel:pick.channel||'email',
    source:lastShareRecipient(shares)?'last':'record', signerId:null };
}
/* The one sentence the dialog says over a filled-in recipient box, named by
   where the address actually came from. Empty where nothing was filled in. */
function sharePrefillNote(pre){
  const p=pre||{};
  if(!(p.email||p.phone||p.name)) return '';
  return p.source==='route' ? i18t('co_filled_from_route')
    : p.source==='record' ? i18t('co_filled_from_record')
    : p.source==='last' ? i18t('co_filled_from_last') : '';
}
/* The shares this contract has already had, for prefill and for the reshare
   button. Never fatal: a contract that cannot reach the server still shares. */
async function contractShares(c){
  if(!API_MODE()) return [];
  try{ const r=await api('contracts/'+c.id+'/shares'); return r.shares||[]; }
  catch(e){ return []; }
}
/* ---- "Send updated version" ----
   The one-click path a resolved round leads to: same recipient, same channel,
   a fresh link carrying the wording as it now reads. Returns the created share
   so the caller can report the outcome; throws only if there is nobody to send
   to, which the button's own visibility already rules out. */
/* WHERE THIS COUNTERPARTY CAN BE REACHED.

   Two places know it and they answer in this order: a link we have already sent
   them (the address it went to), then the address recorded on the contract
   itself when the negotiation was set up. The second is why a FIRST send no
   longer needs the dialog — before it existed, the only record of who to write
   to was a share that had not been created yet, so the first send always had to
   stop and ask. */
function counterpartyContact(c, shares){
  /* A prior share wins outright, however it was sent. lastShareRecipient
     already requires one of name/email/phone, and a copy-link share carries
     only a name — narrowing this to "has an email" broke re-sending on exactly
     those, which is a channel the product supports. The contract's own address
     is a FALLBACK for the case that had none: the first send. */
  /* ---- THE IDENTITY AND THE ADDRESS ARE TWO DIFFERENT ANSWERS ----
     This returned the newest share WHOLE, and a copy-link or WhatsApp share
     carries no email at all. So one link copied to the clipboard shadowed a
     perfectly good address — the one recorded on the contract, or the one an
     earlier email share went to — for the rest of the negotiation. Every send
     after it found `email: ''`, concluded it had nowhere to send, and reopened
     the dialog to ask a question the record could already answer: the pop-up
     that appeared on every round, once per change, reported from the field.

     So the newest share still decides WHO this is — name, channel, token —
     and the address is asked separately, best answer first: the most recent
     share that actually carries one, then the address recorded on the
     contract. A share without an email is not evidence that there is no
     email. */
  const last=lastShareRecipient(shares);
  const recorded=String((c&&c.counterpartyEmail)||'').trim();
  const fromShares=(shares||[]).slice()
    .sort((a,b)=>String((b&&b.createdAt)||'').localeCompare(String((a&&a.createdAt)||'')))
    .map(s=>String((s&&s.recipientEmail)||'').trim())
    .find(Boolean)||'';
  if(last) return { ...last, email: last.email || fromShares || recorded };
  if(!recorded) return null;
  /* AND THE SIGNING ROUTE IS DELIBERATELY NOT READ HERE, though it may hold the
     only address anybody has given us. This function answers "where does a
     ROUND go" — it drives the one-press send in the negotiation room and the
     reshare that refreshes the standing link — and a round is not a signature.
     Reading a signer here would mean naming a CFO on the signing route quietly
     re-pointed the whole negotiation at them, with no dialog and no sight of
     the address. Where there is nothing else, the send falls through to the
     share dialog, which prefills FROM the route and shows it before it goes.
     See shareRouteRecipient. */
  return { name:(c&&c.counterpartyName)||(c&&c.counterparty)||'', email:recorded, phone:'', channel:'email', token:null };
}
/* ---------- WHICH LINK THE COUNTERPARTY IS ACTUALLY READING ----------
   Reported (Young, 12 Aug 2026), on MK-255: the owner refused a change of the
   counterparty's, their page never showed it, Publish Round was pressed, and
   the counterparty reloaded their link to find nothing had moved.

   THE CAUSE WAS THREE ANSWERS TO ONE QUESTION. Three places decided which
   existing link a new copy belongs on, and they did not agree:

     · the ROUND SEND (reshareToLastRecipient) wanted a durable link whose
       recipient email matched the contact's, exactly;
     · the QUIET CATCH-UP (refreshLiveShareQuietly) took every durable link
       and matched no address at all;
     · the SHARE DIALOG wanted a durable link matching the address just typed.

   The round send was the strictest, and its address is not necessarily the
   address any link was made with: counterpartyContact fills a missing one from
   the newest share that has any, or from the contract record. A link created by
   copying a URL carries no email at all. So the match failed, and the round
   send did the one thing it must never do quietly — it MINTED A SECOND LINK,
   reported "sent", and left the reader holding a copy nothing will ever update.

   ONE PREDICATE, and everything asks it: can this link still be refreshed in
   place? It is the client's reading of what PUT /api/shares/:token/payload will
   accept — durable, not revoked, not expired — so a caller cannot form a plan
   the server is going to refuse. */
/* ONE SENTENCE, FOUR SURFACES. Every place that reports a round-send has to be
   able to say that a second link was minted — the negotiation section's resend,
   the seen-state resend, and the one-press send on both the contract tab and
   the workbench. Four copies of this wording would drift, and the one that
   drifted would be the one somebody read. */
const reshareStrandedLine = who =>
  `A NEW link was created for ${who}. The link they already have will NOT update — send them the new one.`;
function shareIsStanding(s){
  if(!s || !s.durable || s.revokedAt) return false;
  if(s.state==='revoked' || s.state==='expired') return false;
  /* The list route sends expiresAt, never an `expired` flag — a filter written
     against `s.expired` reads undefined and passes everything. Compared as
     dates, which is what the server does. */
  if(s.expiresAt && String(s.expiresAt) < nowISO()) return false;
  return true;
}
function standingShares(shares){
  return (shares||[]).filter(shareIsStanding)
    .sort((a,b)=>String((b&&b.createdAt)||'').localeCompare(String((a&&a.createdAt)||'')));
}
/* THE ONE A ROUND GOES ON. Only for the round send, where the question is
   "where is this negotiation happening" — NOT for the share dialog, where the
   sender has just typed a name and an address and may well mean somebody else.
   Reusing a stranger's link because it happened to be the only one open is a
   worse bug than the one this fixes.

   In order: the link the CONTACT ITSELF CAME FROM (lastShareRecipient carries
   its token, and that is the link the negotiation has actually been travelling
   on — the only one of these that cannot be wrong), then the address, then the
   name, and finally the newest standing link there is. That last step is the
   one that closes the reported hole: the quiet catch-up already refreshes every
   durable link on the contract, so a round send that refuses to touch one the
   catch-up would have updated is stricter than the product's own behaviour a
   second earlier. */
function standingShareFor(shares, contact){
  const live=standingShares(shares);
  if(!live.length) return null;
  const tok=contact&&contact.token;
  const byToken=tok?live.find(s=>s.token===tok):null;
  if(byToken) return byToken;
  const email=String((contact&&contact.email)||'').trim().toLowerCase();
  const byEmail=email?live.find(s=>String(s.recipientEmail||'').trim().toLowerCase()===email):null;
  if(byEmail) return byEmail;
  const name=String((contact&&contact.name)||'').trim();
  const byName=name?live.find(s=>String(s.recipientName||'').trim()===name):null;
  if(byName) return byName;
  return live[0];
}
/* ---------- WHERE THIS CONTRACT'S CHANGES GO ----------
   The share dialog is not a confirmation step. It is the form that collects the
   address the app does not have yet — #nego-send takes a one-press route the
   moment a contact exists (js/views/negotiation.js), and the dialog is the
   fallback for when there is nowhere to send.

   Nothing wrote that contact. So the address was asked for, used once, and
   forgotten, and the next Send re-opened the whole dialog to re-ask a question
   answered on the first round — a pop-up between the reader and a button they
   had already used, once per change, for the life of the negotiation.

   FIRST ONE WINS. A later share to a different person is a one-off (a copy to
   counsel, a second signatory); quietly re-pointing the negotiation at them
   would send the next round somewhere nobody chose. The recorded address is
   changed deliberately, through the setup strip that writes it.

   A SIGNING LINK IS NOT A NEGOTIATING CONTACT. It goes to whoever signs, who
   need not be the person the contract is being argued with. */
function shareRememberRecipient(c, info){
  const o = info || {};
  if (!c || o.purpose === 'sign') return false;
  const email = String(o.email || '').trim();
  if (!email || String(c.counterpartyEmail || '').trim()) return false;
  c.counterpartyEmail = email;
  const name = String(o.name || '').trim();
  if (name && !String(c.counterpartyName || '').trim()) c.counterpartyName = name;
  return true;
}
/* ---- ONE DOOR-CHECK FOR THE INTERNAL REVIEW GATE ----

   Written once and called from every send, for the reason the view-only guard
   on the server is written once: the route this has to survive is the FOURTH
   one, added later by someone who never read this comment. Today the doors are
   the share dialog, the round-send onto a standing link, and the workbench's
   own button — and all three land here.

   IT DOES NOT BRANCH ON PURPOSE. A negotiation link carries our unsent asks; so
   does a signing link, so does a read-only adviser link, and so does the
   history. Every one of them puts wording in front of somebody outside this
   company, which is the thing the gate exists to hold. Where nothing of ours is
   unsent the gate is satisfied by definition, so a link on a settled contract
   is untouched whatever it is for.

   Returns TRUE when the send must not proceed, having already said why. */
/* THE TWO REFUSALS A SEND CAN MEET, and they are different questions.

   The GATE is about the CONTRACT: is there wording here that nobody has looked
   at yet. It is a setting and is off unless an admin turns it on.

   THE POSTURE is about the PERSON: you were asked to review a clause and have
   not handed it back, so on this contract you are a reviewer and nothing you do
   reaches the counterparty. That is not a setting — it follows from having
   accepted the job, and it lifts the moment you hand back.

   Both are asked here so that every door gets both, and neither door has to
   remember which one it was supposed to ask. */
function reviewActorSendBlock(c){
  if(!window.reviewActorBlockMessage) return false;
  let msg=null;
  try{ msg=reviewActorBlockMessage(c); }catch(_){ return false; }
  if(!msg) return false;
  toast(msg,'err');
  return true;
}
/* THE DESK'S OWN REFUSAL, asked by the same doors and first. Reaching the
   counterparty is the lead's act; a contributor who is not the lead is refused
   here whatever their review posture is, and the sentence they get says so
   rather than talking about a review they do not have. Where the desk rule is
   off this answers false and nothing changes — see deskMaySend. */
function deskSendBlockToast(c){
  if(!window.deskSendBlock) return false;
  let msg=null;
  try{ msg=deskSendBlock(c); }catch(_){ return false; }
  if(!msg) return false;
  toast(msg,'err');
  return true;
}
function reviewSendBlock(c){
  if(deskSendBlockToast(c)) return true;
  if(reviewActorSendBlock(c)) return true;
  if(!window.reviewGateMessage) return false;
  let msg=null;
  try{ msg=reviewGateMessage(c); }catch(_){ return false; }
  if(!msg) return false;
  toast(msg,'err');
  return true;
}
async function reshareToLastRecipient(c, opts={}){
  if(!canEdit()) throw new Error('Viewers cannot share contracts');
  /* THE ROUND-SEND IS A SEND. This is the route every negotiation after the
     first travels on — it refreshes the copy behind the counterparty's standing
     link — and it never opens the share dialog, so the check there would never
     have run. Thrown rather than toasted: the callers await this and report
     what comes back, and a silent false would have them announce a send that
     did not happen. */
  /* The reviewer's posture first, then the gate — same order, same sentences as
     reviewSendBlock. Thrown rather than toasted for the reason below. */
  /* The desk first, then the reviewer's posture, then the gate — the same order
     and the same sentences reviewSendBlock uses. This route never opens the
     share dialog, so a check that lived only there would never run on the path
     every round after the first actually travels. */
  if(window.deskSendBlock){
    let msg=null; try{ msg=deskSendBlock(c); }catch(_){ msg=null; }
    if(msg) throw new Error(msg);
  }
  if(window.reviewActorBlockMessage){
    let msg=null; try{ msg=reviewActorBlockMessage(c); }catch(_){ msg=null; }
    if(msg) throw new Error(msg);
  }
  if(window.reviewGateMessage){
    let msg=null; try{ msg=reviewGateMessage(c); }catch(_){ msg=null; }
    if(msg) throw new Error(msg);
  }
  const shares=opts.shares||await contractShares(c);
  const last=counterpartyContact(c, shares);
  if(!last) throw new Error('This contract has not been shared with anyone yet');
  try{ await ensureFull(c); }catch(_){}
  const docHash=await sha256(canonicalDoc(c));
  if(c.status!=='Signed'){ const v=captureVersion(c,'Sent to you',null,{auto:true}); if(v) persist(c); }
  const payload=buildSharePayload(c, docHash, null, { purpose:opts.purpose });
  /* If this counterparty already has a standing link, refresh THAT rather than
     mint another one: the point of a standing link is that the other side keeps
     one URL for the whole negotiation. A new link is created only when there is
     none to refresh — and when that happens it is now SAID (see record below),
     because a second live link is the state this whole path exists to avoid.
     See standingShareFor for the order and for what went wrong before it. */
  const live=standingShareFor(shares, last);
  /* WHAT "SENT" MEANS. Refreshing a link is not the same as telling anybody
     about it, and the two were conflated: the owner saw "updated version sent",
     the history recorded it, and on a copy-link or WhatsApp share — or a server
     with no mail provider — nothing had actually gone anywhere. The outcome is
     now reported per channel, and the audit line only says "sent" when
     something left. */
  const who=last.name||last.email||last.phone||'the counterparty';
  /* LINKS THEY MAY BE HOLDING THAT WE CANNOT REFRESH — not revoked, so still
     openable, but not standing, so PUT payload would refuse them. If we end up
     minting, these are the copies that go quietly dead, and the reader is far
     more likely to be sitting on one of them than to know a new link exists. */
  const orphans=(shares||[]).filter(s=>s && !s.revokedAt && !shareIsStanding(s)).length;
  const record=(r,reused)=>{
    const ch=last.channel||'email';
    const delivered=ch==='email' && !!r.emailSent;
    /* A SECOND LIVE LINK IS SAID OUT LOUD. Minting one is sometimes the only
       thing left — a link made before standing links existed cannot be
       refreshed in place, and the server refuses to try — but the owner used
       to be told "Updated version emailed" and nothing else, while the URL the
       counterparty actually had went stale forever. That is the fault this
       whole section was rewritten for; the honest sentence is the half of the
       fix that survives a case the matching cannot rescue. */
    const stranded=!reused && orphans
      ? ` — this is a NEW link: the copy they already hold cannot be refreshed and will not update, so they must use the new one`
      : '';
    /* A round published to the standing link ON PURPOSE is not a failed email.
       The link was delivered once, when the negotiation began; every round
       after that travels through the platform, and the audit line says so
       instead of reading like a mail outage. */
    const quiet=!!r.notifySkipped;
    const detail = quiet
      ? `Round sent to ${who}'s standing link — the platform is the channel; the link was emailed once, when the negotiation began`
      : delivered
      ? `Updated version emailed to ${who}${reused?' on their existing link':''}`
      : ch==='email'
        ? `Updated version published to ${who}'s link${reused?' (existing link)':''} — NOT emailed${r.emailConfigured===false?': this workspace has no mail provider configured':r.emailError?': '+r.emailError:''}`
        : `Updated version published to ${who}'s link${reused?' (existing link)':''} — send it to them by ${ch==='whatsapp'?'WhatsApp':'link'}; nothing was sent automatically`;
    logAudit(c,'Shared',detail+stranded);
    persist(c);
    return { share:r, recipient:last, reused:!!reused, delivered, quiet, channel:ch,
             /* The caller says this on screen too — an audit line nobody opens
                is not a warning. */
             stranded:!!stranded,
             link:r.link||null, emailConfigured:r.emailConfigured!==false, emailError:r.emailError||null };
  };
  if(live){
    /* ONE EMAIL PER NEGOTIATION, and this is the line that keeps the promise:
       a round-send onto an existing standing link refreshes the copy behind
       the URL the counterparty already holds and posts nothing. The first
       send — the POST below, when no link exists yet — is the one that emails,
       because it is the one delivering a link. */
    const r=await api('shares/'+live.token+'/payload','PUT',{ payload, notify:false });
    /* AND EVERY OTHER STANDING LINK ON THIS CONTRACT, quietly. The quiet
       catch-up already refreshes all of them on a decision, so leaving one
       behind on the round send would mean a reader whose URL is not the one
       we picked sees the round arrive late — or not at all. Same payload, no
       email, no second audit line: these are copies being kept honest, not
       sends. Failures are swallowed for the reason refreshLiveShareQuietly
       gives: a link that could not be caught up must not fail the round. */
    for(const s of standingShares(shares)){
      if(!s || s.token===live.token) continue;
      try{ await api('shares/'+s.token+'/payload','PUT',{ payload, silent:true }); }catch(e){}
    }
    return record(r||{}, true);
  }
  const r=await api('shares','POST',{ payload, channel:last.channel||'email',
    message:opts.message||'', recipient:{ name:last.name, email:last.email, phone:last.phone },
    expiryDays:opts.expiryDays||14, durable:opts.durable!==false, purpose:payload.purpose });
  return record(r||{}, false);
}

/* ---- W7: THE SIGNING LINKS COME FROM THE ROUTE, NOT FROM A TYPED BOX ----

   The owner already named every counterparty signer, in order, with an email
   address, when they set the signing route. Opening the share dialog at that
   point and asking them to hand-type ONE recipient threw that record away —
   and left every signer after the first with no link at all.

   This issues one bound link per unsigned counterparty signer, in one pass.
   The server holds each link until its turn (signer n+1's email goes out when
   signer n signs — see releaseNextSignerLink in server/server.js), so calling
   this early simply creates the route dormant, and calling it again is safe:
   one signer, one link, reused in place, and the reuse is the release when
   the turn has arrived in the meantime.

   Returns null where the route cannot drive this (static mode, no counterparty
   signers), and { missingEmails } where it should but the plan is incomplete —
   the caller decides whether to fall back to the hand-typed dialog, because
   only the caller knows whether an owner is watching. */
async function issueSigningRouteLinks(c){
  if(!API_MODE() || !window.signerPlan) return null;
  const cps=signerPlan(c).filter(s=>s && s.party==='counterparty' && !s.signed)
    .slice().sort((a,b)=>(a.order||0)-(b.order||0));
  if(!cps.length) return null;
  const missingEmails=cps.filter(s=>!/.+@.+\..+/.test(String(s.email||'')));
  if(missingEmails.length) return { missingEmails };
  /* The server binds and sequences against the STORED plan, and `persist` is a
     400 ms timer — the same overtaking that once had /distribute refuse a
     contract its own screen had just sealed. The plan must be on disk before
     the first share request reads it back. */
  try{ await flushSaves(); }catch(_){}
  try{ await ensureFull(c); }catch(_){}
  const docHash=await sha256(canonicalDoc(c));
  if(c.status!=='Signed'){ const v=captureVersion(c,'Sent for signature',null,{auto:true}); if(v) persist(c); }
  const links=[];
  for(const s of cps){
    const payload=buildSharePayload(c, docHash, null, { purpose:'sign' });
    const r=await api('shares','POST',{ payload, channel:'email',
      recipient:{ name:s.name, email:s.email }, expiryDays:30, durable:false,
      purpose:'sign', signerId:s.id });
    links.push({ signer:s, ...r });
  }
  /* One audit line for the act, naming what actually went and what is held —
     "3 links created" hides exactly the fact the route exists to record. */
  const made=links.filter(x=>!x.reused).length;
  const sent=links.find(x=>x.emailSent);
  if(made || sent){
    const bit=x=>`${x.signer.name} (${x.emailSent?'emailed their link':x.heldForTurn?'link held until their turn':'link ready'})`;
    logAudit(c,'Shared',`Signing links issued from the route — ${links.map(bit).join(', ')}. Each link is bound to its signer and released in order.`);
    persist(c);
  }
  return { links };
}

/* opts.onSent — a callback fired when a share is really created, carrying what
   actually happened: which channel, whether the email left the building, and
   the link. The negotiation room uses it to hand the turn over ONLY on a
   successful send. Marking a contract "waiting on them" when the dialog was
   closed, or when nothing went out, is the same class of untruth as a
   "Verified" badge that verified nothing.

   opts.handOver — when set, the dialog says on step 1 that sending closes the
   sender's turn, because that is a consequence they should see before they
   press the button rather than discover afterwards. */
/* Which open is current. A counter rather than a boolean: two presses in quick
   succession both run to completion, and what matters is that only the LAST one
   is allowed to paint. See the note in openShareModal. */
let _shareOpenSeq = 0;
/* THE FIRST PAINT IS THE REAL FIRST QUESTION.
   It began as a skeleton — the heading over two grey boxes — which fixed the
   dead press but bought a flicker instead, and the flicker is measurable: the
   panel came up at 266px holding placeholders and jumped to 309px holding the
   real cards ~30ms later on localhost, longer against a real server. A dialog
   that arrives, resizes and changes its contents is three events where the
   reader asked for one.

   NOTHING IN THIS STEP NEEDS THE SERVER. "What are you sharing?" is answered
   from the contract in hand: shareKindStepHtml takes only the record and the
   current purpose, both of which exist the instant the button is pressed. The
   awaits below are for the PAYLOAD and the recipient's details, which belong
   to the screens after this one. So the same markup the settled dialog uses is
   painted first, and the fill that follows replaces identical pixels — same
   wrapper, same step, same height; the later steps are `hidden` and cost
   nothing.

   THE ONE THING THAT CAN LEGITIMATELY CHANGE is whether the history option is
   offered: negoAllChanges reads the round history, and ensureFull is what
   fetches it for a record opened from a list. On such a record the second card
   corrects itself from "nothing proposed yet" to offered. That is a correction
   the reader should see, and it is one card's state rather than the whole
   dialog changing shape. */
function shareOpeningHtml(c, purposeSel){
  return `<div style="padding:22px 24px;">${shareKindStepHtml(c, purposeSel)}</div>`;
}
/* AND IT IS LIVE FROM THAT FIRST FRAME. The real wiring cannot be attached
   until the full markup is in, so without this the cards and Next would be
   drawn, look pressable and do nothing for as long as the fetches take —
   which is the fault the skeleton was introduced to fix, moved rather than
   removed. Presses are held and replayed once the dialog settles.

   ABORTED BEFORE THE FILL, never left behind: the listener sits on #modal-root
   and the fill only replaces the panel's contents, so a surviving copy would
   handle every later press a second time alongside the real handlers. */
function shareWireOpening(pending, c, get, set, signal){
  const root = document.getElementById('modal-root');
  if (!root || !root.addEventListener) return;
  root.addEventListener('click', e => {
    const t = e.target;
    if (!t || !t.closest) return;
    const card = t.closest('[data-share-kind]');
    if (card && !card.disabled){
      pending.kind = card.getAttribute('data-share-kind');
      set(pending.kind);
      const wrap = root.querySelector('#share-kind');
      if (wrap) wrap.outerHTML = shareKindOptionsHtml(c, get());
      return;
    }
    if (t.closest('#share-kind-next')){ pending.next = true; return; }
    if (t.closest('#share-close-kind')) closeModal();
  }, signal ? { signal } : false);
}
/* Into the frame that is already up, rather than a second dialog. openModal
   replaces #modal-root wholesale, which re-runs .modal-in's 200ms entry
   animation — a dialog that arrives, and then arrives again, is a worse answer
   to "it comes with a delay" than the delay was. Falls back to opening one if
   the frame is not there, so this is safe for any caller. */
function shareFillModal(html){
  const panel=document.querySelector('#modal-root .modal-in');
  if(panel){ panel.innerHTML=html; return; }
  openModal(html);
}
async function openShareModal(c, opts={}){
  // An uploaded document carries its file; that only fits through the server,
  // so static mode points the user at the original instead of a giant URL.
  if(isUpload(c) && !API_MODE()){
    toast(i18t('co_upload_share_server'),'err');
    return;
  }
  /* ---- THE DIALOG OPENS ON THE PRESS, NOT WHEN THE WORK IS DONE ----
     Reported (Young, 10 Aug 2026): "it comes with a delay". Everything below
     this line used to run first — ensureFull fetches the whole record,
     canonicalDoc is hashed, a version is captured and persisted, and
     contractShares asks the server who this went to last time. Four round
     trips, and only then was any pixel drawn. On a real server that is a press
     that appears to do nothing, which is the shape of a broken button.

     THE FRAME COMES UP IMMEDIATELY and fills in. Nothing here is a decision the
     reader can make early — the first question genuinely does depend on the
     record — so what is shown is the dialog itself with its own title and a
     quiet line, and the content replaces it when it is ready. The perceived
     delay goes because the press is answered; the work takes exactly as long
     as it did.

     TWO GUARDS, because an await is a window in which anything can happen:
     _shareOpenSeq catches a second press landing while the first is preparing
     (the later one wins, and the earlier one must not paint over it), and the
     missing scrim catches the reader closing the frame or pressing Escape
     while it prepares — reopening a dialog somebody has just dismissed is
     worse than the delay this fixes. */
  const _openSeq = ++_shareOpenSeq;
  const _superseded = () => _openSeq !== _shareOpenSeq || !document.getElementById('modal-scrim');
  /* The purpose is settled before the first paint because the first screen
     draws it — see the note on shareOpeningHtml. It stays a live value: the
     placeholder's own handler moves it, and the payload below is built from
     wherever it has got to by then. */
  let purposeSel = SHARE_PURPOSE(opts.purpose) || defaultSharePurpose(c);
  const _pending = { kind: null, next: false };
  const _openAbort = (typeof AbortController === 'function') ? new AbortController() : null;
  openModal(shareOpeningHtml(c, purposeSel));
  shareWireOpening(_pending, c, () => purposeSel,
    k => { purposeSel = k === 'history' ? 'history'
      : (SHARE_PURPOSE(opts.purpose) || defaultSharePurpose(c)); },
    _openAbort ? _openAbort.signal : null);
  // A share copies the contract out of the building, so it must be copied
  // whole: a record loaded for a list view carries neither its uploaded file's
  // bytes nor its round history, and both are things the payload publishes.
  try{ await ensureFull(c); }catch(_){}
  if(_superseded()) return;
  const docHash=await sha256(canonicalDoc(c));
  // E2: snapshot the exact text being sent so a returned redline diffs cleanly.
  if(c.status!=='Signed'){ const v=captureVersion(c,'Shared for review',null,{auto:true}); if(v) persist(c); }
  /* THE SHARE PAYLOAD IS A COPY OF THE CONTRACT THAT LEAVES THE BUILDING.
     In server mode it sits in the shares table and is served to anyone holding
     the link; in static mode the whole thing travels inside the URL. Either
     way it is read by a party outside the organisation, so it carries ONLY
     what js/views/portal.js renders or needs to send a response back. Anything
     added here is published — audit it against the portal before adding it.

       id, name, counterparty  — the header and the response envelope
       template, fields        — so a built-in template can be re-rendered
       redlineText, format     — the working text, and the marker without which
                                 a rich document renders as literal markup
       source, upload          — an uploaded document's own file
       value, valueType        — the counter-proposal field ("propose a
                                 different value") and the certificate row
       org, sharedBy, at       — who sent it and when, shown in the header
       docHash                 — echoed in the response so the owner can tell
                                 the document changed after the link was made

     `folder` was in here and is not: which internal value stream a contract is
     filed under is the organisation's own filing structure, and the portal has
     never rendered it — it derives one from the template, falling back to
     'corp'. The upload is trimmed to the file itself; the near-duplicate
     signals (textFingerprint, simhash) and OCR bookkeeping are
     portfolio-analysis data with no meaning to a counterparty.

     Built by buildSharePayload() below rather than inline: the allow-list is the
     thing that decides what a counterparty can be shown, so it needs to be
     reachable by a test. It was inline when the returned-changes banner shipped,
     which is exactly how that banner came to be verified against a payload the
     application never actually produces. */
  /* The purpose the dialog opens on: what the caller asked for if it had an
     opinion, otherwise what the contract's own state says. It is a live value —
     the picker on step 1 changes it, and everything downstream reads it from
     here rather than from the payload built a moment ago. */
  /* purposeSel was settled before the first paint and may have MOVED since —
     the reader can answer the first question while the fetches are in flight.
     The payload is built from where it has got to, not from the default. */
  const payloadObj=buildSharePayload(c, docHash, null, { purpose:purposeSel });
  const server=API_MODE();
  // Who this went to last time. Fetched before the dialog is built so the
  // fields open already filled rather than filling themselves a moment later
  // under the user's cursor.
  const priorShares=await contractShares(c);
  if(_superseded()) return;
  const pre=shareModalPrefill(priorShares, c);
  /* THE BOX AND THE ROW ARE ONE ANSWER. Where the prefill came off the signing
     route, the row it came from opens already chosen, so the link is bound to
     that signer from the first frame rather than only when somebody thinks to
     press it. Pressing it again still takes the binding off. */
  const preNote=sharePrefillNote(pre);
  /* WO N4 — the one-question send. Offered only when nothing needs asking:
     the email channel works end to end (server mode), somebody to send to is
     already on the record, and nothing on the readiness list BLOCKS — a block
     needs the full panel and its explicit acknowledgement, never a shortcut
     past it. Non-blocking warnings ride along as one quiet line. */
  const qsWarns=contractReadiness(c).filter(x=>x.severity!=='block');
  /* WO N4's one-question quick send is RETIRED (Young, 02 Aug 2026): it let a
     contract go out without the sender ever consciously choosing negotiate vs
     sign — the one decision that changes what the recipient can DO with the
     link. The dialog now always opens on "What is this link for?". The
     machinery stays (quickSendStepHtml et al.) in case a safer shortcut is
     wanted later. */
  const quickOk = false;
  let qsActive=quickOk;
  const FLD='width:100%;min-height:34px;border:1px solid var(--color-divider);background:var(--color-surface);border-radius:0;padding:6px 10px;font-size:14px;font-family:var(--font-body);color:var(--color-text);outline:none;';
  const LBL='display:block;font-size:12px;font-weight:600;color:var(--color-neutral-700);margin-bottom:4px;font-family:var(--font-mono);letter-spacing:.02em;';
  const tab=(k,label,active)=>`<button data-share-ch="${k}" style="flex:1;padding:7px 4px;font:inherit;font-size:13px;font-weight:600;cursor:pointer;border:1px solid ${active?'var(--color-accent)':'var(--color-divider)'};background:${active?'var(--color-accent)':'var(--color-surface)'};color:${active?'#fff':'var(--color-neutral-700)'};border-radius:0">${label}</button>`;
  let ch=pre.channel||'email';
  const attr=s=>String(s==null?'':s).replace(/"/g,'&quot;');
  /* The opening handler stands down the instant the real one is about to go
     in — both live long enough to overlap otherwise. */
  if (_openAbort) _openAbort.abort();
  shareFillModal(`
    <div style="padding:22px 24px;">
      ${quickOk?quickSendStepHtml(c, pre, purposeSel, qsWarns):''}
      ${shareKindStepHtml(c, purposeSel)}
      ${shareSummaryStepHtml(c, { ...opts, purposeSel,
        signerSel:(pre.source==='route'?pre.signerId:null), hiddenStart:true })}
      <div id="share-step-2" class="hidden">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;"><span style="display:inline-flex;color:var(--color-accent);">${icon('share')}</span>
        <h2 style="font-family:var(--font-heading);font-weight:600;font-size:18px;color:var(--color-text);margin:0;">${i18t('co_share_with_cp')}</h2></div>
      ${''/* Two blurbs, one shown. A history link promises none of this — there
             is nothing on it to sign, request or decline — and a screen that
             says otherwise is a screen that has to be argued with later. */}
      <p id="share-send-blurb" style="font-size:13px;color:var(--color-neutral-700);margin:0 0 12px;line-height:1.55;">Send ${esc(c.counterparty||'the counterparty')} a secure review link — they can review, sign, request changes or decline, <strong>${i18t('co_no_account_needed')}</strong>. ${server?'Each recipient gets their own tracked link; the outcome arrives on this contract automatically and lands in your email.':'Their response comes back as a code you import below the document.'}</p>
      <p id="share-send-blurb-hist" class="hidden" style="font-size:13px;color:var(--color-neutral-700);margin:0 0 12px;line-height:1.55;">${i18t('co_send_readonly_to')} <strong>negotiation history</strong> ${i18t('co_every_change_who')} <strong>${i18t('co_no_account_needed')}</strong>${i18t('co_nothing_to_sign')}</p>
      ${readinessPanelHtml(c)}
      ${emailOff()?`<div id="sh-noemail" style="margin:0 0 12px;border:1px solid var(--st-amber-line);background:var(--st-amber-bg);border-radius:0;padding:10px 12px;font-size:13px;line-height:1.55;color:var(--st-amber-fg)">
        <b>${i18t('co_not_emailed')}</b> ${EMAIL_SETUP_LINE} ${i18t('co_press_create_link',{what:i18t('co_create_link'),who:esc(c.counterparty||i18t('co_them'))})}</div>`:''}
      ${server?'':`<div style="margin:0 0 12px;border:1px solid var(--st-ruby-line);background:var(--st-ruby-bg);border-radius:0;padding:10px 12px;">
        <div style="display:flex;align-items:center;gap:6px;font-size:13px;font-weight:600;color:var(--st-ruby-fg);margin-bottom:5px;">${icon('alert','w-3.5 h-3.5')} ${i18t('co_demo_sharing')}</div>
        <p style="margin:0;font-size:13px;line-height:1.6;color:var(--st-ruby-fg);">${i18t('co_without_server')} <strong>${i18t('co_inside_link')}</strong>. That link <strong>${i18t('co_never_expires')}</strong> — anyone who is forwarded it, now or in a year, can read this contract, and you will have no record that they did. Do not send a real contract this way. Run the HaTi server for tracked links that expire, can be withdrawn, and report back when they are opened.</p>
      </div>`}
      <div id="share-tabs" style="display:flex;gap:6px;margin-bottom:12px;">${tab('email','✉ Email',true)}${tab('whatsapp','WhatsApp',false)}${tab('link',i18t('co_copy_link'),false)}</div>
      <div id="share-fields">
        ${preNote?`<div id="sh-prefill-note" data-prefill-src="${attr(pre.source)}" style="display:flex;align-items:center;gap:7px;margin:0 0 9px;font-size:13px;color:var(--color-neutral-700);border:1px solid var(--color-divider);background:var(--color-bg);border-radius:0;padding:7px 10px">
          <span style="flex:none;color:var(--color-accent);display:inline-flex">${icon('check2','w-3.5 h-3.5')}</span>
          <span style="flex:1;min-width:0">${preNote}</span>
        </div>`:''}
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
          <label><span style="${LBL}">${i18t('co_recipient_name')}</span><input id="sh-name" type="text" value="${attr(pre.name)}" placeholder="e.g. Grace Njeri" style="${FLD}"/></label>
          <label id="sh-email-wrap"><span style="${LBL}">${i18t('co_recipient_email')}</span><input id="sh-email" type="email" value="${attr(pre.email)}" placeholder="them@company.co.ke" style="${FLD}"/></label>
          <label id="sh-phone-wrap" class="hidden"><span style="${LBL}">${i18t('co_whatsapp_number')}</span><input id="sh-phone" type="tel" value="${attr(pre.phone)}" placeholder="+254 7…" style="${FLD}"/></label>
        </div>
        <label style="display:block;margin-top:10px;"><span style="${LBL}">${i18t('co_personal_message')}</span>
          <textarea id="sh-msg" rows="2" placeholder="${esc(i18t('co_ph_share_msg'))}" style="${FLD}min-height:0;"></textarea></label>
        ${''/* ---- A BOX MUST SAY WHERE WHAT YOU TYPE IN IT GOES (13 Aug 2026) ----
               The counterparty's page used to reproduce this note in four
               places. It does not any more — a covering note belongs in the
               covering letter — so the note's ONLY road is the email or the
               WhatsApp text. Which means "copy the link" is now a channel that
               carries no message at all, and a box that silently swallows what
               somebody typed is worse than the banner ever was.

               One quiet line, naming the channel, repainted by setCh when the
               channel changes. It speaks for BOTH boxes: the step-1 note and
               this one are joined into one message before they travel. */}
        <div id="sh-msg-where" style="margin-top:5px;font-size:12px;line-height:1.5;color:var(--color-neutral-600)"></div>
        ${server?`<div style="margin-top:11px;border:1px solid var(--color-divider);border-radius:0;padding:9px 11px">
          <label style="display:flex;align-items:flex-start;gap:8px;font-size:13px;color:var(--color-neutral-800);cursor:pointer">
            ${''/* A SIGNING LINK OPENS ONE-SHOT, and the dialog's own words say
                   why: "the right choice for a final signature, where one copy
                   gets exactly one response". A signature has to bind exactly
                   one copy of exactly one text, so the standing-channel default
                   is wrong for it — and a default that contradicts the sentence
                   beside it is worse than no default. Still theirs to change. */}
            <input type="checkbox" id="sh-durable"${purposeSel==='sign'?'':' checked'} style="margin-top:2px;flex:none"/>
            <span><b>${i18t('co_keep_link_open')}</b>
            <span style="display:block;color:var(--color-neutral-600);line-height:1.5;margin-top:2px">${i18t('co_one_link_current')} <b>${i18t('co_single_answer_link')}</b> ${i18t('co_right_for_final')}</span></span>
          </label>
        </div>
        <label style="display:flex;align-items:center;gap:8px;margin-top:10px;font-size:13px;color:var(--color-neutral-700)">Link expires in
          <select id="sh-exp" style="border:1px solid var(--color-divider);background:var(--color-surface);border-radius:0;padding:4px 6px;font:inherit;font-size:13px;color:inherit;">
            ${[7,14,30,60].map(d=>`<option value="${d}" ${d===14?'selected':''}>${d} days</option>`).join('')}
          </select></label>`:''}
      </div>
      <div id="sh-result" style="margin-top:12px;"></div>
      <div style="margin-top:14px;display:flex;align-items:center;gap:8px;justify-content:flex-end;">
        <button id="share-back" class="ui-btn">← Back</button>
        <button id="share-close" class="ui-btn">${i18t('act_close')}</button>
        <button id="share-send" class="ui-btn ui-btn-primary">${icon('send','w-3.5 h-3.5')} <span id="sh-send-lbl">${i18t('co_send_by_email')}</span></button>
      </div>
      </div>
    </div>`,
    /* WIDER THAN THE 32rem DEFAULT. This dialog carries a scrolling change
       manifest and a five-row textarea, and then asks for a decision
       underneath both — at the default width the buttons sat below the fold
       and the sender had to scroll a modal to reach Next, on the screen whose
       whole job is "choose, then send". */
    { maxWidth:'46rem' });
  /* Both steps are built once and toggled, rather than re-rendered. The send
     form wires a dozen listeners to elements it looks up by id; rebuilding it
     on Next would mean wiring them all a second time, and the first one to be
     forgotten would be a silent dead control. */
  /* Three screens now: what are you sharing, what you are sending, who to.
     'kind' rather than 0 — the retired quick-send already owns 0, and a number
     that means "before the first one" is the kind of thing that gets read as
     zero-indexing by the next person to touch it. */
  const step = n => {
    qsActive = n===0;
    const s0=document.getElementById('share-step-0');
    if(s0) s0.classList.toggle('hidden', n!==0);
    document.getElementById('share-step-kind').classList.toggle('hidden', n!=='kind');
    document.getElementById('share-step-1').classList.toggle('hidden', n!==1);
    document.getElementById('share-step-2').classList.toggle('hidden', n!==2);
  };
  /* THE FIRST QUESTION'S ANSWER, and the only place it is written down. A
     history link is stored as its own purpose (see SHARE_PURPOSE), so choosing
     the record here replaces the sign/negotiate choice rather than sitting
     beside it — and choosing the contract again restores whatever the contract's
     own state says the default should be. */
  const setKind = k => {
    purposeSel = k==='history' ? 'history' : (SHARE_PURPOSE(opts.purpose)||defaultSharePurpose(c));
    payloadObj.purpose = purposeSel; payloadObj.purposeChosen = purposeSel;
    document.querySelectorAll('#share-kind [data-share-kind]').forEach(b=>{
      const on = (b.getAttribute('data-share-kind')==='history') === (purposeSel==='history');
      b.setAttribute('aria-pressed', on?'true':'false');
      b.style.border=`1.5px solid ${on?'var(--color-accent)':'var(--color-divider)'}`;
      b.style.background=on?'var(--color-accent-100)':'var(--color-surface)';
      const dot=b.querySelector('span'), name=b.querySelector('span:nth-child(2) span');
      if(dot){ dot.style.border=`1.5px solid ${on?'var(--color-accent)':'var(--color-neutral-500)'}`;
               dot.style.background=on?'var(--color-accent)':'transparent';
               dot.style.boxShadow=on?'inset 0 0 0 2.5px var(--color-surface)':'none'; }
      if(name) name.style.color=on?'var(--color-accent-800)':'var(--color-text)';
    });
    /* Step 2 is repainted rather than rebuilt — the sender may have edited the
       summary already, and rebuilding would take their words with it. */
    const hist = purposeSel==='history';
    document.getElementById('share-purpose-wrap')?.classList.toggle('hidden', hist);
    document.getElementById('share-hist-note')?.classList.toggle('hidden', !hist);
    const lab=document.getElementById('sh-summary-label');
    if(lab) lab.textContent = hist
      ? 'A note to send with the record — optional'
      : `A note to ${c.counterparty||'them'} — optional`;
    document.getElementById('share-manifest-line')?.classList.toggle('hidden', hist);
    document.getElementById('share-manifest-line-hist')?.classList.toggle('hidden', !hist);
    document.getElementById('share-manifest')?.classList.toggle('hidden', hist);
    document.getElementById('share-hist-preview')?.classList.toggle('hidden', !hist);
    /* Only the invitation changes with the choice. Nothing is written into the
       box by the switch, because nothing is written into it at all — whatever
       is in there was typed by the sender, and switching what is being shared
       is not a reason to take their words away. */
    const ta=document.getElementById('sh-summary');
    if(ta) ta.placeholder = hist
      ? 'e.g. The full record of our negotiation, for your file.'
      : 'e.g. We have moved on payment terms but not on the liability cap.';
    const blurb=document.getElementById('share-send-blurb');
    if(blurb) blurb.classList.toggle('hidden', hist);
    const hblurb=document.getElementById('share-send-blurb-hist');
    if(hblurb) hblurb.classList.toggle('hidden', !hist);
  };
  /* THE PURPOSE PICKER. Repainting the two buttons in place rather than
     re-rendering step 1: the summary textarea sits in that step and the sender
     may already have edited it, and rebuilding would throw their words away. */
  const paintPurpose=()=>{
    document.querySelectorAll('#share-purpose [data-share-purpose]').forEach(b=>{
      const on=b.getAttribute('data-share-purpose')===purposeSel;
      b.setAttribute('aria-pressed',on?'true':'false');
      b.style.border=`1.5px solid ${on?'var(--color-accent)':'var(--color-divider)'}`;
      b.style.background=on?'var(--color-accent-100)':'var(--color-surface)';
      const dot=b.querySelector('span span'), name=b.querySelectorAll('span')[2];
      if(dot){ dot.style.border=`1.5px solid ${on?'var(--color-accent)':'var(--color-neutral-500)'}`;
               dot.style.background=on?'var(--color-accent)':'transparent';
               dot.style.boxShadow=on?'inset 0 0 0 2.5px var(--color-surface)':'none'; }
      if(name) name.style.color=on?'var(--color-accent-800)':'var(--color-text)';
    });
    /* A signing link is one-shot by default and a negotiation link is standing,
       for the reason written beside the checkbox. Changing the purpose has to
       move it, or the picker would quietly leave the wrong kind of link. */
    const d=document.getElementById('sh-durable');
    if(d) d.checked = purposeSel!=='sign';
    /* WHO SIGNS belongs to the Sign purpose alone — on a negotiate link there
       is nothing to bind, and on a view link nobody is being asked for
       anything. Shown and hidden rather than built and thrown away, for the
       reason the branches above give. */
    document.getElementById('share-signers')?.classList.toggle('hidden', purposeSel!=='sign');
  };
  /* The row this link is for, or null for the free-typed recipient. Held here
     rather than read off the DOM at send time, so a repaint cannot lose it. */
  let signerSel = (pre.source==='route' && pre.signerId) ? pre.signerId : null;
  const paintSigners = () => {
    const host=document.getElementById('share-signer-rows'); if(!host) return;
    host.innerHTML=shareSignerRowsHtml(c, signerSel).html;
    wireSignerRows();
  };
  function wireSignerRows(){
    document.querySelectorAll('#share-signer-rows [data-share-signer]').forEach(b=>
      b.addEventListener('click',()=>{
        const id=b.getAttribute('data-share-signer');
        /* Pressing the chosen row again takes the binding off — a picker with
           no way back is a decision you cannot undo without closing the
           dialog. */
        signerSel = (String(signerSel||'')===String(id)) ? null : id;
        const row=(typeof signerPlan==='function'?signerPlan(c):[]).find(x=>x&&String(x.id)===String(signerSel));
        if(row){
          /* THE RECIPIENT FOLLOWS THE ROW. Two answers to "who is this for" on
             one screen is how a link ends up bound to one person and emailed
             to another. */
          const n=document.getElementById('sh-name'), e=document.getElementById('sh-email');
          if(n) n.value=row.name||'';
          if(e) e.value=row.email||'';
          if(!String(row.email||'').trim()) toast(i18t('co_signer_needs_email',{name:row.name||'that signer'}),'err');
        }
        paintSigners();
      }));
    document.getElementById('share-signer-edit')?.addEventListener('click',()=>{
      if(!window.openSignerPlanEditor){ toast(i18t('co_route_editor_missing'),'err'); return; }
      /* Back to this dialog, on this purpose, with the note kept — see the
         onDone note on openSignerPlanEditor. */
      const keep={ summary:fval('sh-summary'), note:fval('sh-msg') };
      openSignerPlanEditor(c, { onDone(){ openShareModal(c, { ...opts, purpose:'sign', resume:keep }); } });
    });
  }
  document.querySelectorAll('#share-purpose [data-share-purpose]').forEach(b=>
    b.addEventListener('click',()=>{ purposeSel=b.getAttribute('data-share-purpose');
      /* BOTH fields move with the picker. purposeChosen was stamped when the
         payload was built — from the DEFAULT — and only `purpose` moved here,
         so a sender who opened Share on a clean round-1 contract (default
         Sign) and picked Negotiate sent a payload still carrying
         purposeChosen:'sign'. portalIssuedForSigning trusts purposeChosen,
         so the counterparty's workbench mounted read-only — "the negotiation
         is closed on this link" — and they could not redline anything until
         the owner had proposed a change of their own, which is when the
         default happens to agree with the picker. What the picker shows at
         the moment of sending IS what the sender chose. */
      payloadObj.purpose=purposeSel; payloadObj.purposeChosen=purposeSel; paintPurpose(); }));
  document.querySelectorAll('#share-kind [data-share-kind]').forEach(b=>
    b.addEventListener('click',()=>setKind(b.getAttribute('data-share-kind'))));
  document.getElementById('share-close-kind').addEventListener('click',closeModal);
  document.getElementById('share-kind-next').addEventListener('click',()=>step(1));
  document.getElementById('share-close-1').addEventListener('click',closeModal);
  document.getElementById('share-next').addEventListener('click',()=>step(2));
  document.getElementById('share-back').addEventListener('click',()=>step(1));
  document.getElementById('share-back-kind').addEventListener('click',()=>step('kind'));
  wireSignerRows();
  /* Coming back from the route editor — the note the sender had typed before
     they went to assign somebody. Restored after the step is built, because
     the fields do not exist until then. */
  if(opts.resume){
    const su=document.getElementById('sh-summary'); if(su && opts.resume.summary) su.value=opts.resume.summary;
    const nt=document.getElementById('sh-msg');     if(nt && opts.resume.note)    nt.value=opts.resume.note;
  }
  setKind(purposeSel==='history'?'history':'contract');
  /* ---- ONLY THE SHARE BUTTON ASKS "WHAT ARE YOU SHARING?" ----
     Pressing Send on a redline opens this dialog too — the send path falls
     back to it when the contract has no recipient on record yet — and being
     met with "the contract, or the negotiation history?" after asking to send
     a change is a question about something the caller already decided. Same
     for the signing route and for handing a round over: each arrives with the
     answer in its hand.

     So the question is asked when, and only when, nobody has stated an intent:
     the plain Share button, which calls this with no options at all. Everything
     else opens where it always did, on what it is sending. */
  const askKind = !(opts.handOver || SHARE_PURPOSE(opts.purpose));
  document.getElementById('share-back-kind')?.classList.toggle('hidden', !askKind);
  step(askKind ? 'kind' : 1);
  /* WHAT THE READER DID WHILE IT WAS LOADING, honoured now. The markup above
     was already built from the purpose they chose, so setKind is here to bring
     the payload and the second screen's copy into line with it rather than to
     repaint the cards; the press of Next is replayed last so it lands on a
     dialog that is fully wired. */
  if (_pending.kind) setKind(_pending.kind);
  if (_pending.next && askKind) step(1);
  const setCh=k=>{ ch=k;
    document.querySelectorAll('[data-share-ch]').forEach(b=>{ const on=b.getAttribute('data-share-ch')===k;
      b.style.border=`1px solid ${on?'var(--color-accent)':'var(--color-divider)'}`;
      b.style.background=on?'var(--color-accent)':'var(--color-surface)';
      b.style.color=on?'#fff':'var(--color-neutral-700)'; });
    document.getElementById('sh-email-wrap').classList.toggle('hidden',k==='whatsapp');
    document.getElementById('sh-phone-wrap').classList.toggle('hidden',k!=='whatsapp');
    document.getElementById('sh-send-lbl').textContent=k==='email'?'Send by email':k==='whatsapp'?'Open WhatsApp':'Create link';
    /* WHERE THE NOTE GOES, said under the box it is typed into. A copied link
       carries no message at all now that the counterparty's page has stopped
       reproducing it, so that branch is a WARNING and wears the warning
       colour; the other two are a plain statement. */
    const where=document.getElementById('sh-msg-where');
    if(where){
      const none=k!=='email'&&k!=='whatsapp';
      where.textContent=i18t(k==='email'?'co_note_goes_email'
        :k==='whatsapp'?'co_note_goes_whatsapp':'co_note_goes_nowhere');
      where.style.color=none?'var(--st-amber-fg)':'var(--color-neutral-600)';
      where.style.fontWeight=none?'600':'400';
    }
  };
  document.querySelectorAll('[data-share-ch]').forEach(b=>b.addEventListener('click',()=>setCh(b.getAttribute('data-share-ch'))));
  /* Called for EVERY channel, email included. It used to be skipped there
     because the markup already draws email as the active one — but the line
     saying where the note goes has no markup default, so an unconditional
     first paint is what makes it present before anything is pressed. */
  setCh(ch);
  document.getElementById('share-close').addEventListener('click',closeModal);

  /* Set when the send refreshed a link the recipient already had rather than
     minting another. It sits ABOVE whatever the channel reports, because "which
     link is this" is a different fact from "did the email leave", and the
     channel branches below each write the whole box. */
  let reuseNote='';
  /* The outcome lands where the sender is standing: the quick panel's own box
     when step 0 is live, the form's box otherwise. */
  const resultBox=(html)=>{ const host=document.getElementById(qsActive?'qs-result':'sh-result');
    if(host) host.innerHTML=reuseNote+html; };
  const copyBox=(link,note)=>`
    <div style="border:1px solid var(--color-divider);background:var(--color-accent-100);border-radius:0;padding:12px;">
      ${note?`<div style="font-size:13px;color:var(--color-accent-800);font-weight:600;margin-bottom:6px;display:flex;align-items:center;gap:6px">${icon('check2','w-3.5 h-3.5')} ${note}</div>`:''}
      <textarea id="share-link" readonly rows="3" style="width:100%;border:1px solid var(--color-divider);background:var(--color-surface);border-radius:0;padding:9px;font-size:12px;font-family:var(--font-mono);color:var(--color-text);outline:none;word-break:break-all;">${link}</textarea>
      <button id="share-copy" class="ui-btn" style="margin-top:6px;font-size:13px;">${icon('copy','w-3 h-3')} ${i18t('co_copy_link')}</button>
    </div>`;
  const wireCopy=()=>document.getElementById('share-copy')?.addEventListener('click',async()=>{
    const ta=document.getElementById('share-link'); ta.select();
    try{ await navigator.clipboard.writeText(ta.value); }catch(e){ document.execCommand('copy'); }
    toast(i18t('co_share_copied'));
  });

  /* ONE SEND, TWO DOORS (WO N4). The form's Send button and the quick panel's
     Send button both press this. Every gate below — the email check, the
     signing-approval refusal, the readiness acknowledgement, the address
     confirmation — holds for both doors, because there is only one path.
     Returns true only when a link actually went out (or was handed over). */
  const doSend=async()=>{
    const name=fval('sh-name'), email=fval('sh-email'), phone=fval('sh-phone');
    /* The note the sender WROTE on step 1 travels with the link: into the
       message body, and onto the payload so the landing page still shows it to
       someone who opens the link a week later. It is empty unless they typed
       something — the box is no longer pre-filled with the generated change
       list, so an empty note now means "they had nothing to add" rather than
       "they did not bother deleting the machine's paragraph". */
    const summary=fval('sh-summary').trim();
    const note=fval('sh-msg').trim();
    const msg=[summary,note].filter(Boolean).join('\n\n');
    /* ---- AND THE NOTE IS NOT WRITTEN INTO THE PAYLOAD (13 Aug 2026) ----
       `payloadObj.contract.changeSummary = summary` used to put the sender's
       own step-1 words onto the copy the counterparty downloads, where their
       landing page drew them under the heading "What changed" — a third title
       on the same typed paragraph. The owner asked for the covering note to
       live in the email and for their page to show the contract, so the field
       stops being written and a new link does not carry a copy. Older links
       still hold one; the page draws nothing from it either way, and the
       server no longer serves the message field at all. Flag changeSummary as
       stale. `msg` above is untouched — that IS the email and the WhatsApp
       text, which is where the note goes. */
    if(ch==='email' && !/.+@.+\..+/.test(email)){ toast(i18t('co_enter_recipient_email'),'err'); return false; }
    if(ch==='whatsapp' && phone.replace(/\D/g,'').length<9){ toast(i18t('co_enter_whatsapp'),'err'); return false; }
    /* A SIGNING LINK IS NOT AN ACKNOWLEDGEABLE RISK.

       Everything else on the readiness list is the sender's call — a missing
       effective date, a Draft status, even an unfilled placeholder: they tick
       the box, they own it, and the contract can still be pulled back. An
       outstanding internal approval on a link whose purpose is SIGN is a
       different kind of thing. The counterparty's signature executes the
       contract by itself, through applyResponse, and a signature cannot be
       taken back — so the approval the organisation requires would be
       permanently bypassed by one tick of a checkbox in the sender's own
       dialog. signDocument refuses this outright rather than warning about it;
       so does this. A negotiation link is unaffected: sending a draft out for
       comment is exactly what happens BEFORE approval. */
    if(purposeSel==='sign'){
      let ap=null; try{ ap=(window.approvalState)?window.approvalState(c):null; }catch(_){ ap=null; }
      if(ap && ap.required && !ap.ok){
        toast(`This contract needs internal approval before it can go out for signature — ${
          (ap.rejected||[]).length ? 'an approver refused it'
          : (ap.stale||[]).length ? 'it changed after it was approved'
          : `“${ap.next?ap.next.name:'approval'}” is still waiting on ${ap.approverLabel||'an approver'}`
        }. Send it to negotiate instead, or clear the approval first.`,'err');
        return false;
      }
    }
    /* AND THE REDLINES' OWN GATE, WHICH BITES EARLIER AND ON THE OTHER PURPOSE.

       The block above deliberately lets a negotiation link past an outstanding
       approval, because sending a draft out for comment is what happens BEFORE
       approval. That reasoning is right about approval and says nothing about
       review: the whole point of an internal review is that it happens before
       the wording travels, so the link it governs is exactly the one approval
       waves through. Not acknowledgeable, for the same reason — a redline
       cannot be recalled either. */
    if(reviewSendBlock(c)) return false;
    // A share cannot be recalled, so an incomplete contract needs an explicit
    // acknowledgement rather than a toast that scrolls away.
    const ack=document.getElementById('sh-ack');
    if(ack && !ack.checked){
      toast(i18t('co_not_ready_to_send'),'err');
      const panel=document.getElementById('share-readiness');
      if(panel){ panel.style.outline='2px solid var(--st-ruby-dot)'; setTimeout(()=>{ panel.style.outline=''; },1600);
                 panel.scrollIntoView({ block:'nearest', behavior:'smooth' }); }
      return false;
    }
    /* H-7: a signing code is only as safe as the address it is sent to, and that
       address is whatever the sender typed. Before a BINDING signing link goes
       out, echo the exact address back for one explicit confirmation — a typo
       here delivers a valid signing code to a real-but-wrong inbox, which is
       hard to walk back. Only signing links are gated; sending a draft out to
       negotiate is not this kind of risk. */
    /* ---- A SIGNING LINK NEEDS SOMEBODY TO SIGN IT ----
       The other half of the wall described at shareSignerPickHtml, and the
       half the owner asked for explicitly ("go with both"): the counterparty's
       page and the server both refuse a signature with no route, and this
       stops the dead link ever being made. Refusing at the point of sending is
       the kinder end — finding out on their screen means a wasted round trip
       and a counterparty told the sender made a mistake.

       It points at the block rather than only saying no: the door to fix it is
       three lines up the same dialog. */
    if(purposeSel==='sign' && shareNeedsSigners(c)){
      toast(i18t('co_send_needs_signers'),'err');
      const box=document.getElementById('share-signers-box');
      if(box){ box.style.outline='2px solid var(--st-amber-dot)'; setTimeout(()=>{ box.style.outline=''; },1800);
               box.scrollIntoView({ block:'nearest', behavior:'smooth' }); }
      return false;
    }
    if(purposeSel==='sign' && ch==='email'){
      const okAddr=await confirmDialog({
        get title(){ return i18t('co_send_signing_q'); },
        message:'The one-time signing code will go to '+email+' — and only to that address. Check it is exactly right; a signing code sent to the wrong inbox is hard to undo.',
        confirmLabel:'Send to '+email, cancelLabel:'Go back' });
      if(!okAddr) return false;
    }
    const rcptLabel=name||email||phone||c.counterparty||'counterparty';
    if(server){
      let r;
      const durableEl=document.getElementById('sh-durable');
      /* ONE PERSON, ONE LINK — the second half of a fix the contract page had
         and this dialog did not.

         There were two ways to send the next round and they did different
         things. "Send updated version" refreshed the link the counterparty
         already had open; Share — and the negotiation room's "Send to …",
         which comes through here — minted a SECOND link and left the first one
         live. Nothing on screen said which was which, so the commonest way to
         send round two put two live links in one inbox, and the reader could
         be answering the older one with neither side able to tell.

         So a standing negotiation link to this same address is refreshed in
         place rather than duplicated. A SIGNING link is deliberately exempt:
         issuing one is what retires the negotiation links, and it has to be its
         own copy for one signature to bind one text. */
      /* THE SAME "can this be refreshed" predicate as the round send, and
         DELIBERATELY NOT its fallback. standingShareFor ends by taking the
         newest standing link when nothing matches, which is right for a round
         — the question there is where this negotiation is happening. Here the
         sender has just typed a name and an address, and reusing a stranger's
         link because it happened to be the only one open would be a worse bug
         than the one that ordering fixes. The typed address is the match. */
      const wantDurable=durableEl?!!durableEl.checked:false;
      const reuse=(wantDurable && payloadObj.purpose!=='sign' && email)
        ? standingShares(priorShares).find(s=>
            String(s.recipientEmail||'').trim().toLowerCase()===String(email).trim().toLowerCase())
        : null;
      try{
        r = reuse
          ? await api('shares/'+reuse.token+'/payload','PUT',{ payload:payloadObj })
          : await api('shares','POST',{ payload:payloadObj, channel:ch, message:msg,
              recipient:{ name, email, phone }, expiryDays:Number(fval('sh-exp'))||14,
              durable:wantDurable, purpose:payloadObj.purpose,
              /* BOUND AT THE SOURCE. The server can already match a signing
                 address to an unsigned row on its own, and does; saying it
                 outright is better because the sender CHOSE this row, and an
                 address that appears twice on a route would otherwise be
                 resolved by "earliest unsigned wins" rather than by what was
                 on screen. Sent only on a signing link — it is meaningless on
                 the other two, and the server validates it against the stored
                 plan either way. */
              signerId:(payloadObj.purpose==='sign' && signerSel) ? signerSel : undefined });
      }
      catch(e){ toast(e.message,'err'); return false; }
      reuseNote = reuse ? `<div style="border:1px solid var(--color-divider);background:var(--color-accent-100);border-radius:0;padding:10px 12px;font-size:13px;line-height:1.55;color:var(--color-accent-800);margin-bottom:8px">
        <b>${i18t('co_already_had_link',{who:esc(name||email)})}</b>
        No second link was created — there is still exactly one, and nothing older is left open.</div>` : '';
      if(ch==='email'){
        // Three different outcomes used to read as one cheerful green box that
        // always blamed a missing mail key — including when the key was working
        // and the provider had refused the message for a stated reason. Say
        // which of the three actually happened, and quote the reason.
        const link=r.link?`<div style="margin-top:8px"><span style="font-family:var(--font-mono);font-size:12px;word-break:break-all">${esc(r.link)}</span></div>`:'';
        if(r.emailSent){
          resultBox(`<div style="border:1px solid color-mix(in srgb,var(--st-green-dot) 30%,transparent);background:var(--st-green-bg);border-radius:0;padding:12px;font-size:13px;color:var(--st-green-fg);display:flex;align-items:flex-start;gap:8px;">${icon('check2','w-4 h-4')}<span><strong>${i18t('co_email_sent')}</strong> to ${esc(email)}. Their answers land on the contract here as they make them — watch it in Negotiation rather than your inbox. Fill in another recipient to share again.</span></div>`);
        } else if(r.alreadySentAt){
          /* Nothing was refused: their live link already went, and no
             duplicate was emailed on purpose. Saying "Not delivered" here was
             the false alarm of 02 Aug 2026. */
          resultBox(`<div style="border:1px solid color-mix(in srgb,var(--st-green-dot) 30%,transparent);background:var(--st-green-bg);border-radius:0;padding:12px;font-size:13px;color:var(--st-green-fg);display:flex;align-items:flex-start;gap:8px;">${icon('check2','w-4 h-4')}<span><strong>${i18t('co_already_sent')}</strong> ${esc(email)} received their link ${fmtDT(r.alreadySentAt)}, and it is still live — no duplicate was sent. This link now shows the current version.${link}</span></div>`);
        } else if(r.heldForTurn){
          /* ---- NOTHING WAS REFUSED. NOTHING WAS ATTEMPTED. ----
             A signing link bound to a signer who is not first is created,
             parked, and emailed by the server the moment the signer before
             them finishes. That is the design working. It fell into the
             refusal branch below and came out amber, reading "the mail
             provider refused it … No reason was given" over a send that was
             never made (reported 12 Aug 2026).

             NEUTRAL, NOT AMBER: amber is for something the reader has to act
             on, and there is nothing to do here but wait.

             THE FACT IS READ, NOT RE-DERIVED — heldForTurn and heldFor both
             come off the reply. The route that decides to hold is the only
             thing that should decide what we say about it.

             AND THE WORDS ARE THE SIGNING CARD'S OWN (see js/approvals.js,
             the 'held' row): "link ready — it goes out when their turn
             arrives". One fact must not grow a second phrase.

             THE URL IS DELIBERATELY NOT SHOWN. The old sentence offered it as
             "safe to send another way", which is the part that actually did
             harm: a held link opens a dormant "waiting on an earlier signer"
             page, so a recipient handed it early meets a holding screen and
             concludes the link is broken. It is not withheld silently — the
             Shares panel lists every link and is the durable record. */
          const waitOn=(r.heldFor&&r.heldFor.name)?esc(r.heldFor.name):i18t('co_held_earlier_signer');
          resultBox(`<div style="border:1px solid var(--st-steel-line);background:var(--st-steel-bg);border-radius:0;padding:12px;font-size:13px;color:var(--st-steel-fg);display:flex;align-items:flex-start;gap:8px;">${icon('clock','w-4 h-4')}<span><strong>${i18t('co_link_held')}</strong> ${
            i18t('co_link_held_body',{who:esc(email),waiting:waitOn})}<br><span style="display:inline-block;margin-top:6px;font-size:12px;opacity:.85">${i18t('co_link_held_where')}</span></span></div>`);
        } else if(r.emailConfigured){
          /* A REAL refusal, which always carries a reason: sendEmail returns
             the provider's own sentence and falls back to "Resend rejected
             this message (<status>)" when the provider says nothing. The
             invented "No reason was given." is gone with the branch that
             produced it — it described a state that cannot occur once a
             non-attempt stops being reported as a refusal. */
          resultBox(`<div style="border:1px solid color-mix(in srgb,var(--st-amber-dot) 45%,transparent);background:color-mix(in srgb,var(--st-amber-dot) 10%,transparent);border-radius:0;padding:12px;font-size:13px;color:var(--st-amber-fg);display:flex;align-items:flex-start;gap:8px;">${icon('alert','w-4 h-4')}<span><strong>${i18t('co_not_delivered')}</strong> The link was created and is safe to send another way, but ${esc(email)} has not received anything.${r.emailError?`<br><span style="display:inline-block;margin-top:6px;font-family:var(--font-mono);font-size:12px;line-height:1.5">${esc(r.emailError)}</span>`:''}${link}</span></div>`);
        } else {
          resultBox(`<div style="border:1px solid color-mix(in srgb,var(--st-amber-dot) 45%,transparent);background:color-mix(in srgb,var(--st-amber-dot) 10%,transparent);border-radius:0;padding:12px;font-size:13px;color:var(--st-amber-fg);display:flex;align-items:flex-start;gap:8px;">${icon('alert','w-4 h-4')}<span><strong>${i18t('co_queued_not_sent')}</strong> This server has no mail provider set up, so nothing left HaTi. An admin can read the message and the link in the outbox under Team &amp; Settings.${link}</span></div>`);
        }
      } else if(ch==='whatsapp'){
        const wa=waShareLink(phone, shareMessageText(c,r.link,msg,r.expiresAt));
        window.open(wa,'_blank');
        resultBox(copyBox(r.link,`Tracked link created for ${rcptLabel} — WhatsApp opened with the message prefilled. If it didn’t open, copy the link below.`)); wireCopy();
      } else { resultBox(copyBox(r.link, reuse
          ? `${name||rcptLabel} keeps the link they already have — it now shows this version.`
          : `Tracked link created${name?` for ${name}`:''}${r.expiresAt?` — expires ${String(r.expiresAt).slice(0,10)}`:''}.`)); wireCopy(); }
      /* THE DRAFT AS IT WENT OUT, on the version list a person reads.

         "Go back to what we sent them on Tuesday" is the commonest thing anyone
         wants from a version list, and until now a negotiation run entirely
         through the room produced NO listed versions at all — the automatic
         copies are unlisted by design, and the hand-over capture only fires on
         a turn that actually moves. So the list read "0 versions" through a
         whole round and there was nothing to compare against and nothing to go
         back to. captureVersion refuses a no-change capture, so sending twice
         without editing does not file two. */
      if(c.status!=='Signed' && window.captureVersion)
        captureVersion(c, `Sent to ${rcptLabel}${payloadObj.purpose==='sign'?' for signature':''}`,
          currentUser()?.name, { auto:true, listed:true });
      /* IT IS NOT A DRAFT ONCE IT IS WITH THE OTHER SIDE.

         The status only ever moved on the "Send for review" button, which is an
         internal step nobody presses once there is a counterparty to send to.
         So a contract could go through six rounds of real negotiation with a
         named buyer — proposals, refusals, counter-wording — and still call
         itself Drafting on every screen and in every filter of the register.
         Sending it to somebody outside the building IS the transition, and it
         is the one the owner can see happening. */
      /* AND IT IS THEIR MOVE NOW.

         Handing the turn over was something only the negotiation room's own
         send did, so a draft sent from the Share button left the record saying
         it was still the owner's turn. With the status finally moving to
         Under Review that became visible and wrong in the same breath: the bar
         dropped straight to "Approved — confirm intent and sign below" on a
         contract that had just gone out for the other side to argue with.

         negoHandOver is idempotent and returns null if the turn is already
         theirs, so the room's send and this one cannot fight. A signing link is
         excluded — a signature request is not a negotiating turn. */
      /* The address this dialog collected, kept — see shareRememberRecipient
         for why every later Send was re-asking for it. */
      shareRememberRecipient(c, { purpose:payloadObj.purpose, email, name });
      if(payloadObj.purpose!=='sign' && c.status!=='Signed' && window.negoHandOver){
        try{ negoHandOver(c, { to:'counterparty', by:currentUser()?.name }); }catch(_){}
      }
      if(c.status==='Draft'){
        c.status='Under Review';
        logAudit(c,'Status changed',`Draft → Under Review — sent to ${rcptLabel}`);
        /* The chip AND the bar. Changing the status without repainting the bar
           left it still reading "Key terms are set — move it into review", with
           a button offering to do the thing that had just been done — the same
           stale-bar fault as after signing, in a different place. */
        try{ if(typeof updateStatusUI==='function') updateStatusUI(c); }catch(_){}
        try{ if(typeof renderActionBar==='function') renderActionBar(c); }catch(_){}
      }
      // H-7: record the EXACT destination address on the audit trail, not just a
      // display label — so "who was this sent to" is provable later, especially
      // for a signing link where the address is what a signature rests on.
      const addr=(ch==='email'&&email)?` to ${email}`:(ch==='whatsapp'&&phone)?` to ${phone}`:'';
      logAudit(c,'Shared',`${reuse?`Published to ${rcptLabel}'s existing link`:`Sent to ${rcptLabel}`}${addr} via ${ch==='link'?'link':ch}${purposeSel==='sign'?' (signing link)':''}${msg?' with a message':''}`);
      persist(c); renderAuditSection(c);
      refreshShareOverview(); renderSharesSection(c);
      if(typeof opts.onSent==='function')
        try{ opts.onSent({ channel:ch, recipient:rcptLabel, link:r.link||null,
          emailSent:!!r.emailSent, emailConfigured:!!r.emailConfigured }); }catch(e){}
      return true;
    } else {
      // static mode: the whole payload travels in the URL fragment
      const link=location.href.split('#')[0]+'#share='+b64e(payloadObj);
      if(ch==='email'){
        const subject=`${currentUser().name} shared "${c.name}" for your review`;
        location.href='mailto:'+encodeURIComponent(email)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(shareMessageText(c,link,msg,null));
        resultBox(copyBox(link,'Your email app opened with the message prefilled. If it didn’t, copy the link below.')); wireCopy();
      } else if(ch==='whatsapp'){
        window.open(waShareLink(phone, shareMessageText(c,link,msg,null)),'_blank');
        resultBox(copyBox(link,'WhatsApp opened with the message prefilled. If it didn’t, copy the link below.')); wireCopy();
      } else { resultBox(copyBox(link)); wireCopy(); }
      shareRememberRecipient(c, { purpose:payloadObj.purpose, email, name });
      logAudit(c,'Shared',`Review link ${ch==='link'?'generated':'sent via '+ch} for ${rcptLabel}`);
      if(typeof opts.onSent==='function')
        try{ opts.onSent({ channel:ch, recipient:rcptLabel, link, emailSent:false, emailConfigured:false }); }catch(e){}
      persist(c); renderAuditSection(c);
      return true;
    }
  };
  /* The Send button owns its outcome (Young, 02 Aug 2026): silence after a
     click read as "nothing happened", people clicked again, and the repeat
     sends produced false "Not delivered" reports. In flight it locks and says
     Sending…; success shows Sent ✓ and re-arms after a beat (the dialog
     supports sending to another recipient); a refused gate re-arms at once so
     the sender can fix the reason and press again. */
  const shareSendBtn=document.getElementById('share-send');
  shareSendBtn.addEventListener('click',async()=>{
    if(shareSendBtn.dataset.busy) return;
    const lbl=document.getElementById('sh-send-lbl');
    const was=lbl?lbl.textContent:'';
    shareSendBtn.dataset.busy='1'; shareSendBtn.disabled=true; shareSendBtn.style.opacity='.75';
    if(lbl) lbl.textContent='Sending…';
    let ok=false;
    try{ ok=await doSend(); }catch(e){ toast(e&&e.message||'Could not send','err'); }
    if(ok){
      if(lbl) lbl.textContent='Sent ✓';
      setTimeout(()=>{ if(lbl) lbl.textContent=was;
        shareSendBtn.disabled=false; shareSendBtn.style.opacity='1'; delete shareSendBtn.dataset.busy; },2500);
    } else {
      if(lbl) lbl.textContent=was;
      shareSendBtn.disabled=false; shareSendBtn.style.opacity='1'; delete shareSendBtn.dataset.busy;
    }
  });
  /* The quick panel's Send: same handler, and the button owns its outcome —
     disabled while in flight, "Sent" once it went, re-armed if a gate said no
     so the sender can fix the reason and press again. */
  document.getElementById('qs-send')?.addEventListener('click',async e=>{
    const b=e.currentTarget; if(b.disabled) return;
    b.disabled=true; b.style.opacity='.75';
    const ok=await doSend();
    if(ok){
      b.innerHTML=`${icon('check2','w-3.5 h-3.5')} Sent`;
      const cxl=document.getElementById('qs-cancel'); if(cxl) cxl.textContent='Close';
      const det=document.getElementById('qs-details'); if(det) det.remove();
    } else { b.disabled=false; b.style.opacity='1'; }
  });
  document.getElementById('qs-cancel')?.addEventListener('click',closeModal);
  document.getElementById('qs-details')?.addEventListener('click',()=>step(1));
}

/* Nothing left the building. Say so plainly and hand over the link, rather
   than reporting success and leaving the counterparty waiting for an email
   that was never going to arrive. */
function reshareNotSentModal(c, out, who){
  /* WHAT CAN AND CANNOT REACH THIS MODAL, checked 12 Aug 2026 while fixing the
     share dialog's false "Not delivered".

     A HELD SIGNING LINK CANNOT. reshareToLastRecipient never binds a signer —
     it posts without signerId and refreshes a durable link in place — so the
     server never holds one for it and heldForTurn is never on the reply. No
     branch is written for it here, deliberately: a branch that cannot run is
     the same fault as wording that describes a state that cannot occur.

     A DELIBERATELY QUIET ROUND USED TO. A round published onto a standing link
     sends nothing on purpose, and both callers fell through to this modal and
     were told the provider had refused it. That is caught at the callers now,
     where the contract page had already been saying it correctly.

     So the last branch is only reached by a real refusal — and a real refusal
     always carries a reason (sendEmail falls back to "Resend rejected this
     message (<status>)" when the provider says nothing at all). */
  const reason = out.channel!=='email'
    ? `This counterparty was shared with by ${out.channel==='whatsapp'?'WhatsApp':'a copied link'}, so HaTi does not send anything automatically.`
    : out.emailConfigured===false
      ? 'This workspace has no email provider set up, so HaTi could not send it.'
      : `The mail provider refused it${out.emailError?`: ${esc(out.emailError)}`:'.'}`;
  openModal(`
    <div style="padding:22px 24px">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px"><span style="color:var(--st-amber-dot);display:inline-flex">${icon('alert')}</span>
        <h2 style="font-family:var(--font-heading);font-weight:600;font-size:18px;margin:0">${i18t('co_link_updated_not_sent')}</h2></div>
      <p style="font-size:14px;color:var(--color-neutral-700);margin:0 0 12px;line-height:1.55">
        ${esc(who)} is now looking at the current wording <b>${i18t('co_if_they_open')}</b> — but they have not been told.
        ${reason} Send them this link yourself:</p>
      <textarea id="rs-link" readonly rows="3" style="width:100%;border:1px solid var(--color-divider);background:var(--color-surface);border-radius:0;padding:9px;font-size:12px;font-family:var(--font-mono);color:var(--color-text);outline:none;word-break:break-all">${esc(out.link||'')}</textarea>
      <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px">
        <button id="rs-copy" class="ui-btn">${icon('copy','w-3 h-3')} ${i18t('co_copy_link')}</button>
        <button id="rs-close" class="ui-btn ui-btn-primary">${i18t('act_close')}</button>
      </div>
    </div>`);
  document.getElementById('rs-close').addEventListener('click',closeModal);
  document.getElementById('rs-copy').addEventListener('click',async()=>{
    const ta=document.getElementById('rs-link'); ta.select();
    try{ await navigator.clipboard.writeText(ta.value); }catch(e){ document.execCommand('copy'); }
    toast(i18t('co_link_copied'));
  });
}

/* ---- has the other side actually seen this? ----
   "Under review" covers two completely different situations: they are reading
   it and thinking, or they never opened it and do not know it exists. The
   server has always recorded when a link was first opened, and a durable link's
   opened-marker is cleared each time the wording is refreshed — so the answer
   is already in the data and was simply never shown. Without it, a stalled
   negotiation looks exactly like a considered silence.

   Returns null when there is nothing worth saying: no share, an anonymous
   copy-link (nobody to have seen it), or a contract already executed. */
function counterpartySeenState(c, shares){
  if(!c || c.status==='Signed') return null;
  const live=(shares||[]).filter(s=>!s.revokedAt && s.state!=='expired'
    && (s.recipientEmail||s.recipientPhone||s.recipientName));
  if(!live.length) return null;
  const latest=live.slice().sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')))[0];
  const who=latest.recipientName||latest.recipientEmail||latest.recipientPhone||'The counterparty';
  if(latest.respondedAt) return { kind:'responded', who, at:latest.respondedAt, share:latest };
  if(latest.firstOpenedAt) return { kind:'opened', who, at:latest.firstOpenedAt, share:latest };
  return { kind:'unopened', who, at:latest.sentAt||latest.createdAt, share:latest };
}
/* Days since a moment, floored. Used only to decide how loudly to say it. */
const _daysSince = iso => { const t=Date.parse(iso||''); return Number.isFinite(t)?Math.floor((Date.now()-t)/86400000):0; };
function counterpartySeenHtml(c, shares){
  const st=counterpartySeenState(c, shares);
  if(!st || st.kind==='responded') return '';   // they answered; the round strip speaks
  const days=_daysSince(st.at);
  const esc=s=>String(s==null?'':s).replace(/[&<>]/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[x]));
  const stale=days>=3;
  if(st.kind==='opened') return `
    <div id="seen-state" style="display:flex;align-items:center;gap:9px;flex-wrap:wrap;border:1px solid var(--color-divider);background:var(--color-surface);border-radius:0;padding:9px 13px;margin-bottom:12px;font-size:13px;color:var(--color-neutral-700)">
      <span style="flex:none;color:var(--st-green-fg);display:inline-flex">${icon('check2','w-3.5 h-3.5')}</span>
      <span style="flex:1;min-width:160px">${i18t('co_opened_no_response',{who:esc(st.who),when:days===0?i18t('co_opened_today'):i18tn('co_opened_days',days,{n:days})})}</span>
    </div>`;
  return `
    <div id="seen-state" style="display:flex;align-items:center;gap:9px;flex-wrap:wrap;border:1px solid ${stale?'var(--st-amber-line)':'var(--color-divider)'};background:${stale?'var(--st-amber-bg)':'var(--color-surface)'};border-radius:0;padding:9px 13px;margin-bottom:12px;font-size:13px;color:${stale?'var(--st-amber-fg)':'var(--color-neutral-700)'}">
      <span style="flex:none;color:${stale?'var(--st-amber-dot)':'var(--color-neutral-500)'};display:inline-flex">${icon(stale?'alert':'clock','w-3.5 h-3.5')}</span>
      <span style="flex:1;min-width:160px"><b>${esc(st.who)} has not opened the current version.</b> Sent ${days===0?'today':`${days} day${days===1?'':'s'} ago`}${stale?' — worth chasing, or check the link reached them.':'.'}</span>
      ${canEdit()?`<button id="seen-resend" class="ui-btn" style="flex:none;font-size:12px;padding:5px 11px">${i18t('co_send_again')}</button>`:''}
    </div>`;
}

/* ---------- the send journey, as lights with words (WO N4) ----------
   Four moments — Sent, Opened, Responded, Signed — drawn as one strip at the
   head of the contract's Shares panel. RULE: never a colour alone. Every
   light carries plain words saying what happened, and the strip closes with
   one sentence naming whose move it is — the difference between a status
   display and an answer. Read from the same share records the panel lists
   (sentAt / firstOpenedAt / respondedAt) and the contract's own status for
   the last light; nothing here is a second source of truth. */
function shareJourneyState(c, shares){
  if(!c) return null;
  const live=(shares||[]).filter(s=>s&&!s.revokedAt&&s.state!=='revoked'&&s.state!=='expired');
  if(!live.length) return null;
  const latest=live.slice().sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')))[0];
  const who=latest.recipientName||latest.recipientEmail||latest.recipientPhone||'the counterparty';
  const signed=c.status==='Signed';
  const responded=!!latest.respondedAt;
  const opened=!!latest.firstOpenedAt;
  const days=_daysSince(latest.sentAt||latest.createdAt);
  const stale=!opened&&!responded&&!signed&&days>=3;
  const now=signed?'signed':responded?'responded':opened?'opened':'sent';
  const sentence=
    signed ? 'Signed and sealed — nothing is waiting on anyone.'
    : responded ? `${who} answered — your move now.`
    : opened ? `${who} is reading it. Nothing for you to do yet.`
    : stale ? `${who} has not opened it in ${days} days — worth chasing, or check the link reached them.`
    : `Out with ${who} — they have not opened it yet.`;
  return { who, latest, signed, responded, opened, now, days, stale, sentence,
    stages:[
      { k:'sent', get label(){ return i18t('co_sh_sent'); }, on:true,
        words:`${fmtDT(latest.sentAt||latest.createdAt)}${(latest.expiresAt&&!responded&&!signed)?` · link valid to ${String(latest.expiresAt).slice(0,10)}`:''}` },
      { k:'opened', get label(){ return i18t('co_sh_opened'); }, on:opened||responded||signed,
        words: opened?fmtDT(latest.firstOpenedAt):(responded||signed)?'answered directly':'not yet' },
      { k:'responded', get label(){ return i18t('co_responded'); }, on:responded||signed,
        words: responded?`${fmtDT(latest.respondedAt)}${signed?'':' — your turn'}`:(signed?'—':'not yet') },
      { k:'signed', get label(){ return i18t('co_sh_signed'); }, on:signed, words: signed?'sealed & filed':'not yet' },
    ] };
}
function shareJourneyHtml(c, shares){
  const j=shareJourneyState(c, shares);
  if(!j) return '';
  const esc=s=>String(s==null?'':s).replace(/[&<>]/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[x]));
  const cell=s=>{
    const cur=s.k===j.now;
    const col=!s.on?'transparent'
      : s.k==='signed'?'var(--st-green-dot)'
      : (s.k==='responded'&&cur)?'var(--st-amber-dot)'
      : 'var(--color-accent)';
    return `<div data-journey="${s.k}" style="flex:1;min-width:108px">
      <div style="display:flex;align-items:center;gap:7px">
        <span style="flex:none;width:11px;height:11px;border-radius:50%;background:${col};border:2px solid ${s.on?col:'var(--color-neutral-400)'}"></span>
        <span style="font-size:12px;font-weight:${cur?'700':'600'};color:${s.on?'var(--color-text)':'var(--color-neutral-500)'}">${s.label}</span>
      </div>
      <div style="font-size:12px;color:var(--color-neutral-600);margin:3px 0 0 18px;line-height:1.45">${esc(s.words)}</div>
    </div>`;
  };
  return `<div id="share-journey" style="border:1px solid ${j.stale?'var(--st-amber-line)':'var(--color-divider)'};background:${j.stale?'var(--st-amber-bg)':'var(--color-bg)'};border-radius:0;padding:11px 13px;margin-bottom:12px">
    <div style="display:flex;gap:10px;flex-wrap:wrap">${j.stages.map(cell).join('')}</div>
    <div style="display:flex;align-items:center;gap:9px;margin-top:9px;padding-top:8px;border-top:1px dashed var(--color-divider)">
      <span style="flex:1;font-size:13px;line-height:1.5;font-weight:${(j.responded&&!j.signed)?'600':'500'};color:${j.signed?'var(--st-green-fg)':(j.responded||j.stale)?'var(--st-amber-fg)':'var(--color-neutral-700)'}">${esc(j.sentence)}</span>
      ${(j.stale&&typeof canEdit==='function'&&canEdit())?`<button id="seen-resend" class="ui-btn" style="flex:none;font-size:12px;padding:5px 11px">${i18t('co_send_again')}</button>`:''}
    </div>
  </div>`;
}

/* ---- Shares panel (workspace): every dispatch for this contract with its
   traffic light, timestamps and per-share actions (copy / resend / revoke). */
/* The shares this workspace has already fetched, by contract id. The Negotiation
   tab's status strip needs the same "have they opened it?" answer this section
   already asked the server for, and asking twice would be two round trips for
   one fact — and two chances for the two strips to disagree. */
const _shareCache=new Map();
const cachedShares = c => _shareCache.get(c&&c.id)||[];
/* ---- "NOTHING" AND "NOT ASKED YET" ARE DIFFERENT ANSWERS (13 Aug 2026) ----
   cachedShares returns [] for both, which is fine for drawing a panel and
   wrong for making a CLAIM. negoTheirCopy asks whether the counterparty holds
   a link that is still live before the product says the deal is waiting on
   them, and an empty cache that has simply never been filled must read as "we
   do not know" rather than as "they have nothing". See negWhoseMove. */
const sharesKnown = c => !!(c && c.id && _shareCache.has(c.id));
/* Fill it once per sitting, for callers that are not the shares panel. Same
   shape as renderRedline's one-per-sitting message fetch: fire and forget, the
   page paints immediately, and the caller repaints if the answer changes what
   it drew. Never in local mode — there are no links there to be standing. */
const _shareFetching=new Set();
function ensureSharesCached(c){
  if(!c||!c.id) return Promise.resolve([]);
  if(!API_MODE()) return Promise.resolve([]);
  if(_shareCache.has(c.id)) return Promise.resolve(cachedShares(c));
  if(_shareFetching.has(c.id)) return Promise.resolve([]);
  _shareFetching.add(c.id);
  return contractShares(c).then(list=>{ _shareCache.set(c.id, list||[]);
    _shareFetching.delete(c.id); return list||[]; })
    .catch(()=>{ _shareFetching.delete(c.id); return []; });
}
/* ---- AND THE INTERNAL HALF OF THE SAME ANSWER ----
   A counterparty signer's progress is a fact about their SHARE; an internal
   signer has none, so "have they been told it is their turn" is recorded
   separately by the server and rides back on this same fetch. One cache, one
   round trip, and no way for the two halves of the signing card to disagree
   because they asked at different moments — the reason _shareCache exists at
   all. Read by signerNoticeState in js/approvals.js. */
const _noticeCache=new Map();
const cachedSignerNotices = c => _noticeCache.get(c&&c.id)||[];
async function renderSharesSection(c){
  const host=document.getElementById('shares-section'); if(!host) return;
  if(!API_MODE()){ host.innerHTML=''; return; }
  let shares=[], notices=[];
  try{ const r=await api('contracts/'+c.id+'/shares'); shares=r.shares||[]; notices=r.signerNotices||[]; }
  catch(e){ host.innerHTML=''; return; }
  _shareCache.set(c.id, shares);
  _noticeCache.set(c.id, notices);
  /* The Signature-progress rows read this cache (signerLinkState) to say
     whether each signer's link is unsent / sent / opened. The sign area
     painted BEFORE this fetch answered, so repaint it now the truth is in —
     otherwise the panel keeps route-order guesses until the next full render. */
  try{ if((c.signerPlan||[]).length && typeof renderSignButton==='function') renderSignButton(c); }catch(_){}
  if(!shares.length){ host.innerHTML=''; return; }
  const esc=s=>String(s==null?'':s).replace(/[&<>]/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[x]));
  const chLabel={email:'Email',whatsapp:'WhatsApp',link:'Link'};
  const live=s=>s.state==='sent'||s.state==='opened';
  host.innerHTML=`<div class="px-5 py-4">
    ${''/* WO N4: the four-light journey replaced the single seen-state
         sentence here; counterpartySeenState still answers for the
         negotiation strip, and the chase button keeps its id so the
         wiring below holds. */}
    ${shareJourneyHtml(c, shares)}
    <div class="flex items-center gap-2 mb-3"><span class="text-brand-500">${icon('send')}</span>
      <h3 class="text-sm font-display font-600 text-brand-900">${i18t('co_shares')}</h3>
      <span class="ml-auto text-[10px] font-mono text-brand-800/60">${shares.length} sent</span></div>
    <div class="space-y-2">
      ${shares.map(s=>{
        const who=esc(s.recipientName||s.recipientEmail||s.recipientPhone||'Open link');
        const meta=[`sent ${fmtDT(s.sentAt||s.createdAt)}`,
          s.firstOpenedAt?`opened ${fmtDT(s.firstOpenedAt)}`:null,
          s.respondedAt?`responded ${fmtDT(s.respondedAt)}`:null,
          (!s.respondedAt&&!s.revokedAt&&s.expiresAt)?`expires ${String(s.expiresAt).slice(0,10)}`:null].filter(Boolean).join(' · ');
        return `<div style="border:1px solid var(--color-divider);border-radius:0;padding:8px 10px;background:var(--color-bg)">
          <div style="display:flex;align-items:center;gap:8px;min-width:0">
            ${shareChip(s.state)}
            <span style="flex:1;min-width:0;font-size:13px;font-weight:400;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${who}">${who}</span>
            <span style="font-size:12px;color:var(--color-neutral-500);font-family:var(--font-mono);flex:none">${chLabel[s.channel]||'Link'}</span>
          </div>
          ${s.responseBy?`<div style="font-size:12px;color:var(--color-neutral-700);margin-top:3px">by ${esc(s.responseBy)}</div>`:''}
          <div style="font-size:12px;color:var(--color-neutral-600);font-family:var(--font-mono);margin-top:3px">${meta}</div>
          ${(live(s)&&canEdit())?`<div style="display:flex;gap:10px;margin-top:5px">
            <button data-sh-copy="${s.token}" style="border:0;background:none;padding:0;font:inherit;font-size:12px;font-weight:600;color:var(--color-accent-700);cursor:pointer">${i18t('co_copy_link')}</button>
            ${s.channel==='email'?`<button data-sh-resend="${s.token}" style="border:0;background:none;padding:0;font:inherit;font-size:12px;font-weight:600;color:var(--color-accent-700);cursor:pointer">${i18t('co_resend')}</button>`:''}
            <button data-sh-revoke="${s.token}" style="border:0;background:none;padding:0;font:inherit;font-size:12px;font-weight:600;color:var(--st-ruby-dot);cursor:pointer">${i18t('co_revoke')}</button>
          </div>`:''}
        </div>`; }).join('')}
    </div></div>`;
  document.getElementById('seen-resend')?.addEventListener('click',async e=>{
    const btn=e.currentTarget, restore=btn.innerHTML;
    btn.disabled=true; btn.innerHTML=`<span class="animate-pulse">${i18t('co_sending')}</span>`;
    try{
      const out=await reshareToLastRecipient(c);
      const who=out.recipient.name||out.recipient.email||out.recipient.phone||'the counterparty';
      /* Their copy could not be reused — see the other caller; same order. */
      if(out.stranded) toast(reshareStrandedLine(who),'err');
      else if(out.delivered) toast(`Sent again to ${who}`);
      /* Deliberately quiet, not refused — see the note on the other caller. */
      else if(out.quiet) toast(i18t('co_round_on_standing_link',{who:esc(who)}));
      else reshareNotSentModal(c, out, who);
      renderAuditSection(c); renderSharesSection(c);
    }catch(err){ toast(err.message,'err'); }
    btn.disabled=false; btn.innerHTML=restore;
  });
  host.querySelectorAll('[data-sh-copy]').forEach(b=>b.addEventListener('click',async()=>{
    const link=location.origin+location.pathname+'#share=t:'+b.getAttribute('data-sh-copy');
    try{ await navigator.clipboard.writeText(link); }catch(e){}
    toast(i18t('co_share_copied'));
  }));
  host.querySelectorAll('[data-sh-resend]').forEach(b=>b.addEventListener('click',async()=>{
    try{ const r=await api('shares/'+b.getAttribute('data-sh-resend')+'/resend','POST',{});
      toast(r.emailSent?'Reminder email sent':'Reminder queued to the outbox'); renderSharesSection(c);
    }catch(e){ toast(e.message,'err'); }
  }));
  host.querySelectorAll('[data-sh-revoke]').forEach(b=>b.addEventListener('click',async()=>{
    if(!await confirmDialog({get title(){ return i18t('co_revoke_share_q'); }, message:'The recipient will no longer be able to open the contract from this link. You can share again at any time.', confirmLabel:'Revoke link', danger:true})) return;
    try{ await api('shares/'+b.getAttribute('data-sh-revoke')+'/revoke','POST',{});
      logAudit(c,'Share revoked','A counterparty share link was revoked'); persist(c); renderAuditSection(c);
      toast(i18t('co_share_revoked')); renderSharesSection(c); refreshShareOverview();
    }catch(e){ toast(e.message,'err'); }
  }));
}

/* ---- Portfolio-wide dispatch overview: feeds the register/folder dots and
   the dashboard "Out with counterparties" strip. Refreshed on load + poll. */
async function refreshShareOverview(){
  if(!API_MODE()) return;
  try{
    const r=await api('shares/overview');
    /* Repaint only when the answer moved. This runs on a minute timer, and an
       unconditional renderDashboard() rebuilt the whole Home screen twice a
       minute for a reader who was just looking at it — the same steady data,
       redrawn as a visible blink. Same rule as pollThreadMessages. */
    const j=JSON.stringify(r), changed=j!==state._shareOverviewJson;
    state._shareOverviewJson=j;
    state.shareOverview=r; state.shareByContract=r.byContract||{};
    if(changed && state.view==='dashboard') renderDashboard();
  }catch(e){ /* transient — next refresh retries */ }
}

/* Questions the counterparty asked that nobody has answered. Loaded beside the
   share overview because it answers the same question the dashboard exists to
   answer — what is waiting on me? — and because a channel nobody watches is
   slower than the formal round it replaced. */
async function refreshWaitingQuestions(){
  if(!API_MODE()) return;
  try{
    const r=await api('messages/waiting');
    /* Same discipline as refreshShareOverview: a minute-timer refresh earns a
       repaint only by bringing something new. */
    const j=JSON.stringify(r), changed=j!==state._waitingQuestionsJson;
    state._waitingQuestionsJson=j;
    state.waitingQuestions=r;
    if(changed && state.view==='dashboard') renderDashboard();
  }catch(e){ /* transient — next refresh retries */ }
}

function openImportModal(c){
  openModal(`
    <div style="padding:22px 24px;">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;"><span style="display:inline-flex;color:var(--color-accent);">${icon('upload')}</span>
        <h2 style="font-family:var(--font-heading);font-weight:600;font-size:18px;color:var(--color-text);margin:0;">${i18t('co_import_cp_response')}</h2></div>
      <p style="font-size:13px;color:var(--color-neutral-700);margin:0 0 12px;line-height:1.55;">${i18t('co_paste_response_code')}</p>
      <textarea id="imp-code" rows="5" placeholder="${i18t('co_paste_response')}" style="width:100%;border:1px solid var(--color-divider);background:var(--color-bg);border-radius:0;padding:11px;font-size:12px;font-family:var(--font-mono);color:var(--color-text);outline:none;"></textarea>
      <div style="margin-top:14px;display:flex;align-items:center;gap:8px;justify-content:flex-end;">
        <button id="imp-cancel" class="ui-btn">${i18t('act_cancel')}</button>
        <button id="imp-go" class="ui-btn ui-btn-primary">${i18t('co_import')}</button>
      </div>
      <div style="margin-top:16px;padding-top:14px;border-top:1px solid var(--color-divider);">
        ${''/* HALF A SENTENCE IN EACH LANGUAGE, until 13 Aug 2026: the opening
               was translated and everything after it was hardcoded English, so
               a Swedish reader read "Eller ladda upp den markerade Word-filen
               they sent back. Their tracked changes are…". The tail is
               co_upload_word_tail now and reads on from the bold opening. */}
        <p style="font-size:13px;color:var(--color-neutral-700);margin:0 0 8px;line-height:1.55;"><b>${i18t('co_or_upload_word')}</b> ${i18t('co_upload_word_tail')}</p>
        <input id="imp-docx" type="file" accept=".docx" style="width:100%;font-size:13px;color:var(--color-text);"/>
        <div id="imp-docx-note" style="margin-top:7px;font-size:12px;color:var(--color-neutral-600);"></div>
      </div>
    </div>`);
  document.getElementById('imp-cancel').addEventListener('click',closeModal);
  document.getElementById('imp-go').addEventListener('click',async()=>{
    const ok=await applyResponse(c, b64d(fval('imp-code')));
    if(ok) closeModal();
  });
  document.getElementById('imp-docx')?.addEventListener('change',async ev=>{
    const f=ev.target.files&&ev.target.files[0]; if(!f) return;
    const note=document.getElementById('imp-docx-note');
    if(!/\.docx$/i.test(f.name||'')){ if(note) note.textContent=i18t('co_import_not_docx'); ev.target.value=''; return; }
    if(note) note.textContent=i18t('co_import_reading',{name:f.name});
    try{
      await ensureFull(c);
      if((c.execution&&c.execution.at)||isExternallyExecuted(c)) throw new Error(i18t('co_import_executed',{id:c.id}));
      const bytes=new Uint8Array(await f.arrayBuffer());
      if(!window.negoImportReturnedDocx) throw new Error('The Word reader is not loaded on this page');
      const res=await negoImportReturnedDocx(c, bytes, {});
      /* The comments are the COUNTERPARTY's words, imported by the editor
         holding their file — they land on the counterparty's side under the
         commenter's own name, tagged with the channel they came by. */
      let attached=0;
      for(const cm of res.comments){
        const author=(cm.author||c.counterparty||'Counterparty')+' · via Word comment';
        if(API_MODE()){
          try{
            const r=await api('contracts/'+c.id+'/messages','POST',{ topic:cm.topic,
              topicLabel:cm.topicLabel, body:cm.text, viaWordComment:true,
              author:cm.author||c.counterparty||'Counterparty' });
            c._messages=(r&&r.messages)||c._messages; attached++;
          }catch(_){ /* counted below by what actually landed */ }
        }else{
          c._messages=c._messages||[];
          c._messages.push({ id:'wc'+Date.now()+'_'+attached, side:'counterparty', author,
            topic:cm.topic, topicLabel:cm.topicLabel, body:cm.text, at:new Date().toISOString() });
          attached++;
        }
      }
      logAudit(c,'Negotiation',`Returned Word file ${f.name} read — ${res.filed.length} change${res.filed.length===1?'':'s'} filed`+(attached?`, ${attached} margin comment${attached===1?'':'s'} attached to the discussion`:''));
      persist(c);
      closeModal();
      toast(res.filed.length||attached
        ? i18tn('co_import_filed', res.filed.length, { name:f.name, n:res.filed.length })
          + (attached ? i18tn('co_import_comments', attached, { n:attached }) : '')
        : i18t('co_import_nothing',{name:f.name}));
      if(state.view==='workspace'&&window.renderWorkspace) renderWorkspace();
      else if(state.view==='redline'&&window.renderRedline) renderRedline();
    }catch(e){
      if(note) note.textContent=i18t('co_import_unreadable',{err:(e&&e.message)||e});
      ev.target.value='';
    }
  });
}
async function applyResponse(c, r, opts={}){
  if(!r || r.kind!=='hati-response'){ if(!opts.background) toast(i18t('co_invalid_response_code'),'err'); return false; }
  /* 'err', not a bare call — a bare call is SILENT by this product's own rule
     (see toast), so this refusal has been invisible since the day the three
     kinds landed. It cannot fire from the poller, which looks the contract up
     by this very id; it fires on the paste-a-code path, where the reader has
     just handed us the wrong code and is owed the sentence. */
  if(r.id!==c.id){ toast(`This response is for ${r.id}, not ${c.id}`,'err'); return false; }
  // The caller may hand us a LIGHT register row — the list endpoint strips
  // audit, comments, execution.html and the upload's text off every row. This
  // function appends to the record and persists the whole object, so acting on
  // a light row would write those absences back over the full record and
  // destroy the audit trail at the exact moment a counterparty responds.
  try{ await ensureFull(c); }catch(e){
    toast(i18t('co_could_not_load_full'),'err');
    return false;
  }
  // An agreement that is already executed is not a thing a share link may
  // re-open. A stale or replayed link must not be able to flip a signed
  // contract to Declined or bolt another signature onto a sealed record.
  if((c.execution && c.execution.at) || isExternallyExecuted(c)){
    if(!opts.background) toast(`${c.id} is already executed — a share response cannot change it. Record an amendment instead.`,'err');
    return false;
  }
  const currentHash=await sha256(canonicalDoc(c));
  const docChanged = r.docHash && r.docHash!==currentHash && r.docHash!==c.hash;
  /* C-3: a BINDING response — a signature, or an acceptance of the wording, or
     a "ready to sign" — against a copy that no longer matches the live document
     must NOT be applied. Sealing it would bind the counterparty to text they
     never saw and the seal would still verify as "valid", because it would be
     consistent with the edited wording. So the binding action is refused, the
     owner is told plainly, and the remedy (reshare the current copy) is named.
     Non-binding responses (a redline or a decline) keep the informational note
     and proceed, because they change nothing the counterparty is bound by.
     Refused the same way an out-of-order signature is refused above: return
     false so nothing is written and the response stays visible as pending. */
  if(docChanged && (r.action==='sign' || r.action==='accept' || r.action==='ready')){
    if(!opts.background) toast(`${r.name||'The counterparty'} responded to an earlier copy of ${c.id} — the wording changed after their link was sent, so their ${r.action==='sign'?'signature':'response'} was NOT applied. Reshare the current version so they respond to the document you actually have.`,'err');
    return false;
  }
  if(docChanged)
    toast(i18t('co_doc_changed_after'),'err');
  const who=r.name+(r.title?', '+r.title:'');
  /* Values the counterparty filled into a template form. Only known open
     fields land (never fixed wording, never invented keys), each re-checked
     against the shared registry, and the wording regenerates so both screens
     read the same document. Runs before the signature block below so what is
     signed is the filled form the signer was looking at. */
  if(r.templateValues && c.templateForm && window.fieldLibValidate){
    c.templateForm.values=c.templateForm.values||{};
    for(const [k,v] of Object.entries(r.templateValues)){
      const f=(c.templateForm.fields||[]).find(x=>x.fieldKey===k);
      if(!f||f.fieldType==='signature_name_title') continue;
      const s=v==null?'':String(v).trim();
      if(!s){ continue; }
      if(fieldLibValidate({label:f.label,field_key:f.fieldKey,field_type:f.fieldType,
        control:f.control,options:f.options,required:f.required}, s)) continue;
      c.templateForm.values[k]=s;
    }
    if(window.templateFormDocHtml) c.redlineText=templateFormDocHtml(c.templateForm);
  }
  if(r.action==='sign'){
    /* ---- W7 fault 3: A SIGNATURE LANDS ON ITS BOUND ROW, OR ON NONE ----
       This used to stamp whichever counterparty row was NEXT — nextSigner() —
       so when links were out with their MD (order 3) and their FD (order 4)
       and the FD signed first, the signature landed on the MD's row. The real
       name went into `by`, so the trail was not false, but the official
       running order was silently wrong from then on.

       A response from a bound link now carries the row it belongs to
       (r.signerId — stamped by the SERVER from the share record, never
       claimed by the page). It is checked BEFORE anything is written, because
       a refusal that has already pushed the signature is a misfile with extra
       steps. Out of order is refused here as well as at the server: this
       function is also the import door for static-mode response codes, which
       never pass through the respond route. A background refusal is safe —
       the poller retries, and succeeds once the earlier signature it is
       waiting on has been applied. */
    let boundRow=null, routeNote='';
    if(r.signerId && window.signerPlan && signerPlan(c).length){
      boundRow=signerPlan(c).find(x=>x && String(x.id)===String(r.signerId))||null;
      if(boundRow){
        if(boundRow.signed){
          if(!opts.background) toast(`${boundRow.name}'s signing step is already recorded — this signature was not applied again`,'err');
          return false;
        }
        const earlier=signerPlan(c).filter(x=>x && (x.order||0)<(boundRow.order||0) && !x.signed)
          .sort((a,b)=>(a.order||0)-(b.order||0));
        if(earlier.length){
          if(!opts.background) toast(`${r.name} signed out of order — ${earlier[0].name} signs first. Refused rather than filed on the wrong step.`,'err');
          return false;
        }
      } else {
        /* The route was edited and the bound row is gone. The signature is
           real evidence and is kept; what must not happen is guessing it onto
           somebody else's step. Recorded with the gap named, so the trail says
           exactly what is and is not claimed. */
        routeNote=' — NOTE: the signing-route step this link was bound to no longer exists on the route; the signature is recorded, and no step was marked signed';
      }
    }
    c.signatures=c.signatures||[];
    const sig={ form:r.signatureForm||null, image:r.signatureImage||null, imageHash:r.signatureImageHash||null,
      typedName:r.signatureTypedName||null, font:r.signatureFont||null };
    c.signatures.push({ party:'counterparty', name:r.name, title:r.title||'', email:r.email||'', at:r.at,
      method:r.method||'share-link', verified:r.verified!==false, ip:r.ip||null, ua:r.ua||null, docHash:r.docHash,
      /* W3-3: which rung this was taken at, stamped as the response is
         applied. `verify` is the one-time code they proved against the
         invited address — the difference between "somebody typed a name"
         and "the person we wrote to answered". */
      assurance:(typeof assuranceAtSigning==='function')
        ? assuranceAtSigning({ method:r.method||'share-link', verify:r.verify||(r.verified!==false&&r.verifyToken)||null }) : undefined,
      form:sig.form, image:sig.image, imageHash:sig.imageHash, typedName:sig.typedName, font:sig.font });
    if(boundRow){
      boundRow.signed=true; boundRow.at=r.at; boundRow.by=r.name; boundRow.signature=sig;
    } else if(!r.signerId){
      /* The unbound path: a pre-W7 link, or a static-mode response code —
         neither carries a binding, and next-in-order is all there is to go
         on. Bound links never come through here. */
      const ns=window.nextSigner?nextSigner(c):null;
      if(ns && ns.party==='counterparty'){ ns.signed=true; ns.at=r.at; ns.by=r.name; ns.signature=sig; }
    }
    c.comments.push({ author:r.name, role:'Counterparty — Signed', side:'external', text:r.comment||'Approved and signed via secure share link.', at:r.at, ts:fmtDT(r.at) });
    // r.verified===false means the server could not send a code, so nothing
    // checked that this signer holds that address. The trail says so rather
    // than reading like every other verified counterparty signature.
    const unverified = r.verified===false;
    logAudit(c,'Countersigned',`${who} signed via share link (${r.method||'share-link'}${sig.form?', '+sig.form+' signature':''})${boundRow?` — step ${boundRow.order} of the signing route, on their own bound link`:''}${signerProvenance(r.ip,r.ua)}${unverified?' — NOT independently verified: this workspace cannot send verification codes':''}${routeNote}`);
    toast(`${r.name} has signed — countersignature recorded`);
    // Last signature on a route ⇒ freeze, seal and distribute automatically.
    const routeDone = window.allSigned && allSigned(c);
    /* THE SAME MOMENT, REACHED WITHOUT A ROUTE. A contract with no signing
       plan can still arrive here holding both parties' marks — ours recorded
       outside the single-signer path (a migration, an off-platform mark), and
       theirs landing now through the share link. Leaving it unsealed meant a
       fully signed contract that never froze, never fingerprinted and never
       sent anybody their copy. The route check stays first and stricter: while
       a plan exists, only its completion seals. */
    const bothDone = (!window.signerPlan || !signerPlan(c).length)
      && window.bothPartiesSigned && bothPartiesSigned(c);
    if((routeDone || bothDone) && c.status!=='Signed' && window.finalizeExecution){
      c.lastAction=todayStr(); persist(c);
      await finalizeExecution(c, { silent:!!opts.background });
      return true;
    }
    /* THE SEAL CAME FIRST, THE LAST SIGNATURE SECOND. In the single-signer
       flow the owner's own signature seals immediately — status 'Signed',
       document frozen — and the counterparty's mark lands HERE afterwards,
       on an already-sealed record. finalizeExecution will not run again
       (there is nothing left to seal), and it was the only caller of
       distributeExecuted — so the copy the design promises "when the last
       signature lands" never went out. This is that moment, caught. A
       part-signed progress notice sent earlier does not count as the copy
       (distribution.fully records which kind went); it is cleared and the
       real executed copy goes now. */
    if(c.status==='Signed' && window.bothPartiesSigned && bothPartiesSigned(c)
       && window.distributeExecuted && (!c.distribution || c.distribution.fully!==true)){
      if(c.distribution) delete c.distribution;
      try{ await distributeExecuted(c); }
      catch(e){ console.warn('executed-copy distribution failed: '+(e&&e.message)); }
    }
  } else if(r.action==='accept'){
    /* Agreement to the wording, which is not execution. The contract keeps its
       status and its seal stays unwritten; what changes is that the other side
       has said yes to this text on the record, so the next step is signature
       rather than another round of drafting. */
    c.acceptance={ by:who, at:r.at, email:r.email||null, comment:r.comment||'' };
    c.comments.push({ author:r.name, role:'Counterparty — Wording accepted', side:'external',
      text:r.comment||'Accepted the current wording. Not yet signed.', at:r.at, ts:fmtDT(r.at) });
    logAudit(c,'Wording accepted',`${who} accepted the current wording without signing`);
    toast(`${r.name} accepted the wording — ready for signature`);
  } else if(r.action==='decisions'){
    /* Answers to individual fingerprinted changes we proposed. Applied through
       negoResolve, so the wording is rebuilt from the accepted set by the same
       code the owner's own decisions run through — there is no second path into
       the document, and therefore no second set of rules about what enters it.

       A decision only ever lands on a change WE proposed. Their own asks are
       not theirs to rule on: that would let one side mark its own wording
       adopted and tell the other it was agreed. */
    const done=applyNegoDecisions(c, r, who);
    /* AND WORDING OF THEIR OWN. A response on a negotiation link carries both:
       answers to our asks, and asks of theirs. Only decisions used to arrive,
       so the room's Change button on their side filed a change that could never
       leave their browser — see PORTAL_NEGO_PROPOSED. */
    const filed=await applyNegoProposals(c, r, who);
    /* AND WITHDRAWALS. This branch used to ignore them — only the readiness
       branch read negoWithdrawn — so a counterparty who took a refused ask off
       the table and pressed Send rather than Ready had the withdrawal dropped
       in silence. Their screen said the point was settled; ours went on
       reporting a live disagreement, and neither side could see why the deal
       would not move. */
    const withdrew=applyNegoWithdrawals(c, r, who);
    if(!done.length && !filed.length && !withdrew.length){
      if(!opts.background) toast(i18t('co_no_decisions'),'err');
      /* WORDING THAT CANNOT LAND MUST STILL STOP ARRIVING. Reported unhandled,
         the poller re-fetches this same response every cycle and re-applies
         nothing, for ever — which is precisely how a counterparty's redline came
         to disappear with no error on either screen (f163). So a response whose
         whole content was PROPOSED WORDING none of which could be placed is
         reported handled: applyNegoProposals has just written their exact words
         into the trail, and the owner is told once here.

         Only wording. A refused DECISION — ruling on their own ask, or naming a
         fingerprint this contract has never had — stays unhandled and unapplied,
         because that is a refusal rather than a delivery, and f37 pins it. */
      const proposed=Array.isArray(r.negoProposed)?r.negoProposed.length:0;
      const decided=Array.isArray(r.negoDecisions)?r.negoDecisions.length:0;
      const withdrawn=Array.isArray(r.negoWithdrawn)?r.negoWithdrawn.length:0;
      if(!proposed || decided || withdrawn) return false;
      c.lastAction=todayStr(); persist(c);
      toast(`${r.name||'The counterparty'} sent wording that does not match any clause on ${c.id} — nothing was filed. Their exact words are in this contract's history.`,'err');
      return true;
    }
    const acc=done.filter(x=>x.status==='accepted').length;
    const said=[done.length?`${acc} of ${done.length} proposed changes accepted (${done.map(x=>'#'+x.id).join(', ')})`:'',
      filed.length?`${filed.length} change${filed.length===1?'':'s'} proposed (${filed.map(x=>'#'+x).join(', ')})`:'',
      withdrew.length?`${withdrew.length} ask${withdrew.length===1?'':'s'} withdrawn (${withdrew.map(x=>'#'+x).join(', ')})`:'']
      .filter(Boolean).join('; ');
    c.comments.push({ author:r.name, role:'Counterparty — Negotiation round', side:'external',
      text:r.comment||(said+'.'), at:r.at, ts:fmtDT(r.at) });
    if(done.length) logAudit(c,'Negotiation',`${who} decided ${done.length} proposed change${done.length===1?'':'s'} — ${acc} accepted, ${done.length-acc} rejected (${done.map(x=>'#'+x.id+' '+x.status).join(', ')})`);
    negoTurnBack(c, who);
    toast(said?`${r.name}: ${said}`:`${r.name} answered`);
  } else if(r.action==='ready'){
    /* ONE PRESS, ONE CALL. "Ready to sign" carries whatever decisions were
       still held on their page AND the readiness signal, in a single response.

       It used to take two: decide the changes, press Send, then separately say
       you were done. Forgetting the first lost the round — the owner received a
       readiness signal about a change set that had not moved, and the reader
       had no way to tell their answers had never left their browser. The two
       facts arrive together or not at all.

       Order matters: the decisions are applied FIRST, so the alignment the
       signal is checked against is the one their decisions produce, not the one
       the contract had before they answered. */
    const done=applyNegoDecisions(c, r, who);
    /* Wording of their own, arriving with the readiness signal. Filed BEFORE
       the signal is checked, for the same reason the decisions are: the
       alignment the claim is tested against has to be the one their whole
       response produces. A reader who asks for a change and presses Ready in
       one breath is not aligned, and the contract must be able to see that. */
    await applyNegoProposals(c, r, who);
    /* Also arriving in the same call: asks THEY made that we refused and they
       have now let go. Without this a counterparty could never clear their own
       side of a deadlock from their link. Only their OWN asks — withdrawing
       ours would let one side clear every objection raised against its wording
       and then declare the deal aligned. */
    const withdrew=applyNegoWithdrawals(c, r, who);
    const sig=window.negoSignalReady
      ? negoSignalReady(c, { side:'counterparty', by:who, at:r.at, email:r.email||null })
      : null;
    if(!sig){
      /* The gate is enforced on BOTH sides of the wire. Their page disables the
         button until the parties are aligned, but a response is a public POST
         and the page that sent it is not ours — so the contract checks the
         claim against its own change set rather than believing it.

         What arrived WITH the claim is still true and is kept: their decisions
         are answers to our asks and their withdrawals are theirs to make. Only
         the readiness is refused, and the trail says so — silently dropping the
         whole response would lose real answers over a claim about them.

         Reporting handled (rather than failed) whenever something landed
         matters for the poller: an unhandled response is re-fetched and
         re-applied every cycle, so a claim that can never succeed would be
         retried forever. It is recorded once, as a fact, and the deal moves on
         the way it always does — by somebody settling what is outstanding. */
      logAudit(c,'Negotiation',`${who} signalled ready to sign, but this contract is not settled`
        +` — ${negoAlignmentWhy(c,'counterparty')||'something is still outstanding'}.`
        +` The readiness was not recorded${done.length||withdrew.length
          ? `; the ${done.length?`${done.length} decision${done.length===1?'':'s'}`:''}`
            +`${done.length&&withdrew.length?' and ':''}`
            +`${withdrew.length?`${withdrew.length} withdrawal${withdrew.length===1?'':'s'}`:''}`
            +` sent with it ${(done.length+withdrew.length)===1?'was':'were'} applied`
          : ''}.`);
      if(!opts.background) toast(i18t('co_readiness_mismatch'),'err');
      c.lastAction=todayStr(); persist(c);
      if(opts.background) setView(state.view||'dashboard'); else renderWorkspace();
      return !!(done.length||withdrew.length);
    }
    const acc=done.filter(x=>x.status==='accepted').length;
    const parts=[];
    if(done.length) parts.push(`${done.length} change${done.length===1?'':'s'} answered (${acc} accepted)`);
    if(withdrew.length) parts.push(`${withdrew.length} of their own ask${withdrew.length===1?'':'s'} withdrawn`);
    c.comments.push({ author:r.name, role:'Counterparty — Ready to sign', side:'external',
      text:r.comment||`Everything is settled from our side${parts.length?` — ${parts.join(', ')}`:''}. Ready to sign.`,
      at:r.at, ts:fmtDT(r.at) });
    negoTurnBack(c, who);
    logAudit(c,'Ready to sign',`${who} signalled ready to sign via the negotiation link`
      +`${parts.length?` — ${parts.join('; ')}`:''}. Nothing is signed: issue a signing link to take it forward.`);
    toast(`${r.name} is ready to sign — issue a signing link`);
  } else if(r.action==='changes'){
    c.comments.push({ author:r.name, role:'Counterparty — Changes requested', side:'external', text:r.comment, at:r.at, ts:fmtDT(r.at) });
    c.rounds=c.rounds||[];
    // E2: a change request may carry proposed edited text (a redline). Capture
    // the base text it was edited from so the owner can review a clean diff.
    const hasRedline = typeof r.proposedText==='string' && r.proposedText.trim().length>0;
    c.rounds.push({ n:c.rounds.length+1, at:r.at, by:who, comment:r.comment,
      proposedValue:Number.isFinite(Number(r.proposedValue))&&r.proposedValue!==''&&r.proposedValue!=null?Number(r.proposedValue):null,  // M-4: store only a real number, never NaN
      proposedText: hasRedline ? r.proposedText : null,
      baseText: hasRedline ? (r.baseText || docPlainText(c)) : null,
      // a reason per clause, when they gave one — matched to the individual
      // changes on the review screen rather than read as one lump
      clauseNotes: Array.isArray(r.clauseNotes)&&r.clauseNotes.length ? r.clauseNotes.slice(0,60) : null,
      status:'open', resolution:null });
    logAudit(c,'Changes requested',`${who} requested changes${hasRedline?' with proposed edits (redline)':''}${r.proposedValue?` (proposed value ${fmtMoney(r.proposedValue)})`:''}`);
    /* The same redline, ALSO filed as fingerprinted changes so it can be worked
       clause by clause in the Negotiation tab. The round record above is
       untouched and still carries the whole-document pair — every existing
       review path, test and export reads exactly what it read before, and this
       is additive rather than a replacement. Where the two disagree the round is
       the wire format and the changes are the working set. */
    if(hasRedline && window.negoFileProposal){
      try{
        const base=r.baseText||docPlainText(c);
        negoInit(c);
        if(!(c.negotiation.baselineText||'').trim()) c.negotiation.baselineText=base;
        /* Keyed on the WORDING they annotated, not on a clause id. The
           counterparty's reply is composed against a text projection and
           carries no clause ids at all, so the note is matched to the change by
           the words it was written about — which is the only thing the two
           records actually share. */
        const notes={};
        for(const n of (Array.isArray(r.clauseNotes)?r.clauseNotes:[])){
          const key=String(n.after||'').replace(/\s+/g,' ').trim();
          if(key&&n.note) notes[key]=String(n.note).slice(0,600);
        }
        await negoFileProposal(c, r.proposedText, { side:'counterparty', author:who,
          baseText:base, roundN:c.rounds.length, notes, via:'the counterparty’s link' });
      }catch(e){ /* the round is filed either way — the fingerprints are the bonus, not the record */ }
    }
    toast(`${r.name} requested changes — review in Negotiation`);
  } else if(r.action==='decline'){
    c.status='Declined';
    c.comments.push({ author:r.name, role:'Counterparty — Declined', side:'external', text:r.comment, at:r.at, ts:fmtDT(r.at) });
    logAudit(c,'Declined',`${who} declined via share link`);
    toast(`${r.name} declined the agreement`,'err');
  } else { if(!opts.background) toast(i18t('co_unknown_response'),'err'); return false; }
  c.lastAction=todayStr(); persist(c);
  /* WRITTEN BEFORE ANYTHING REPAINTS, and this is not a nicety.

     `persist` only marks the contract dirty and sets a 400 ms timer. The
     repaint below reloads the contract into the same object — so on the
     background path the sequence was: apply the counterparty's answers, mark
     dirty, repaint, let the reload assign the SERVER's older copy over the
     answers, and then let the timer save that older copy back. Every decision,
     withdrawal and audit line in the response vanished, with no error anywhere:
     the response was marked applied on the server, so it was never re-delivered
     either. A counterparty accepted a clause, their screen said sent, and the
     owner's contract never heard of it.

     Draining the queue here makes the write happen while the object still holds
     what arrived. */
  try{ await flushSaves(); }catch(_){}
  if(opts.background) setView(state.view||'dashboard'); else renderWorkspace();
  /* THE ROOM IS A LAYER OVER THE PAGE, and the repaint above rebuilds the page
     UNDER it. So an owner sitting in the negotiation watched a change stay
     "pending" after the counterparty had accepted it and we had applied the
     acceptance: the record was right, the screen they were reading was not, and
     nothing on it said so. Leaving and coming back fixed it, which is the worst
     kind of fix — the one only somebody who already suspects a problem finds. */
  if(window.negoRepaintOpenRoom) negoRepaintOpenRoom(c);
  /* AND THEIR LINK IS A PHOTOCOPY. It serves the payload taken when the link
     was made; nothing updated it when their own answers were applied. So the
     counterparty answered, sent, and reloaded — and their page replayed the
     negotiation as it stood before they touched it: decision needed, Accept and
     Reject, on a change they had already answered.

     Caught up quietly: no email, no "sent" mark, no reset of whether they have
     opened the current wording. Telling them stays a deliberate act. */
  refreshLiveShareQuietly(c);
  return true;
}

/* Bring the counterparty's live link up to date with the record, silently.
   Fire-and-forget by design: it is a correction to a copy, and a contract that
   has just been updated must not fail because a link could not be refreshed. */
async function refreshLiveShareQuietly(c){
  if(!API_MODE() || !canEdit()) return;
  try{
    const shares=await contractShares(c);
    /* THE SAME PREDICATE THE ROUND SEND ASKS — see shareIsStanding. This used
       to filter on `s.expired`, a field the shares list does not send, so an
       expired link was fetched, PUT and refused every time. Harmless, and it
       hid the fact that these two callers were reading the same record by two
       different rules. */
    const live=standingShares(shares);
    if(!live.length) return;
    const docHash=await sha256(canonicalDoc(c));
    for(const s of live){
      /* The purpose the link was issued with is kept. A negotiation link that
         quietly became a signing link — or the reverse — would change what the
         reader is being asked to do without anybody deciding it. */
      /* holdUnsent: this refresh fires on DECISIONS — an answer to something
         already on their screen — and can run while the owner holds a draft
         they have not sent. A payload built here without the guard carried
         that draft to the counterparty's page: the one thing the whole turn
         model exists to keep home, leaked by a background sync. The explicit
         SEND path never sets this, because there everything pending is
         precisely what is being sent. */
      const payload=buildSharePayload(c, docHash, null, { purpose:s.purpose||undefined, holdUnsent:true });
      try{ await api('shares/'+s.token+'/payload','PUT',{ payload, silent:true }); }catch(e){}
    }
  }catch(e){ /* the record is right either way; the link catches up next time */ }
}

/* WHOSE MOVE IT IS, after they answer.

   The turn moved to the counterparty when the owner sent the round; nothing
   moved it back when the counterparty answered. So the owner's banner went on
   reading "Waiting on Nordfrakt Logistik AB" over a contract Nordfrakt had
   already replied to — the exact untruth the turn model exists to prevent, in
   the one direction nobody had walked.

   Handing back is what an answer IS. Ride negoHandOver, which is the same code
   the owner's own send uses, so a version is captured and the trail reads as a
   sequence of hand-offs either way. */
function negoTurnBack(c, who){
  if(!window.negoHandOver || !window.negoTurn) return;
  if(negoTurn(c)!=='counterparty') return;      // already ours; nothing to move
  negoHandOver(c, { to:'owner', by:who });
}

/* Answers to individual fingerprinted changes, applied through negoResolve so
   the wording is rebuilt by the same code the owner's own decisions run
   through. Shared by the 'decisions' and 'ready' actions, which differ only in
   what an empty result means: for 'decisions' it is a failed response, for
   'ready' it is a reader who had already sent their answers.

   A decision only ever lands on a change WE proposed. Their own asks are not
   theirs to rule on: that would let one side mark its own wording adopted and
   tell the other it was agreed. */
function applyNegoDecisions(c, r, who){
  const list=Array.isArray(r.negoDecisions)?r.negoDecisions.slice(0,200):[];
  const done=[];
  /* The identity that goes onto the decision is the honest one, not the typed
     one — see counterpartyActor. `who` is kept as the fallback so a response
     from before this existed still reads exactly as it always did. */
  const actor=(typeof negoActorLabel==='function')?negoActorLabel(r, who):who;
  for(const d of list){
    const ch=window.negoChangeById?negoChangeById(c,String(d.id||'')):null;
    if(!ch || ch.authorSide!=='owner') continue;
    if(d.status!=='accepted' && d.status!=='rejected') continue;
    if(negoResolve(c, ch.id, d.status, { side:'counterparty', by:actor,
      reply:d.reply||null })) done.push({ id:ch.id, status:d.status, reply:d.reply||null });
  }
  return done;
}

/* Asks of THEIR OWN that we refused and they have now let go. Only their own —
   withdrawing ours would let one side clear every objection raised against its
   wording and then declare the deal aligned.

   Lifted out of the readiness branch because both branches need it: a
   withdrawal is what clears the deadlock a single refusal creates, and it can
   travel with plain decisions just as easily as with a readiness signal. */
function applyNegoWithdrawals(c, r, who){
  const out=[];
  for(const id of (Array.isArray(r.negoWithdrawn)?r.negoWithdrawn.slice(0,200):[])){
    const ch=window.negoChangeById?negoChangeById(c,String(id||'')):null;
    if(!ch || ch.authorSide!=='counterparty') continue;
    if(window.negoWithdraw && negoWithdraw(c, ch.id, { side:'counterparty', by:who })) out.push(ch.id);
  }
  return out;
}

/* ---------- wording the counterparty asked for ----------
   The other half of a negotiation round, and the half that used to have no way
   home. Their room files a real change when they press Change on a clause; this
   is where it lands on the record.

   RE-FILED, never trusted. The draft arrives from a public, no-login page, so
   nothing about it is taken as evidence: the id, the fingerprint and the chain
   are all minted here by negoFileChange, exactly as they are for a change typed
   on this side. What travels is what they wrote and which clause they wrote it
   on. Their id is kept only in the log, so a support conversation can match the
   two up.

   `oldText` is read from OUR copy of the clause, not from theirs. A redline is a
   claim about what the wording currently says, and the record copy is the only
   thing entitled to answer that. */
async function applyNegoProposals(c, r, who){
  const list=Array.isArray(r.negoProposed)?r.negoProposed.slice(0,200):[];
  if(!list.length || !window.negoFileChange) return [];
  const filed=[];
  const unplaced=[];
  for(const p of list){
    if(!p || !p.clauseId){ if(p) unplaced.push(p); continue; }
    const type=p.changeType==='deleteClause'||p.changeType==='insertClause'?p.changeType:'modify';
    /* ---- FINDING THE CLAUSE THEY MEANT, AND SAYING SO WHEN WE CANNOT ----
       The id is the answer and is tried first. But an id can be stale — a link
       minted before clauseCarryIds existed carries ids our baseline has since
       re-minted — and this used to `continue` on a miss, in silence: nothing
       filed, applyResponse returned false, the poller never marked the response
       handled, and it re-applied the same impossible answer every cycle for
       ever. The counterparty's wording was simply gone, with no line anywhere
       saying so. So the miss is recovered from where it honestly can be, by the
       wording they were editing and then by the clause's own label, and
       RECORDED when it cannot. */
    let cl=window.negoClauseById?negoClauseById(c, String(p.clauseId)):null;
    if(!cl && type!=='insertClause' && window.negoClauseList){
      const norm=s=>String(s==null?'':s).replace(/\s+/g,' ').trim().toLowerCase();
      const clauses=negoClauseList(c)||[];
      const want=norm(p.oldText);
      cl=(want && clauses.find(x=>norm(x.text)===want))
        || (p.clauseLabel && window.negoClauseLabel
            && clauses.find(x=>norm(negoClauseLabel(x))===norm(p.clauseLabel)))
        || null;
    }
    if(!cl && type!=='insertClause'){ unplaced.push(p); continue; }
    const newText=String(p.newText==null?'':p.newText);
    /* Already here. A durable link can send the same round twice and the poller
       retries anything it could not mark applied, so the same ask must not
       become two fingerprints on the index.

       Matched on the RICH body too, when the proposal carries one: a
       formatting-only ask has the same text as the clause — and as any other
       formatting-only ask on it — so a text-only match would swallow a real
       proposal as a duplicate. Canonical comparison, so serialisation noise
       does not un-duplicate a genuine retry. */
    const canonB=h=>{ try{ return window.canonicalRich?canonicalRich(String(h||'')):String(h||''); }catch(_){ return String(h||''); } };
    /* OUR id for the clause, never theirs. Where the ask arrived on a stale id
       and was recovered by its wording above, filing it under the id they sent
       would anchor the change on a clause this contract does not have — the
       same invisible hole one step further along. */
    const clauseId=String((cl&&cl.clauseId)||p.clauseId);
    if((c.changes||[]).some(x=>x && x.authorSide==='counterparty' && x.clauseId===clauseId
        && x.status==='pending' && String(x.newText||'')===newText
        && (!p.bodyHtml || canonB(x.bodyHtml)===canonB(p.bodyHtml)))) continue;
    let ch=null;
    try{
      ch=await negoFileChange(c, { clauseId, changeType:type,
        oldText: cl?cl.text:String(p.oldText||''), newText,
        bodyHtml: p.bodyHtml?(window.sanitizeRich?sanitizeRich(p.bodyHtml):null):null,
        headingText:p.headingText||null, afterClauseId:p.afterClauseId||null,
        clauseLabel:(cl&&window.negoClauseLabel?negoClauseLabel(cl):p.clauseLabel)||null },
        /* why AND note, and they are not the same thing: `why` is the reason
           they typed for this ask and is what the card shows; `note` is
           provenance and stays internal. This re-filed with `note` alone, so
           even once the reason reached the server it was written into the
           field the card does not read. */
        { side:'counterparty', author:who, why:p.why||null, note:p.note||null, quiet:true,
          via:`their link${p.id?` as ${p.id}`:''}` });
    }catch(e){ ch=null; }
    if(!ch){ unplaced.push(p); continue; }
    filed.push(ch.id);
    logAudit(c,'Negotiation',`#${ch.id} proposed by ${who} through their link — “${ch.summary}”`
      +` on ${ch.clauseLabel||ch.clauseId} · fingerprint ${ch.hash}`
      +` (the counterparty's wording, recorded in their name${p.id&&p.id!==ch.id?`; their copy called it ${p.id}`:''})`);
  }
  /* WORDING THAT ARRIVED AND COULD NOT BE PLACED IS NEWS, not a no-op. It used
     to vanish: nothing filed, nothing logged, and the poller re-fetching the
     same response every cycle because it had never been reported handled. The
     text they wrote is kept verbatim in the trail, so the round is recoverable
     by hand rather than lost. */
  if(unplaced.length)
    logAudit(c,'Negotiation',`${unplaced.length} change${unplaced.length===1?'':'s'} proposed by ${who}`
      +` through their link could NOT be matched to a clause on this contract and ${unplaced.length===1?'was':'were'} not filed`
      +` — ${unplaced.map(p=>`${p.clauseLabel||p.clauseId||'an unnamed clause'}: “${String(p.newText||'').slice(0,300)}”`).join(' | ')}`);
  return filed;
}

/* poll the server for counterparty responses and apply them */
/* ---- A ROUND THAT WILL NOT LAND MUST SAY SO (owner-reported 23 Aug 2026) ----
   This loop had three silent holes, and they compounded into the worst shape a
   hand-off can take: the counterparty's page says "Sent", the owner's page
   shows nothing, and NOTHING ANYWHERE says why.

     · a response naming a contract this browser does not hold was skipped with
       `continue` — for ever, without a word;
     · applyResponse returning false left the row unmarked, so it was re-fetched
       and re-refused on every beat, silently, until the tab was closed;
     · and the whole loop sat inside one catch that swallowed everything,
       including a fault in the applying rather than in the network.

   RETRYING IS RIGHT AND STAYS. What was wrong is that it was invisible. So the
   retry is untouched and the SECOND consecutive failure on the same answer is
   reported, once per sitting — the second, not the first, because one miss is
   ordinarily a page that has not finished loading its contracts and crying wolf
   on that would teach the reader to ignore this box.

   IT WRITES NOTHING TO THE RECORD. An audit line would mean persisting a
   contract we have just failed to apply an answer to, which is the one moment
   not to be writing to it. The toast plus the standing retry is the whole
   report.

   THE NETWORK IS STILL SILENT, deliberately: a fetch that fails between beats
   is ordinary and the next beat fixes it. Only the applying speaks. */
const POLL_TROUBLE_AT = 2;
const _pollTrouble = new Map();   // answer key -> consecutive failures
const _pollTold = new Set();      // reported once per sitting, never nagged
async function pollPendingResponses(){
  if(!API_MODE() || !canEdit()) return;
  let list;
  try{ list=await api('shares/pending'); }
  catch(e){ return; }             // transient network — the next beat retries
  for(const item of list){
    const key=String(item.responseId||item.token||'');
    const c=getContract(item.response&&item.response.id);
    let ok=false;
    if(c){ try{ ok=await applyResponse(c, item.response, {background:true}); }
           catch(e){ ok=false; } }
    if(ok){
      _pollTrouble.delete(key); _pollTold.delete(key);
      // A durable link carries one row per round, so the acknowledgement names
      // the answer just applied. Marking the whole link applied would silence
      // every later round on it.
      try{ await api('shares/'+item.token+'/applied','POST',
             item.responseId?{ responseId:item.responseId }:{});
           refreshShareOverview(); }catch(e){ /* the row stays unmarked; next beat re-acknowledges */ }
      continue;
    }
    const n=(_pollTrouble.get(key)||0)+1;
    _pollTrouble.set(key,n);
    if(n>=POLL_TROUBLE_AT && !_pollTold.has(key)){
      _pollTold.add(key);
      const id=(item.response&&item.response.id)||'';
      const who=(item.response&&item.response.name)||'';
      /* 'warn', not 'err': nothing is lost and nothing was refused — the
         answer is safe on the server and this browser keeps trying. The action
         is the one thing that has been shown to clear it. */
      toast(i18t('co_answer_stuck',{ id:esc(id), who:esc(who) }),'warn',
        { action:{ label:i18t('co_answer_stuck_act'), onClick:()=>location.reload() } });
    }
  }
}
/* ---------- how often to look ----------
   Answers arrive by polling; there is no channel from the server that can tap
   this page on the shoulder. One fixed 45-second beat treated every situation
   the same, so someone sitting on the contract they have just sent out — the
   one case where the wait is the whole experience — watched a screen that could
   be three quarters of a minute out of date, with no reason to suspect it.

   Two cheap corrections, both using what is already here:

     · WATCH HARDER WHEN SOMEBODY IS WATCHING. While the open contract is with
       the other side, look every twelve seconds instead of forty-five. It costs
       one small request; it is the difference between "it just appeared" and
       "I had to reload".
     · LOOK WHEN THEY COME BACK. Returning to the tab is exactly the moment a
       person expects to be caught up, and it costs nothing to be right then.
       Rate-limited so alt-tabbing repeatedly cannot hammer the server. */
const POLL_SLOW=45000, POLL_FAST=12000;
let _pollTimer=null, _pollEvery=0, _pollLastAt=0;
function pollWaitingOnThem(){
  /* ---- THE NEGOTIATION PAGE IS A PAGE THAT WATCHES (owner-reported 23 Aug
     2026, MK-349) ----
     This asked `state.view!=='workspace'` — written when Negotiate was a TAB
     on the contract workspace, and never told when it became its own view on
     12 Aug 2026. So the one screen in the product built for watching a live
     round answered "nobody is waiting on anything" about itself, and sat on
     the slow 45-second beat while the reader watched it. Reproduced end to
     end: their round reached the server, the owner's page showed nothing for
     half a minute, and re-opening the page did not help either (see
     POLL_ON_ARRIVAL in js/app.js, the other half of this fix — the two lists
     must agree or the page catches up on arrival and is then not watched).

     WHICH CONTRACT, on that page, is redlineHeldId() and not state.activeId:
     the held id is the contract actually PAINTED, recorded on the paint, while
     activeId is a global that survives whatever was last opened anywhere. On
     the negotiations LIST it is null — several negotiations, no single one to
     be waiting on — and this answers false there, which is what the comment
     above the function has always claimed ("the open contract"). Read through
     `window`, because this module cannot see the negotiation view's own
     names. */
  if(state.view!=='workspace' && state.view!=='redline') return false;
  const id = state.view==='redline'
    ? (typeof window!=='undefined' && window.redlineHeldId ? redlineHeldId() : null)
    : state.activeId;
  if(!id) return false;
  const c=getContract(id);
  if(!c || c.status==='Signed' || c.status==='Declined') return false;
  if((c.rounds||[]).some(r=>r&&r.status==='open')) return false;   // it is OUR move
  const turn=window.negoTurn ? negoTurn(c) : (c.negotiation&&c.negotiation.turn);
  if(turn==='counterparty') return true;
  // or we have sent something and nobody has answered it yet
  return !!(c.negotiation&&c.negotiation.turnAt) || (Array.isArray(c.signatures)&&c.signatures.length===0
    && (Array.isArray(c.changes)?c.changes:[]).some(x=>x&&x.status==='pending'&&x.authorSide==='owner'));
}
/* A REPLY IS NOT A RESPONSE, and it arrives by a different door.
   pollPendingResponses collects answers that MOVE the negotiation — decisions,
   proposals, signatures. A comment on a fingerprint moves nothing and is
   deliberately not on that route, so a counterparty's reply reached the server
   and then sat there until the owner reloaded the page. On the one screen built
   for the conversation, that is the reply arriving late by exactly as long as
   the owner happens to stay put.

   Refreshed on the same beat, and only for the contract that is open: the
   messages belong to a screen somebody is looking at, and there is no reason to
   fetch a conversation nobody is reading. */
async function pollThreadMessages(){
  if(!API_MODE()) return;
  const c=state.contracts&&state.activeId?getContract(state.activeId):null;
  if(!c) return;
  try{
    const r=await api('contracts/'+c.id+'/messages');
    const next=(r&&r.messages)||[];
    const before=(c._messages||[]).length;
    c._messages=next;
    /* Repaint only when something actually arrived. A repaint on every tick
       would rebuild the room under the reader twice a minute — and take the
       reply box they were typing into with it. */
    if(next.length!==before){
      const painted=window.negoRepaintOpenRoom ? negoRepaintOpenRoom(c) : false;
      /* The WORKBENCH reads these threads too (rlCardNotesHtml), and it was
         not on this repaint list — so a counterparty note arrived in
         c._messages and the cards on screen never changed (Young, 10 Aug
         2026). Never while the reader is mid-sentence: a repaint rebuilds the
         composer and takes a half-typed note with it; the next tick catches
         up the moment they pause. */
      if(!painted && document.getElementById('view-redline') && window.renderRedline){
        const el=document.activeElement;
        const typing=el && el.tagName==='TEXTAREA' && String(el.value||'').trim();
        if(!typing) renderRedline();
      }
      else if(!painted && window.renderDiscussSection) renderDiscussSection(c);
    }
  }catch(e){ /* transient — the next tick retries */ }
}
async function pollNow(reason){
  const t=Date.now();
  if(t-_pollLastAt < 4000) return;      // never twice in four seconds
  _pollLastAt=t;
  await pollPendingResponses();
  await pollThreadMessages();
}
function schedulePolling(){
  const want=pollWaitingOnThem()?POLL_FAST:POLL_SLOW;
  if(_pollEvery===want && _pollTimer) return;
  _pollEvery=want;
  clearInterval(_pollTimer);
  _pollTimer=setInterval(()=>{ pollNow('tick'); schedulePolling(); }, want);
}

